/* 令和4年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r04.committeeSessions.push(...[{"id":"r04-20221101-9","meetingId":"r04-cm11","date":"2022年11月1日","dateIso":"2022-11-01","committee":"文教委員会","time":"午前１０時００分～午後 ４時４６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を95件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和４年特別区および東京都人事委員会勧告等","agenda":"令和４年特別区および東京都人事委員会勧告等","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"確認ですが、幼稚園教員のほうが、前段の特別区人事委員会の勧告で給与が変更されるということと、区固有教員のほうは、後段の東京都人事委員会の勧告が給与に影響するということでよろしいのか。それと、区固有教員以外の教員の方もこの東京都の人事委員会の勧告で変更になるのでしょうかという確認です。直近のその状況を数として教えていただきたいのと、あと、辞められる方の例えば経験年数の特徴など。","respondent":"中谷指導課長","answer":"例えば２０代の方もいらっしゃれば、４０代、５０代の方もいらっしゃるというような状況があります。精神的なものでお休みに入られる方というのは、年代的には本当に様々であると言えるかなと考えています。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり休職される方のうち、メンタルの面というのがほとんどだということなのですよね。だから深刻ですよね。数も少なくない数ですし。やはり職場改善をしていく必要があるなと思います。区内の数だと思うのですが、それが分からなかったので、これはどういう数なのかということと、あと、もし分かれば、３年間で退職されてしまった方は何人ぐらいだったのか。分かれば、教えていただきたいと思います。","respondent":"中谷指導課長","answer":"そのような状況です。もう一点補足します。先ほど、令和元年度から３年度までの３年間の病気休職の数字につきましては、東京都の教職員の数字です。","voiceIndex":7,"id":"exchange-002"},{"speaker":"田中委員","kind":"意見","question":"今回、若年層の給与だけ引上げということで、それはよかったなと歓迎したいと思いますが、比べる民間事業者との差額感というか。一般的に今そんなに給料が上がったという声が区民のほうから聞こえてこない中で、なかなか難しい。職員の方たちの給与が上がったことは本当に歓迎したいのですが。何だか難しいなと思いながら報告を聞いていました。まとまっていなくてすみません。","respondent":"中谷指導課長、矢部教育総合支援センター長","answer":"試行的な取組としましては、先生方の職員室での監督役でもある副校長先生もお仕事が非常に多いという背景もありますので、副校長補佐という形で、東京都の事業を活用しているものです。現在はまだ試行実施ということでやっております。学校現場の現状としましては、やはり校長を中心に雰囲気づくりというのは、これまでどおり進めてまいります。私たちが持っている研修会は、若手研修、３年目ぐらいまでの先生たちをお呼びしてやっています。","voiceIndex":12,"id":"exchange-003"},{"speaker":"田中委員","kind":"質問","question":"結構１人で抱え込んでしまって、子どもへの教え方なども誰に相談したらいいのだろうと悩んでしまっているという声も聞かれていたので、今、でも改善に向けて様々されているということが分かりました。もしお答えいただけたら、副校長補佐の試行実施というのが、今、何校ぐらいで、いつからやられているかということだけ教えていただけますか。","respondent":"中谷指導課長","answer":"副校長補佐の試行実施ですが、現在、小学校で１校、中学校で１校、ちょうど開始したところになります。１０月１日から荏原第五中学校、１１月１日から立会小学校で試行実施をしております。","voiceIndex":15,"id":"exchange-004"},{"speaker":"若林委員","kind":"質問","question":"教えてください。人事委員会と東京都、いずれも初任給であるとか若年層、初任層というところの改定となっていますが、ここら辺をどのように理解したらよいか。区としてこれをどのようにして反映していくかというものはお聞かせいただけますでしょうか。","respondent":"中谷指導課長","answer":"勤勉手当につきましては、０.１月分が引き上げられることに伴いまして、引上げ分を加えた形で、管理職を含めた全員が該当するということで、１２月の勤勉手当にて支給ということを予定しております。","voiceIndex":19,"id":"exchange-005"},{"speaker":"若林委員","kind":"質問","question":"いわゆる意見が載っていて、人材確保みたいなところがちらっと見えますが、特段、初任層とか若年層という表記はあまり見られませんでした。すみません。意見とポイントがあまり合致しないなというのが率直な感想なのですが、何かお話を聞いてくださったのですか。もう一つ、若年層というのは、年齢で言うとどこら辺で線引きするのか、教えてください。","respondent":"中谷指導課長","answer":"そのほかのものにつきましては全ての方々をということで、公民比較ということでやっておりますので、その２つに分けて比較しております。","voiceIndex":21,"id":"exchange-006"}]},{"id":"topic-02","title":"令和４年度（５年度採用）品川区立学校教育職員採用候補者選考状況","agenda":"令和４年度（５年度採用）品川区立学校教育職員採用候補者選考状況","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"去年のご説明ですと、去年３名採用しますということで、その目標のとおり３０名に達するということでしたが、今年はなぜ４人の採用になるのでしょうかと。４人辞めてしまったのですかということですね。２年前は、一次申込みの時点で６１名いたのです。それが２０名ということです。そこら辺について、なぜこんなに減ってしまったのだろうと、どのように分析しているのでしょうか、伺います。","respondent":"中谷指導課長","answer":"そういった声をかけてくださる大学のタイミングを逃さず、学生たちに引き続きアプローチをかけていきたいなと考えています。","voiceIndex":29,"id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"そこら辺に目を向けていただきたいなと思います。だから空きが４名という理解でよろしいのかというところを質問したいと思います。この区独自教員は３０名を目標としています。こうした現場での要望、柔軟な措置を行っているのはここだけだと思いますが、となると３０名も雇うのに、今２６名ですか、そのうち１名は三木小学校で活用されていると。そこら辺をちょっと伺いたいなと思います。","respondent":"中谷指導課長","answer":"近々ケーブルテレビなどを用いて、何が先生として楽しいか、どういう仕事に魅力があるかというようなところを発信できるような取組を企画して実施していきたいなと考えています。今年度４名募集したということについてです。","voiceIndex":31,"id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"三木小学校の話をしましたが、私がちょっと伺ったのは、３０人を目指して２６人採用していって、そのうち１人はそういう使い方をしているのに、２５名の方は一体どこへ行ってしまったのかなというか。クラスを持っているのでしょうけれど、その分、市民科専門の人がいるのですか。実際に三木小学校の３年生はそういうことでやっているのですが、その現状を見ていると、１年生はやはり大変ではないですか。","respondent":"中谷指導課長","answer":"当然その教科をどういった学級形態でやっていくかという検討は、まず学校長がその者とどうしていくかを検討した後に、こうしたいというような具体的なイメージをつくり、そして教育委員会に申請するという理屈になっております。","voiceIndex":33,"id":"exchange-009"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりました。現場で求められている、あるいは実際の子どもたちや保護者が求めている形で独自教員を活用していくところがあるわけですね。そういう申請があった場合にはぜひ広く検討をしていただきたいですし、これを実際に広げてもらえたらなと思います。すみません。三木小学校のような活用の仕方をしているのは、三木小学校しかないのでしょうか。小中学校でほかにあれば。伺って終わりにします。","respondent":"中谷指導課長、勝亦学務課長","answer":"基本的には、固有教員の活用の仕方というのは先ほど申し上げたとおりになるので、そのもっとミクロな部分だと思いますが、例えばＩＣＴや市民科を担う以外の学級編制というところまでは。学級編制上におきまして、固有教員を少人数学級に充てていますのは三木小学校のみという状況になってあります。","voiceIndex":35,"id":"exchange-010"},{"speaker":"田中委員","kind":"意見","question":"すみません。今の加配の部分で三木小学校のみの加配ということでしたが、三木小学校が選ばれた理由というか、どういった経緯で加配になったのか。私も加配については、先生たちの負担を軽減しますし、子どもたちのためにも必要だと思うので、ちょっとそこの部分をお知らせいただければと思います。","respondent":"勝亦学務課長","answer":"こちらの加配といいますか、現在、三木小学校の３年生が６１人ということで、通常ですと２学級の状態ですが、３学級で編制しております。こちらについては、特別に配慮を要するお子さんがいるということで、３学級の編制にしているという状況です。","voiceIndex":40,"id":"exchange-011"},{"speaker":"田中委員","kind":"質問","question":"その場合は、特別な支援が必要な子がいたために校長から申請があって、加配というかそこに行くということになるのか。その手続を教えていただけますか。","respondent":"勝亦学務課長","answer":"学校から申請をいただきまして、学級編制のほうが細かくできるか、また、人員が充てられるか、指導課と連携しながら決定しているものです。","voiceIndex":42,"id":"exchange-012"},{"speaker":"渡部委員","kind":"質問","question":"本当に数字のことで申し訳ないのですが、今の議論の中で、２６名。取りあえずの母数というのは、今２６名でいいのかどうかということと、２６名のうち校長はいなかったと思うのですが、副校長先生が何名、主幹が何名、主任が何名、一般教諭が何名というところまでちょっと教えてほしいなというところで、現状の数字を聞かせてください。その辺も数字が分かったら教えてください。","respondent":"中谷指導課長","answer":"義務教育学校には８名を配置しております。免許の内訳です。小学校の免許を持っている者が１６名、中学校に関しましては、国語が３名、社会が８名、数学が３名、理科が２名、保健体育が５名、英語が７名、特別支援教育が５名、美術科が１名となります。","voiceIndex":46,"id":"exchange-013"},{"speaker":"渡部委員","kind":"質問・要望","question":"先に質問をちょっと続けします。これもいよいよ３０名全員ということで、私自身も何度も、これは別に３０人で限ることなくと言っていましたし、品川区の教員の方にいろいろご活躍いただきたいし、例えば校長先生にもなってほしいというのは、もうかねてから質問のたびに言わせていただいています。そこをしっかり持っていないと、議論がどんどんおかしな方向に行ってしまうと思います。","respondent":"中谷指導課長","answer":"今現在そのものを担っている者はいないのですが、同じ６級職というところは変わりはないのですが、名称がやはり校長という名称をつけることができないというのが、昨年まで東京都教育委員会とずっとやり取りを交わしてきた中での今の時点でいただいている結論です。","voiceIndex":50,"id":"exchange-014"},{"speaker":"渡部委員","kind":"質問・要望","question":"しっかりと、やはりその学校を任せて、お願いできて、校長先生になってほしいなというのを、やはりずっと僕は思っていますし、そういう制度に変えていただきたいなと思うのですが、私たちができることではないので残念なのですが、よく分かりました。そういうこともしっかりやっていただきたいというのは、そこは要望にしておきますが、再任用のところだけちょっとお聞かせください。","respondent":"中谷指導課長","answer":"今現時点で再任用されている方はもちろんいらっしゃいませんが、１０年スパンで見たときに、これに関して、ご自身のキャリアを検討というか考え直す必要があるという方がいらっしゃいます。そういった経緯で、今回規定をさせていただいたというところがあります。","voiceIndex":52,"id":"exchange-015"},{"speaker":"渡部委員","kind":"質問・要望","question":"３０人になったから採りませんではなくて、やはりこれまでの間、採用事務を品川区としてやってきているわけですから、そこに関しても区の教育委員会事務局の中でもノウハウが蓄積されてきていると思うのです。３０人に欠けたから１人採用ですというのでなくて、本当に優秀な人材をこれから採っていくのだというような姿勢で。そういう施策の推進をしていただきたいと要望します。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-016"}]},{"id":"topic-03","title":"SHINAGAWA ICT SYMPOSIUMの開催","agenda":"SHINAGAWA ICT SYMPOSIUMの開催","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"今の最後のご説明ですと、区民の方だったら誰でも午後のオンライン配信が見られるということでよろしいのかという確認です。講演のタイトルやディスカッションのタイトルもありますが、この人選の理由をちょっと伺いたいのですが、区教委としては、こちらの方々に何を期待してお呼びしたのでしょうか。伺いたいと思います。","respondent":"中谷指導課長","answer":"これまで令和３年度品川区ＩＣＴ効果検討委員会の委員を務めていただくほか、教育委員会で主催しております教員を対象としましたＩＣＴの研修会で長らく講師を務めていただいております。","voiceIndex":59,"id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"理由は分かりました。私、この姿勢が大事なのではないかと思うのです。皆で考える上では、こうしたＩＣＴの限界あるいはリスクについても含めて、私は考えるべきだと思います。それは意見として述べさせていただきたいと思います。質問です。主なテーマというところに、それぞれ３つのポチがあります。現状での区教委としてのそれぞれの成果と課題については、どのように捉えているのか、伺いたいと思います。","respondent":"中谷指導課長","answer":"そういった活用をもっと広めていきたいという思いを持っております。まだまだ一部での活動という認識でおりますので、こちらについては、実践されている学校の取組を広げていきたいと考えています。最後の家庭における活用状況です。","voiceIndex":61,"id":"exchange-018"},{"speaker":"田中委員","kind":"確認","question":"ＩＣＴシンポジウムというのは、品川区以外の自治体でもやられているのかということをまず確認したいのと、確かに成果も様々あったとは思いますが、しかしやはり課題も大きく見えているところがあるということは、保護者の一人としても感じています。今ほかの自治体でもこういったシンポジウムが開催されているのかということと、課題についてのお話を伺えればと思います。","respondent":"中谷指導課長","answer":"シンポジウムの開催に向けては、リハーサルも１か月前から行っておりまして、十分にいろいろなことを考え、構築した上での本番を迎えていきたいなと考えています。","voiceIndex":65,"id":"exchange-019"},{"speaker":"田中委員","kind":"確認","question":"後でＩＣＴ教育についてというところもあるので、そこでお話しすべきなのかちょっと悩んで、シンポジウムのほうで話してしまいました。私としては、やはり誰でもオンラインで受けられる状況はあっていいのではないかなと思いますが、そこの部分について確認させていただいてもよろしいですか。","respondent":"矢部教育総合支援センター長","answer":"ただ、現状、コロナのことや体調不良で教員のほうが全てに対応できない場合もあるので、それはそれぞれ学校にご相談いただいて、私どもが伝えていることは校長も認識しておりますので、ぜひご相談いただきたいと思います。","voiceIndex":67,"id":"exchange-020"}]},{"id":"topic-04","title":"令和４年度品川区学力定着度調査および令和４年度全国学力・学習状況調査の結果","agenda":"令和４年度品川区学力定着度調査および令和４年度全国学力・学習状況調査の結果","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"正答率とありますが、要するに１００問問題があるとすれば、その中で何問正答したかという割合のことなのでしょうか。いわゆる点数ですと、問題ごとに異なる点数が配分されて、トータルで１００点という点数なのですが、その点数とどう違うのかというのをちょっと伺いたいと思います。それぞれどこなのか。ちょっと分からないのですけれど、伺いたいと思います。そこら辺をちょっと伺いたいと思います。","respondent":"中谷指導課長","answer":"つまり１０人の方が受けていて３人の方が正答すれば、３割る１０というような割合で出てくるものが正答率です。そういう意味で申し上げますと、全員が正答すれば１００％というものです。３つ目の業者につきましては、今回、東京書籍に問題を委託という形で実施しております。","voiceIndex":73,"id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"もう国語と数学と英語にすごく力を入れてしまっていて、ここら辺がおろそかになっているということはないのか、伺いたいと思います。それが質問です。それと、全国の３枚目のほうの右下の８番のところ。同じ授業をやっていて、同じクラスの中で子どもによって使用率が違うということはないと思うので、これはつまり学校ごとにＩＣＴ使用頻度の格差があるということなのでしょうか。伺いたいと思います。","respondent":"中谷指導課長","answer":"３点いただきました。１つ目は、全国学力・学習状況調査の業者というところです。こちらは文部科学省が実施しており、国立教育政策研究所で主に作成しているものです。","voiceIndex":75,"id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"予想します。区の調査ですが、品川区と全国を比べているではないですか。全国版でやっているということなのですか。なぜ全国が出てくるのかというのがちょっと分からなかったので、これは伺ってお答えいただきたいです。３枚目の８番の右下のところについてです。全く真逆なのです。ですから、私は、この結果をもってタブレットをさらに活用する口実に使うべきではないと思いますが、いかがでしょうか。","respondent":"中谷指導課長","answer":"やはり年齢に応じて、学年に応じてＩＣＴのタブレットをどういうふうに使っていくかということを具体的に研究していくことが非常に大事かなと思っています特に中学生、義務教育学校後期課程のお子さんたちが、技術的には使い方には慣れているけれども。","voiceIndex":77,"id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"だから、コンピューターを使うとき、探求的な学びにどう役立つかというところで使うべきだし、コンピューターを使うがあまり、そういう顔を突き合わせて行う協同的学びの時間が削られるとか、あるいは追いやられるということがあってはならないので、こういう結果を単純に促えて運用しないでほしいということを改めて要請します。競争でないと言うのだったら、なぜ学校ごとの結果を渡しているのでしょうか。","respondent":"中谷指導課長","answer":"先ほど申し上げたような社会の授業をどうしていくかということや、理科の様々に答えられていない、誤答が多い、また無回答が多い状況をどうしていくかというようなことは、傾向としてやはり出ておりますので。","voiceIndex":79,"id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"それなら、なぜ、あなたの学校は区の平均と比べてこうですよとか、あるいは学校ごとに結果を渡しているのかなというのが理解できませんけれど、そういうことをすることによって、学びの動機が各現場、各学校ではテストの点数をどう上げるかというようなことを目的に動かざるを得なくなってしまうというところなのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-025"},{"speaker":"田中委員","kind":"質問","question":"品川区学力定着度調査の結果についての１枚目の７番、課題の見られる問題例のところで、四角に囲った正答の部分についてです。個々のつまずきの箇所に注意する必要があるとありますが、この個々というのは、子どもたちの一人ひとりという意味なのか。そして注意する必要があるのは誰なのかというところを教えていただいてもよろしいですか。","respondent":"中谷指導課長","answer":"ご質問の資料１枚目の７番の課題の見られる問題例というところの解説文になろうかと思います。個々のつまずきというのは、こちらの場合、生徒一人ひとりのつまずき。","voiceIndex":83,"id":"exchange-026"},{"speaker":"田中委員","kind":"質問","question":"ここの内容はそうだと思っています。この下の右を向いた黒い三角の指している「８年生理科は」から始まる文章の中でも、「９年生でも目標値を下回り、基礎・基本的な知識・技能の定着や主体的に学習に取り組む態度が課題である。そこを補うための工夫が必要なのではないかといった声が聞かれるのですが、今どういった工夫がされているかというところをお知らせいただけたらと思うのですが、いかがでしょうか。","respondent":"中谷指導課長","answer":"先ほどのご質問にあったような、協働的な学びという時間と、それが終わった後に個として１人で振り返って考える時間と、しっかりそういったバランスの取れた授業を展開していくことがやはり力をつけていく上では大事であるという方向性を思っております。","voiceIndex":85,"id":"exchange-027"},{"speaker":"田中委員","kind":"質問・要望","question":"先生たちが子ども一人ひとりのつまずきに気づきにくい状況があることから、やはり加配などで先生をフォローして、子どもたちもフォローできるような態勢もやはりこれからもつけていかないと、学力の定着というか基礎の知識がつかないまま、分からないところが分からないまま学年が上がっていってしまうということがあるので、ぜひそういった考え方を進めていただけたらなということを要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-028"}]},{"id":"topic-05","title":"令和３年度指定管理者による管理に対するモニタリング・評価の結果について令和３年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"令和３年度指定管理者による管理に対するモニタリング・評価の結果について令和３年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今年はマイナスのところはないですね。差引収支というのがマイナスになった場合というのは、それはもう事業者の持ち出しになるということでよろしいのか伺いたいのと、Ａグループの令和元年度と令和３年度の人件費と指定管理料を見ますと、ちょうど人件費の増額分が指定管理料の増額分とほぼ同じように見えるのですが、人件費というのはなぜ上がったのか。伺います。","respondent":"吉田品川図書館長","answer":"１点目の令和２年度におけるＡグループのマイナスの部分です。こちらにつきましては、事業者の持ち出しということになります。２番目の人件費の増につきましては、この間の最低賃金の上昇や指定管理者のほうの従業員の昇級等を含めまして、人件費の増がかかったものです。","voiceIndex":92,"id":"exchange-029"},{"speaker":"安藤委員","kind":"質問","question":"そこら辺どうなのかというのをちょっとお伺いしたいと思います。第三者の意見というのが入っていますが、第三者の意見というのは、誰がどのように評価しているのでしょうか。伺います。利用者の満足度調査という記載があります。全部言ってしまいますが、有資格者の配置状況についてですが、Ａ、ＣグループとＢグループではちょっと違う感じなのですが、その違いはなぜなのでしょうか。伺いたいと思います。","respondent":"吉田品川図書館長","answer":"賃金アップにつきましては、指定管理につきましては５年間指定管理を行うことを前提で契約を行います。そのために、５年間の賃金上昇分を見込んだ形での見積り等を出していただいております。それを年度ごとに金額として協定を結んで履行しております。","voiceIndex":94,"id":"exchange-030"},{"speaker":"安藤委員","kind":"質問","question":"そういった面からも、区が直接雇用でやるのがいいのではないかなと私は思っています。説明でちょっと分からなかったのが、最後１点だけ。第三者意見と利用者満足度調査というのは、同じということですか。企画調整課で利用者の満足度調査を委託していますという話がありましたが、そこがちょっと分からなかったので、お伺いします。","respondent":"吉田品川図書館長","answer":"実際としては、内容としては同じものになります。ただ、８月に取ったアンケートに基づいて分析するという形になりますので、最終的には内容としては同じものになります。","voiceIndex":96,"id":"exchange-031"}]},{"id":"topic-06","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと資料についてお伺いしたいのですが、各学校での活用の様子というところの写真の右から２番目の撮影した動画を活用しての対話というところがありますが、これはどういう感じなのか。品川区の場合は、東京都や全国に比べて「ほぼ毎日」や「週３回以上」がかなり多いと思いますが、なぜこのようになっていると品川区は分析しているのでしょうか。伺いたいと思います。","respondent":"中谷指導課長","answer":"３番目のご質問で、タブレットの活用の頻度が全国や東京都と比べて非常に高いと。なぜここまでたどり着けたかというところですが、やはり１つは、研修をずっとやってきた成果というのがあるかなと考えています。","voiceIndex":104,"id":"exchange-032"},{"speaker":"安藤委員","kind":"質問","question":"動画を活用しての対話というのはよく分かりました。ちょっと最後の質問のところですが、数字上、品川区の場合はタブレット使用がかなり多いと思うのです。例えば教育委員会として、必ずこれぐらいは使ってくださいねという指導や指示というのはあるのか、ないのか。そこら辺を伺いたいと思います。","respondent":"中谷指導課長、矢部教育総合支援センター長","answer":"そういった面で言いますと、品川区はＷｉ－ＦｉとＬＴＥと両方でやっておりますので、安定したインターネット環境が構築できているのかなと。そこもやはり使用が進んでいく一つの要因なのかなと考えております。授業の中で毎日使っていますが、時間は何分ということは書いてありません。私たちが見ている中で、１時間授業の４５分、５０分を全てＩＣＴを使って授業しているというのは見たことがありません。","voiceIndex":106,"id":"exchange-033"},{"speaker":"安藤委員","kind":"質問・要望","question":"ネット環境についてもかなりきちんと相当なお金もかけているということだとは思いました。アクティブラーニングというキーワードがありますが、やはりこれから必要な学びとか学力というのは、これからはどんどんＡＩに取って代わられる時代になっていくという指摘もあります。そういうことのためにタブレット等は活用していただきたいと思います。それは意見として申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":109,"id":"exchange-034"},{"speaker":"田中委員","kind":"質問","question":"取組の中のＩＣＴ活用推進の中の活用状況調査の実施というのがあります。その調査内容を伺いたいのと、ヘルプデスクの活用とありますが、具体的にどういったことなのかということをお知らせください。","respondent":"中谷指導課長、勝亦学務課長","answer":"ＩＣＴ活用状況調査について、まずご説明申し上げます。こちらにつきましては、令和３年度の時点の品川区立学校におけるＩＣＴ活用状況を独自に調査しております。内容といたしましては、実際に使っている中でのトラブルの対応や問合せ、使い方への対応、それから障害への対応または故障の対応等々、技術的な支援といったものを電話・メール等でしているものです。","voiceIndex":111,"id":"exchange-035"},{"speaker":"田中委員","kind":"確認","question":"先ほど私が事例として挙げた、例えば学校を休んだときの授業の受け方の状況についても、長期休暇以外のときでも活用できている学校とできていない学校があるということは、区教委としても把握はできているということでよろしいのかという確認をさせてください。市民科デジタル化ですが、これから教科書をデジタルにしていくということなのですか。","respondent":"勝亦学務課長、矢部教育総合支援センター長、中谷指導課長","answer":"こちらはｉＰａｄのリースをＮＴＴドコモからしておりまして、その契約の中でヘルプデスクを開設していただいているもので。市民科の教科書につきましては、全てのお子さんのｉＰａｄの中に市民科の教科書をデジタル化したものを１０月から導入しています。先ほどの活用状況調査の質問項目ですが、ご指摘いただいた休み中の授業の受け方というところについては、今回。","voiceIndex":114,"id":"exchange-036"},{"speaker":"田中委員","kind":"質問","question":"市民科デジタル化のところで、市民科に限らずほかの教科書もデジタルにしてきた、しているということではないのですか。先ほど学校には呼びかけているということでしたが、学びの機会の確保ができるように、できない学校の場合にはなぜできなくて、どういうフォローが必要かといった各学校の状況もくみ取っていただけたらと思うのですが、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"学校はかなりそれぞれ工夫をしていて、持ち帰るものと置いていっていいものと分けている。学年によって変えたり、また、お子さんの体格やご家庭のお考えもあるので、個別には対応していると認識しております。ＩＣＴの対応につきましても同様です。","voiceIndex":118,"id":"exchange-037"},{"speaker":"田中委員","kind":"質問","question":"市民科のデジタル化については、子どもたちのタブレットに入っていることも、ほかの教科も英語からというのは分かりました。本当に本が必要になるかどうかはこの先の判断ということでした。そういったこともちょっとお知らせいただければと思いますが、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"データですので、ホームページに上げるかどうかというのは技術的にはできるかもしれません。それも中身の検討や活用方法をきちんと検討してから進めてまいりたいと考えています。","voiceIndex":120,"id":"exchange-038"},{"speaker":"渡部委員","kind":"質問","question":"大勢の先生がいらっしゃる中で、この人のやり方は面白いな、すごいなというのは、映像化されるか何かして、ほかの教員の方々に事例集のように共有がなされていて、ほかの方々が活用できるような仕組みになっているのかどうかということを教えてほしいです。一点は児童・生徒の側の話です。ちょっと気になっていたので教えてほしいです。もう一件伺います。例えば因数分解は大事なものではないですか。","respondent":"中谷指導課長","answer":"こういう授業をやったら、子どもたちがこのように変わったということが分かる優良事例をためて、事例集を作って共有できるように、教育委員会として進めていきたいと考えております。","voiceIndex":123,"id":"exchange-039"},{"speaker":"渡部委員","kind":"質問・要望","question":"特に課長から最後にご説明いただいたところというのは、せっかくタブレットを持っているわけですから、家庭教育に持ち込んで、保護者と一緒になってそういうのを進められる仕組みができると、今の保護者は、相当一緒になってやってくれるのかと思ったりもしています。品川区の子どもたちですから、そういうところは大丈夫なのかなと思いつつ、やはりどこかちょっと一抹の不安があります。すみません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":125,"id":"exchange-040"},{"speaker":"若林委員","kind":"質問","question":"コンパクトな資料ですので、ＩＣＴ教育は、なかなか現場を見ることもふだんありませんので、ご説明のないところをちょっとお聞きしたいと思います。家庭との連携というのは、今までの質疑で、さっきの話のことなのかどうなのかも含めて、ちょっとコメントをいただけますか。はまとめて、ＩＣＴ活用重点校が小学校１校、中学校が２校と。そこら辺の重点校についてのお話もお願いいたします。","respondent":"中谷指導課長、勝亦学務課長","answer":"そういった中で、ロイロノートの活用ということも含めて、それぞれの学校で進めていただいているという状況です。各種アプリの活用導入のところについて、お答えいたします。防災アプリ等々です。","voiceIndex":127,"id":"exchange-041"},{"speaker":"若林委員","kind":"質問・要望","question":"課がもう違うのですね。なるほど。分かりました。取りあえずお話を伺いました。重点校のお話は、今度の１１月３０日のシンポジウムを含めて確認をしたり、また、今後の展開にということで楽しみにさせていただきたいと思います。はここに出てこないものとして、これは特別支援教育にはどういうふうに活用されているのか、されていないのか。ちょっとここは、現状も含めて方向性をお聞かせいただけますか。","respondent":"矢部教育総合支援センター長","answer":"特別支援教育につきましては、特別支援学級には特に２人に１台、これまでも使っておりました。この導入に際して１人１台になりました。基本的なアプリは同じなのですが、お子さんに合わせてそれぞれアプリが替わっている場合があります。","voiceIndex":130,"id":"exchange-042"},{"speaker":"若林委員","kind":"質問","question":"今のお話だと、自然な流れの中で各学級、先生で活用して、こんなアプリもあんなアプリも活用できますよというふうにどうしてもちょっと聞こえてしまったので、今後の力の入れ具合、また、どこら辺が課題になるのかというのは、教えていただいて。教室は通常学級との関連がありますが、特別支援教室はどういうふうに立て分けているのか。使い方をちょっと、教室についてのコメントをいただければ。","respondent":"矢部教育総合支援センター長","answer":"特別支援教室は、基本的に持っている子が、例えば１年１組のお子さんが木曜日の２時間ぐらいお出かけしていくので、その場合使わないときもありますし、それがとても有効だということが分かれば、また落ち着いた自立活動に向けて有効だということが分かれば持って行って。","voiceIndex":132,"id":"exchange-043"},{"speaker":"若林委員","kind":"確認","question":"なるほど。聞いてみないと分からないですね。そういうふうに両課でしていただければいいかなと思います。特別支援学級は、通常教室と特別支援教室の２つの教室を往来している中で、通常学級の先生と特別支援教室の先生の授業の振り返りや確認、連携という意味でのタブレットの有用性というのは、何かあるのか。ありそうな気がしますが、いかがでしょう。","respondent":"矢部教育総合支援センター長","answer":"担任は授業中ですので、離れているその場面をなかなか見ることができないので、放課後などにそのノートを共有して、保護者と情報共有しています。ＩＣＴを使うということであれば、その辺りです。","voiceIndex":134,"id":"exchange-044"},{"speaker":"若林委員","kind":"質問・要望","question":"ありがとうございました。人数で言うと、通常は大きくて特別支援は小さいということに当然なるわけですが、さっきありましたように一人ひとりのニーズという意味でいけば、特別支援教育のそもそもの意味がそういうことですので、しっかりと研究、また取組を進めていただきたいなとお願いをして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":136,"id":"exchange-045"},{"speaker":"松澤副委員長","kind":"質問・要望","question":"ＩＣＴというものが導入されて、もう１年半たったのですね。その中で、ＬＴＥモデル。要はＷｉ－Ｆｉの環境がなくてもできますよというのが本当に売りで、Ｗｉ－Ｆｉ環境がない子どもにもこういう学びを閉ざさないという品川区の姿勢に改めて感謝するとともに、このＬＴＥの使用状況というのですか、電波状況。利用状況というのがちょっと分かったら教えていただきたい。それを教えていただきたい。","respondent":"勝亦学務課長","answer":"ただ、全体の平均をしますと２ギガバイト程度の使用になっているのですが、中には修学旅行にｉＰａｄを持っていって学習に活用するといった使い方もできておりますので、非常に有効な活用ができていると感じております。","voiceIndex":138,"id":"exchange-046"},{"speaker":"松澤副委員長","kind":"質問","question":"これからのＩＣＴ向け。でも、スタートして１年半。だからこそ、２年目に向かうときに、そのＩＣＴを、どういう授業にいかすかというのは、この取組にも書いてありますが、とても大事なことだと考えています。そういった先生をどう守ってあげるのかというのが、これから２年目に向かうＩＣＴ教育の課題の一つでもあるかなと私自身は思います。学びをどう持っていくのかというのをちょっと教えてください。","respondent":"中谷指導課長","answer":"校務での支援をきちんとデジタルを活用していくことで、ＩＣＴを活用していくことで、今まで時間がかかっていたことがスムーズになるようなところをしっかり整えていきたいなと思います。","voiceIndex":140,"id":"exchange-047"},{"speaker":"松澤副委員長","kind":"質問","question":"ちょっと聞きたいのは、ＩＣＴ支援員というのが、要は学校の勉強の仕方を教えてくれる方向性でありますから、なかなかこのＩＣＴ支援員の活用というのは、先生の学びとイコールになっているかちょっと分かりませんが、先ほどおっしゃっていただいたように、聞くことのできない先生も出てくると思うのです。聞くことが恥だと思ってしまうというのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":142,"id":"exchange-048"},{"speaker":"田中委員","kind":"質問","question":"ごめんなさい。１点だけ。ちょっと設備のほうですが、プロジェクターや教師用パソコンなど様々ある中で、以前、予算特別委員会かどこかでも質問したと思いますが、先生用のマイクについてです。でも、こうやってＩＣＴを進めていくというのであれば、やはり専用のマイクというのは絶対必要だと私は思いますが、区教委としてはどのようにお考えかというところを１点だけお知らせください。","respondent":"勝亦学務課長","answer":"専用のマイクがあればクリアな音声でというところは理解できますが、そういった周辺機器につきましては、各学校に消耗品を購入する予算を配分していますので、授業の状況等に合わせてご対応いただきたいと考えております。","voiceIndex":144,"id":"exchange-049"}]},{"id":"topic-07","title":"その他(1)所管質問","agenda":"その他(1)所管質問","exchanges":[{"speaker":"田中委員","kind":"質問","question":"１０月２７日の高橋しんじ議員の教育・子ども施策についてです。廃園を区教委で行わなかったのか。昨日の議論も含めて質問をしてしまうと、越権行為ではないかということに対しての答弁が明確でなかったのは伺いたいことの１点です。運営事務がどこまでを指しているのかということと、決定権まで委任ができるのが補助執行なのかという部分について伺いたいと思います。","respondent":"勝亦学務課長","answer":"こちらにつきましては、保育園のニーズの高まりや区立幼稚園の入園状況を踏まえて、区では令和３年度よりこども未来部と教育委員会が連携し、プロジェクトチームを立ち上げまして、区立幼稚園の今後の在り方等について検討を重ねてきたものです。","voiceIndex":148,"id":"exchange-050"},{"speaker":"田中委員","kind":"質問","question":"越権行為ではないといったことでしたが、そうですかというところです。教育長は、ここで協議して内容の是非を問うということにはならないかと思うとして、ほかの委員の方たちの意見を促しているのですが、１回報告事項で上がった伊藤幼稚園の閉園に向けた方針というのが、もう一度教育委員会で諮られて結果が出ていくのですかという、この手順もちょっと不思議なのですが、そこもお知らせいただけますか。","respondent":"勝亦学務課長","answer":"プロジェクトチーム、検討委員会の中での様々な意見があったというお話に関してです。","voiceIndex":151,"id":"exchange-051"},{"speaker":"田中委員","kind":"確認","question":"ただ、話の結論。教育委員会は、早過ぎるとストップをかけていたのです。大変だっただろうなということです。区教委で区立幼稚園の状況については８月２３日に報告が上がって、是非を問う場所ではないですということで報告をしているのですが、再度、条例変更をするために、もう一度区立幼稚園についてということが教育委員会で審議されるのですかという確認をしたいのですが、明確に教えていただけますか。","respondent":"勝亦学務課長、宮尾庶務課長","answer":"幼稚園廃止を行う場合、必ず幼稚園の条例の中で廃止というものが必要になりますので、必ず教育委員会のほうにこちらの条例改正について議論いただき、議決をいただいた後、議会に条例改正の提案をするという形になってあります。すみません。教育委員会の権限というところで、ちょっと私から答弁をさせていただければと思います。地方教育行政の組織及び運営に関する法律の第２１条の中に、教育委員会が職務権限として行うべきものが明記されております。","voiceIndex":153,"id":"exchange-052"},{"speaker":"田中委員","kind":"質問・要望","question":"補助執行している中身を教えていただいてもよろしいですか。いつから補助執行しているのか。昨日、平成元年からと言われましたが、ちょっと明らかではなかったので、そこを教えていただきたい。一番最初に子ども、そこに通っている子どもの保護者、地域にもきちんとした説明がないままに進んでしまった今回の手続の進め方について、教育委員会としてどう受け止めているかというところも伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":157,"id":"exchange-053"},{"speaker":"若林委員","kind":"質問","question":"冒頭の田中委員の質問は、今日、初めて補助執行という言葉が出てきましたが、法律に基づいて教育委員会の権限がどこまであるのか。逆に保育課に、区長部局のほうにどこまで許されるのかという質問だったはずです。ですので、今の拙速だったということは、今日の質問にはそもそも入っていなかったので、それを踏まえて進行していただければと思います。高橋しんじ議員の質問に対してということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":158,"id":"exchange-054"},{"speaker":"田中委員","kind":"確認","question":"高橋しんじ議員の質問は、これは越権行為ではないのかということだったのです。私は昨日は、越権行為だったのではないですかということに明確な答えがなかったので、改めてということを伺いたかったのです。これは法令違反になる可能性があって、議会としてこれを認めていいのかと、この問題は本当に大事な話ですから、ということをきちんと皆さん共有したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":159,"id":"exchange-055"},{"speaker":"安藤委員","kind":"質問","question":"これ、実態はどうなのかというところが私は大事だと思っています。これは明らかに越権行為というか。といいますのは、私も８月２３日の教育委員会の議事録も拝見していますが、もう教育委員会がかなり形骸化しているといいますか、報告事項にとどめているわけですね。これは、教育委員会としては、結論が決まっているのに、では、何のために開くのですか。そこについては反省がないのでしょうか。","respondent":"宮尾庶務課長","answer":"一部繰り返しの答弁になりますけれども、改めて廃止の決定というところに関しては、再度、これはもう法に基づくものとして教育委員会を開催し、そこで、また結論はどうなるか、全くフラットなところで教育委員会を開催して。","voiceIndex":163,"id":"exchange-056"},{"speaker":"安藤委員","kind":"意見","question":"昔は選挙で決めていたのです。ただ、残念ながら今はそういうふうになっていなくて、ある意味、行政機関の決定の追認機関になってしまっているという現状が、これは１つ大きな問題としてあります。決定のときだけ教育委員会を開きますというのは、これはあまりにも私は教育委員会としての機能をおとしめるものであり、こういうやり方というのは、私は承服できないというふうな意見を言わせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":165,"id":"exchange-057"},{"speaker":"田中委員","kind":"質問","question":"今、方針の決定だけであって、最終的な本当の決定というのは教育委員会ということは理解しました。ただ、方針が決定された時点で、当事者たちにも説明がないままに、もう閉園だということで話は進んでしまっています。でも決定はしていない。では、今から取りやめることはできるのですかということが上がってきたときには、取りやめることはできるのですか。ということを伺いたいのですが、いかがでしょうか。","respondent":"勝亦学務課長","answer":"今、区立幼稚園３園が出ているかと思いますけれど、入園・退園に関しましては、区長部局で補助執行しておりますので、その取扱いは保育課のほうで退園……。","voiceIndex":166,"id":"exchange-058"},{"speaker":"田中委員","kind":"質問","question":"今、入園・退園の話ではなくて、今後の幼稚園の在り方についてなのですが、補助執行している範囲というのは分かりました。７３４人の方から陳情が上がっている中で、では廃園を中止することは可能なのですよねという問いが私たちに来た場合に、私たちは何と答えたらいいのでしょうか。今、方針だけが決定しているので可能ですよと答えていいのですか。どうでしょうかと、そこの部分を伺いたいのですが。","respondent":"勝亦学務課長","answer":"繰り返しになりますけれども、廃止の決定については教育委員会で議論いたしまして、条例改正が決定いたしまして区議会で条例を出させていただいて、条例が成立して廃止が決定するものと考えております。","voiceIndex":168,"id":"exchange-059"},{"speaker":"田中委員","kind":"確認","question":"実際、今の二世、三世問題とか統一教会の問題がすごく出ている中で、自分が当事者だったのだと気づいた子どもが、今、相談できる体制というのがあるのかと。相談を受けたときに、つなげる先があるのかというところを確認できたらと思うのですが、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"相談窓口や手段が多数あることを指導することが今、重要と考えております。それがたとえ信仰を理由とした虐待行為であったとしても、ご説明した複数の体制で学校が察知するものと考えて、このような答弁になっております。","voiceIndex":172,"id":"exchange-060"},{"speaker":"田中委員","kind":"確認","question":"信仰にかかわらずの相談を受ける通常の体制で今カバーをしているといった認識でよろしいですよね。その中で、当事者だったという相談が今現に上がってきているかどうかということをもしも把握できていたら、受けてからどこにつなげたのかということも確認できたらと思います。","respondent":"矢部教育総合支援センター長","answer":"今現在、特別に信仰を理由とした虐待という案件は、センターとしてはまだ聞いておりません。もしもあっても内容によるのですが、お子さんが虐待のような状態でありましたら、すぐに子ども家庭支援センターかなというふうには今考えております。","voiceIndex":176,"id":"exchange-061"},{"speaker":"安藤委員","kind":"質問","question":"連日の報道で、私のこの大変な状況は信仰の二世、三世問題だったのだと気がつく人がでてくる、なぜこんなに自分がつらいのだろうなと分からない人が、自分のつらさの原点が分かる。今のところそういう事例の相談はないという話ですが、仮にそういうお子さんから具体的に相談があった場合、二世、三世問題の相談があった場合、子ども家庭支援センターのほかに何かないのですか。","respondent":"矢部教育総合支援センター長","answer":"学校で担任が最初の窓口になるかと思いますが、そのお子さんの環境をどうやったら改善できるかということを考える。そこから私どもも情報を得て、今、子ども家庭支援センターと申し上げましたが、必要な関係機関につなげる努力はいたします。","voiceIndex":178,"id":"exchange-062"},{"speaker":"安藤委員","kind":"意見","question":"マインドコントロールなどいろいろ大変な複雑な問題で、特別な専門的な支援も必要な相談になると思いますので、子ども家庭支援センターにまず相談が行ったとしても、その先のいろいろな専門的な相談先というのを今からしっかり研究して、つなげるようにしていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":180,"id":"exchange-063"}]},{"id":"topic-08","title":"審査順を入れ替えまして、(4)その他","agenda":"審査順を入れ替えまして、(4)その他","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"これまでプレテストを何回、いつからやってきたのかということと、このプレテストが、今回のＥＳＡＴ－Ｊ、スピーキングテストとどう関係しているのか。英語スピーキングテストに有効だからこれを行っているのかといったところも教えていただきたいのですが、なぜこのプレテストを実施するようになったのか、その部分もお知らせください。","respondent":"中谷指導課長","answer":"令和元年度からです。２点目の質問ですが、プレテストも含めて、英語のスピーキングテストは東京都教育委員会の主催のものです。今回から入試活用するということに備えまして、その準備として、東京都教育委員会が考えましたプレテストを実施したという経緯になってあります。","voiceIndex":185,"id":"exchange-064"},{"speaker":"田中委員","kind":"質問・要望","question":"ということは、東京都の予算でこのプレテストが実施されるということですか。お金のつけ方も伺いたいのと、英語のスピーキングテストは１１月末に実施されるということですが、会場もまだきちんと明確に保護者にも知らされていません。やはり保護者からも多くの中止してほしい、もうやらないでほしいといった声を聞いております。教育委員会にもぜひそうしていただきたいと思うのですが、いかがでしょうか。","respondent":"中谷指導課長","answer":"２つ目ですが、品川区教育委員会としましては、東京都教育委員会の今回のスピーキングテストの導入の目的ということも含めて、保護者の皆様に丁寧にお伝えしまして、１１月末に実施を考えております。","voiceIndex":187,"id":"exchange-065"},{"speaker":"田中委員","kind":"確認","question":"長くならないようにします。今、丁寧に説明とありましたが、保護者からは、進路説明会のときにも説明がなかったと。実際知られていないのです。質問したいのが、プレテストのときにでも、タブレットを使って子どもが自分で顔写真を撮って、個人情報を入力して送るものになっているのか。それとも今回スピーキングテストのときだけそれが行われるのかということを確認させてください。","respondent":"中谷指導課長","answer":"写真の活用ということですが、今回のテストの申込みの利用規約というものを東京都教育委員会は発行しております。そちらも含めて保護者の皆様に学校を通じてご案内させていただいた上で、写真の活用ということも含めて申込み手続をしているという状況です。","voiceIndex":189,"id":"exchange-066"},{"speaker":"田中委員","kind":"質問・要望","question":"プレテストということは、今プレテストを行っている８年生、９年生は、この顔写真をつけて個人情報を入力するという動作をしているのかというところを確認したいというのと、やはり説明もないまま進んでいく状況がある。なので、ちょっとこのやり方はやめていただきたいというのと、何学年の方たちが個人情報、顔写真を載せて送ってしまっているのか、状況を確認させてください。","respondent":"中谷指導課長","answer":"ただ、利用規約に関しての使用に問題はないと東京都教育委員会は判断しています。そういった個人情報の守り方ということも含めて、しっかりとまた今年度の利用規約をきちんとつくった上での本番実施という形になっております。","voiceIndex":196,"id":"exchange-067"},{"speaker":"安藤委員","kind":"質問","question":"やはりスピーキングテストですが、非常に問題が多くて拙速過ぎていて、これで１１月末に予定どおりというわけにはいかないと思います。そもそもこの全員強制というところですが、都の教育委員会が中学生にそうしたテストを強制できる権限はないですし、これを入試に活用するということは事実上の強制ですから、教育基本法でも禁じられている不当な支配にも当たるわけです。その２点、お伺いします。","respondent":"中谷指導課長","answer":"こちらについては、希望される方のみということでご案内しています。申込み状況としましては約９５％の方々が今、申込みされておりますが、若干個別の理由により受験されないという方もおります。ということで、希望制であるということをお伝えさせていただきたいと思います。","voiceIndex":199,"id":"exchange-068"},{"speaker":"安藤委員","kind":"質問","question":"これは実は、様々な事情というのが様々な事情で、基本的には強制なのです。それで、受けていない方。これが入試と言えるのですかねというか、もうあまりにも都の制度が不整備で、こういうのに参加するということに疑問を感じないのかなというか。品川区としては、そこの点の問題点についてどう考えるか。問題だと思わないのかということ。お伺いします。","respondent":"中谷指導課長","answer":"品川区としまして今回のこのプレテストですが、やはり新しく初めてやっていく取組の中で、プレという、準備という段階の中で、東京都教育委員会が実施の目的も含めてご案内しているものですので、そちらに応えていくという形で、しっかり３年間を見据えて。","voiceIndex":201,"id":"exchange-069"}]},{"id":"topic-09","title":"令和３年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"令和３年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"こちらは、どんな理由なのかというのが１つと、この間、収支という点ではマイナスがかなり進んでいると思いますが、こちらの原因は何なのかということと、こちらはやはり法人の持ち出しになると思いますが、それが人件費削減等、従業員ひいては利用区民へのしわ寄せにならないのかと心配なのですが、そこら辺については大丈夫なのかという点をお伺いします。","respondent":"飛田子育て応援課長","answer":"収支面のところです。事業費については、各事業を実施するために必要な経費ということで、こちらについては、事業で使用する車両の修理や装備品を購入したことや、学童保育児の玩具等の購入に多くかかったことが原因となっております。","voiceIndex":209,"id":"exchange-070"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりました。赤字になると当然持ち出しになってしまうと思うので、法人のほうでリストラなどはないのかなと、心配だなという思いがあるので、そこら辺は大丈夫なのでしょうかという質問にお答えいただきたいと思います。感謝を述べまして、その上で２つ質問です。再委託先を管理しているというところですが、こちらはどういった業務の再委託をどこにされているのかというのをお伺いします。","respondent":"立木保育課長、飛田子育て応援課長","answer":"再委託に関しましては、ぷりすくーる自体の管理をするための点検委託や、清掃委託といったところが再委託という形になっているということです。令和３年度、こちらに記入させていただきました母子生活支援施設処遇改善臨時特例事業補助金、１５万２,６００円と記載させていただきましたが、引き続き令和４年度も、こちらのほう。","voiceIndex":211,"id":"exchange-071"},{"speaker":"田中委員","kind":"確認","question":"それでもしも人の手当てにしわ寄せが行き、マイナスになってしまったら困るなと思って、そこの部分を確認したいと思います。そこの部分を確認したいのと、こういった事故報告書などの点検は、どうしたら私たちができるのかというところを伺いたいというのが２点目です。一般的に知られていないのではないかなと思いますが、どういった周知がされているのかという部分をまず伺いたいと思います。","respondent":"飛田子育て応援課長","answer":"ヒヤリハットと事故防止のリスク等ですが、これは事故があったわけではなく、法人全体としまして高齢者施設や障害者施設等もありますので、そういうところでいろいろな事例を検討しながら、また自分のところはどういうところを気をつけなければいけないかということで。","voiceIndex":215,"id":"exchange-072"},{"speaker":"田中委員","kind":"確認","question":"何か事故が発生したとき、区はどうやって事故報告を受けるのか。改善が必要とされた原因の分析および対応方針の中に、職員への処遇改善に取り組むとともに経費の削減にも取り組んでいるとありますが、処遇改善はされているのですよねという確認と、経費の削減というのは、これは人件費の削減と読めてしまうのですが、この経費の削減というのは何を指しているのですかということを伺いたいです。","respondent":"飛田子育て応援課長、立木保育課長","answer":"おかげさまで、事故などの緊急のことは今までありませんが、万が一起こりましたら、すぐに家庭あんしんセンターから法人本部ならびに区の担当へ連絡が行くようになっております。公設民営保育園と同形式の様式につきましては、特にぷりすくーるには提出を求めておりませんが、私どもで把握しているものでは、約６割程度の人件費比率という確認が取れております。","voiceIndex":217,"id":"exchange-073"},{"speaker":"田中委員","kind":"質問・要望","question":"ぷりすくーるのところで、保育士の人件費比率が６割程度、確保できているということだったと思いますが、今、公設民営保育園については区のホームページで公開されているので、そういった形で利用者が確認できるように公表していただけたらと思います。何かあったら聞かせてください。担当というのはどこですかという確認だけさせてください。","respondent":"飛田子育て応援課長","answer":"ひとり親相談係が担当となっております。","voiceIndex":220,"id":"exchange-074"}]},{"id":"topic-10","title":"第２期品川区子ども・若者計画素案","agenda":"第２期品川区子ども・若者計画素案","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"どなたでもいいかもしれません。これからの未来をつくっていく子ども・若者の可能性をどう切り開いていくかということですから、今回のパブコメに当たっても、そういう説明があるといい。説明会が一番いいと思いますが、オンライン配信でもいいのですが、これはやるべきだと思いますが、いかがでしょうかというのが１つです。この計画をつくる目的を一言で言うと何なのかというのをちょっと教えてください。","respondent":"廣田子ども育成課長","answer":"パブコメ実施に当たっての説明会というお話ですが、パブコメのための説明会というよりは、青少年の関係の委員などにはこの計画についてはお話を少しずつして、理解を得ようと思っているところです。機会を見つけてお話はさせていただこうと考えています。","voiceIndex":227,"id":"exchange-075"},{"speaker":"安藤委員","kind":"質問・要望","question":"なるほどと。ですから、工夫していただきたいなと、改めてこれは要望です。専門委員会は１８名で、検討部会の方を合わせると、延べで言うと２８名ぐらいいると思いますが、こちらは、重複しているのがどういう方々なのかというのを、ある程度、代表的なところを教えていただきたいのと、あと、冊子に書いていないのです。それをどういうふうに捉えていらっしゃるのか、伺いたいと思います。","respondent":"廣田子ども育成課長","answer":"生きづらさを感じるところの検討部会につきましては、フリースペースや教育総合支援センター、各種ひきこもり等の支援を行っている部署の方に入ってもらいながら、オブザーバーとして先ほど申し上げた萩原建次郎先生に入っていただいたり、引き籠もっていて。","voiceIndex":229,"id":"exchange-076"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりました。最後に具体的にお伺いしたいこと、要望があるのですが、Ａ３の資料の重点施策がありますが、特に１番目と２番目のところで、子ども・若者の活動拠点の整備を具体的に検討していくということですが、どういうことを考えていらっしゃるのか。これは要望したいと思いますし、そういった問題についてどう考えるかという点。そこら辺についての問題意識もお伺いできればと思います。","respondent":"廣田子ども育成課長","answer":"フリースペースではやり切れない部分をつなげるところをつくる。つくるか探すというところで、ネットワーク化と重層的支援事業の検討も進んでおりますので、ネットワーク化をしながら、１つの場所で全部は解決できませんので、つながっていくというところを考えています。","voiceIndex":231,"id":"exchange-077"},{"speaker":"田中委員","kind":"質問・要望","question":"今回の基本理念の変更については先ほどご説明もあって、大綱が変わっただけでなく、区としてもゴールを自立にするのは危険という判断で、安心できる場所が必要といった考えから変更に至ったということは、本当にそのとおりだなと思いました。そこの部分に本当に取り組んでいただきたい。今後、報告があるということで、動きがあるのかなと思ったのですが、そこの部分を確認させてください。いかがでしょうか。","respondent":"廣田子ども育成課長","answer":"パブコメの説明については、説明会という形ではなくて、主任児童委員や青少年委員になど様々な場面を見つけてお話をしていこうかと思います。","voiceIndex":234,"id":"exchange-078"},{"speaker":"田中委員","kind":"質問・要望","question":"若者に特化した部分で、小学校、高学年、中学生とそれ以上の子どもと若者の居場所というのが本当に今ない状態です。唯一あるのがフリースペースです。高学年の子どもと若者の居場所をつくるというのはなかなか難しい問題もあるかもしれませんが、今、居場所がない子たちがそれで間違った方向に行くことがないように、受皿となるような居場所づくりをぜひ進めていただきたいと強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":236,"id":"exchange-079"},{"speaker":"くにば委員","kind":"質問・要望","question":"パブリックコメントについてです。先ほど、前回は８名から３３件のご意見をいただいたということですが、今回、パブコメに対して具体的にどのような方々からご意見をいただきたいのかについて伺いたいと思います。３０代以下の方は１.７％しかパブコメに参加していなかったという事実がありました。それであえて今回コメントをいただきたいと考えているターゲットを、まず伺います。","respondent":"廣田子ども育成課長","answer":"前回、パブコメが８名３３件でしたが、前回は期間が非常に短かったので、今回はマックスに近い１か月ほど取るようにしております。理想としては、当事者の声を聞きたいというところで、今回検討部会でも今２０代のひきこもりだった方や大学生に入っていただきました。","voiceIndex":238,"id":"exchange-080"},{"speaker":"くにば委員","kind":"意見","question":"パブコメが全てではないし、なかなか若い方々からパブコメをいただくのは難しいという部分についてです。今回このＡ４の用紙に、周知方法は広報紙への概要掲載、区ホームページ等と書いてあります。若い人たちが、パブリックコメントというとどういった内容なのか分からないかもしれないので、みんなのコメントを募集してますというポスターを作る。そこについて何かお考えがあれば。","respondent":"廣田子ども育成課長","answer":"次のターゲットを大学生とかそういう世代についてどう広げるかについては、これからまた検討に当たって考えていこうかと思います。委員のご意見も参考にさせていただこうと考えています。","voiceIndex":240,"id":"exchange-081"},{"speaker":"くにば委員","kind":"質問","question":"声をいただくという部分に関してですが、具体的に個別に面談をして、それぞれの方々にご質問なさったのか。それとも目安箱のような形で匿名で、自分が発言したことが分からないような形で、プライバシーが守られるような、気軽に投稿できるような形で声を聞いたのか。その声を聞いたという内容について、やり方について教えてください。","respondent":"廣田子ども育成課長","answer":"フリースペースにつきましては自由に来られる時間帯を午前中に設けていますが、１８歳以上が来る若者カフェといって、希望している人だけ来る座談会のような会も設けております。","voiceIndex":242,"id":"exchange-082"},{"speaker":"くにば委員","kind":"質問・要望","question":"そういった部分がすごくあると思いますので、中高生のアンケートだけではなく、実際に当事者の方々からも匿名で意見をもらえるような形ももう少し深掘りしてというか、何かしらその方法を考えていただきたいと思うのが１点目です。もう１点は、ひきこもり当事者についてです。こちらに関して、ポスト青年期。そこの線引きについて、明確に２９歳なら２９歳で区切るのかどうか、教えてください。","respondent":"廣田子ども育成課長","answer":"有料だったり、区としてはそんなに持っていませんが、都・国の４０歳を超えたら受けられないというサービスでなければ、対応可能であれば受けています。一旦受けて、その年齢に合う支援先につなぐということはしています。","voiceIndex":244,"id":"exchange-083"},{"speaker":"くにば委員","kind":"質問","question":"フリースペースやエールしながわ等の活用に関しては、本当にご努力なさっていると感じております。リアルの現場、人の顔が見えるところに行くのは、やはりハードルが高い。なぜかというと、インターネット上にはひきこもりの人たちが多い場所というかネットの空間がやはりあります。そういうところを品川区として何かしら模索できないかと思うのですが、そこについて何かお考え等ありますでしょうか。","respondent":"廣田子ども育成課長","answer":"そういう対応はできるのですが、エールにしても、今は本当に一人ひとり丁寧に行っている状況なので、ＳＮＳのほうが気軽ではあると思いますが、スタッフの心のメンテナンスということも考えなければならないので、ちょっと今は区としては難しいかなと考えています。","voiceIndex":246,"id":"exchange-084"},{"speaker":"くにば委員","kind":"質問・要望","question":"最後に意見というか、今おっしゃったとおり東京都で、専門性がやはり必要、生死の問題なので試行錯誤しながらやっているという部分。少しずつその情報やノウハウを蓄積していきながら、東京都だけではなく、少しずつ品川区でも進められるような体制に後々なっていただきたいなと意見させていただいて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":248,"id":"exchange-085"},{"speaker":"松澤副委員長","kind":"質問・要望","question":"要は何が言いたいかというと、子どもの貧困というのは、裏に見えるのが親の貧困ということもあるわけではないですか。見学に行きましたけれど、子どもがゲームをやって遊んでいて、居場所という部分ではすごくいい活動だなという中で、今、不登校児童・生徒への教育の中で、ＩＣＴを使った学習をしましょうという話がある、では、そこにどう結びつけるのかなとか。それについて何か一言だけ。","respondent":"廣田子ども育成課長","answer":"大学生だけではないのですが、若い世代に入ってもらえるような仕組みが必要ではないかというご意見も出ました。それは引き続き検討していくということで、計画の策定の検討部会の中で出てきたので、いかしたいと考えています。","voiceIndex":250,"id":"exchange-086"}]},{"id":"topic-11","title":"区立児童相談所開設に向けた進捗状況等","agenda":"区立児童相談所開設に向けた進捗状況等","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"資料に基づいて。場所をお伺いします。それと、竣工から開設までは結構長い期間があると思いますが、開設準備を進めるに当たり、建物をどのように使用していくイメージなのかお伺いしたいと思います。それと夜間休日の対応の件は、委託なのか直営なのか検討中ということですが、先行自治体が既にあると思いますが、そちらの状況というのはつかんでいらっしゃるのか、伺いたいと思います。","respondent":"長谷川児童相談所移管担当課長","answer":"その翌月にその初度の物品搬入というスケジュールになっておりますので、その後の使用スケジュールという意味合いだとは思いますが、その後、開設の６年１０月までの間に関しましては、主に派遣職員や経験者採用職員等の知見・経験といったものをいかしながら。","voiceIndex":256,"id":"exchange-087"},{"speaker":"安藤委員","kind":"質問","question":"見守りホットラインの接続先について一本化するということですが、現在はどこにつながっていて、どういうふうな対応をされているのかというのを伺います。4)については、現在既に様々な自治体へ派遣されているのですが、その成果と、派遣されている職員の方々の受け止めみたいなものをどういうふうにつかんでいらっしゃるのか、どんな状況なのか、伺いたいと思います。","respondent":"長谷川児童相談所移管担当課長","answer":"一方で、１人で孤独に戦っている派遣者ですので、そういった方の不満や愚痴といったところを聞く貴重な場にもなっていると認識しております。","voiceIndex":258,"id":"exchange-088"},{"speaker":"安藤委員","kind":"質問・要望","question":"すごく人が重要だといいますか、場合によっては大変深刻なケースも扱い、専門性がすごく求められていると思いますので、職員の体制については、加配も含めてかなりしっかり手厚くしていただきたい。ぜひそちらも検討していただきたいのですが、最後にご意見があれば伺いたいと思います。","respondent":"長谷川児童相談所移管担当課長","answer":"その業務の継続性や執行体制なども勘案しまして、これまでも柔軟な配慮・対応を行っていたところでありますけれども、児童相談など専門性が求められる業務に限らず、異動については杓子定規にならずに配慮していく必要があると、我々としても認識しております。","voiceIndex":260,"id":"exchange-089"},{"speaker":"田中委員","kind":"質問","question":"２点伺います。児童相談所開設に向けた計画書の１４ページで、子どもの権利擁護について触れています。子どもの権利擁護の機関の設置について、区としてどのように考えているのかを伺いたいのが１点です。それで辞めてしまうケースも多くあると聞くので、メンタルケアの部分を伺いたいのですが、どのように考えているかということを教えてください。","respondent":"長谷川児童相談所移管担当課長","answer":"そういったときに、相談窓口の活用や設置区の状況等を踏まえて、職員のメンタルケアについては引き続き検討していきたいと考えております。","voiceIndex":263,"id":"exchange-090"},{"speaker":"渡部委員","kind":"確認","question":"確認だけです。建物ができて、今年の３月にはもう箱が出来上がっているから、児相に関係する人というのはそこに移動といいましょうか、その建物で仕事を始めるということでよろしいのですよねというのが１点です。継続している案件というのは一旦全部引き取って、それで徐々に新たな案件もそこでどんどん取っていくというイメージなのかというところの確認です。その３点だけ教えてください。","respondent":"長谷川児童相談所移管担当課長","answer":"来年はもう少しプラスで１年派遣という方法も検討していきたいと考えていますので、そういった職員はその建物の中には入らない。","voiceIndex":267,"id":"exchange-091"}]},{"id":"topic-12","title":"品川区保育所等の利用調整基準の一部改正","agenda":"品川区保育所等の利用調整基準の一部改正","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"資料の２の（１）のところですが、申請の直近３か月の就労状況で出していたような記憶があるのですが、それを４月入園の場合は、直前の３月、２月、１月の実績でよいという変更なのでしょうか。その場合、結構ばたばたするのではないかなと思いますが、間違っていたら訂正して説明いただければと思います。","respondent":"立木保育課長","answer":"委員のご指摘のとおり、４月入園の場合は３月、２月、１月の勤務実績をもとにという形に変更になるです。","voiceIndex":274,"id":"exchange-092"},{"speaker":"安藤委員","kind":"質問","question":"申請は１１月にするのですが、直近の就労状況については後で書類を出すという流れ、イメージということでしょうか。","respondent":"立木保育課長","answer":"引き続き就労しているものとみなしまして、変更があった場合には書類を出していただくということになります。申請の段階で内定とか勤務が始まっている場合には、今後こういう形で就労しますという形で出していただき、事務手続を行うことになっております。","voiceIndex":276,"id":"exchange-093"},{"speaker":"田中委員","kind":"質問・要望","question":"改正前は診断書等が必要でしたが、改正後は、医師が証明した病状内容で指数の認定ということで、とても楽になったというか、負担が軽減されたということでよろしいですねという確認と、この改正については、品川区独自で改正ができるのですか。品川区が基準を持っていて、こうやって改正ができるのかという部分を教えていただきたいと思います。","respondent":"立木保育課長","answer":"項番２の（２）に関しましては、これまで自由書式で出していただいておりましたが、書かれている内容がそれぞればらばらでございまして、保育の必要性を認定する際にかなり聞き取り調査等をしておりました。","voiceIndex":279,"id":"exchange-094"},{"speaker":"安藤委員","kind":"質問","question":"目的のところの保護者・企業の負担軽減というのがいろいろ説明があったのですが、保護者間の公平性確保という点では、これはどういうところが改正なのでしょうかというという説明をお聞かせください。","respondent":"立木保育課長","answer":"入園月を基準にすることによりまして、１１月ぐらいから働き始めて既に５か月働いている方が、以前より継続して働いている方と同じ条件で入園審査が受けられるということで、公平性を担保したという形になってあります。","voiceIndex":282,"id":"exchange-095"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5082#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":97185,"voices":290}},{"id":"r04-20221101-5","meetingId":"r04-cm11","date":"2022年11月1日","dateIso":"2022-11-01","committee":"総務委員会","time":"午前１０時００分～午後 ４時３５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"説明に入る前に、各所管委員会における審査結果","agenda":"説明に入る前に、各所管委員会における審査結果","exchanges":[{"speaker":"吉田委員","kind":"確認","question":"いつもこのような補正予算審査のときに、何度かこの総務委員会で確認させていただいているのですけれども、改めて伺います。もし間違っていたら、修正していただけると大変ありがたいです。","respondent":"黒田財政課長","answer":"補正予算の考え方のご質問になりますが、基本的には年度当初の予算で想定できなかった事態が発生した際に補正予算を編成いたしますけれども、いわゆる国や都の補助金につきましては、その事態が発生したときに、財源として活用できるものについては、当然その活用をいたしますし。","voiceIndex":5,"id":"exchange-001"},{"speaker":"吉田委員","kind":"確認","question":"度々確認させていただいてすみません。そのような考え方でいうと、歳出のほうの産業経済費の創業支援施設等経費というものは、旧ゆうぽうと跡地の活用というところで、もう既に大分前から計画があって、私が別の委員会にいるときも説明を伺っていたと思うのですけれども、この中での施設内装工事設計委託というものは、今この時期に補正予算でということの意味が分からないので、ちょっと教えてください。","respondent":"黒田財政課長","answer":"いわゆる躯体連動工事のところの予算編成につきましては、令和４年度編成時につきましては、金額が不明な点もあって、令和５年度の当初予算で計上することを想定して、令和４年度予算を当初編成したところですが、本来の日本郵政のほうで建設している事業者のほうから。","voiceIndex":7,"id":"exchange-002"},{"speaker":"吉田委員","kind":"質問","question":"ということは、区の計画で見込んだものより、先方のという言い方でいいでしょうか、相手方の事情、それもいろいろなものの高騰ということは、そちらとしても想定外だったと思うのですけれども、そういうことで、なるべく費用を抑えるとか、そのような意味で、このたびの補正になったということで理解してよろしいでしょうか。","respondent":"黒田財政課長","answer":"ご指摘のとおりです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"建物の持ち主である日本郵政がやるのではなくて、品川区がそういった設計から内装工事まで、品川区の予算でやるというようなことになるのか、その仕組みをひとつ教えていただきたいと思います。","respondent":"黒田財政課長","answer":"今回の五反田産業文化施設につきましては、郵政が建物の一部、ホールを借り受けて、区が公の施設として条例設置で運営するという施設になりますので、いわゆる借り方の中で、内装まで全て工事が終わったものを借りるという形式もあろうと思いますが。","voiceIndex":11,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうしますと、その内装工事全体としては幾らぐらいかかるという試算などが出ているのか、ちょっとその点を伺いたいということと、それから賃料が１年間に１億４,５２０万円ということで日本郵政から借りるということで、区民委員会のほうでは答弁があったと聞いているということなのですけれども、これは指定管理者になっていきますよね。","respondent":"黒田財政課長","answer":"指定管理者については、通常でいいますと、公の施設を１年間運営するに当たって、必要な経費について様々なご提案をいただいて、条例に定めた使用料を徴収して、収支が、所管課の説明ですと７５％ぐらいの稼働率だと３,０００万円から４,０００万円ぐらいの運営費。","voiceIndex":13,"id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ということは、区の負担としては、賃料が年間１億４,５２０万円かかった上に、指定管理者に対して赤字になるかもしれないというようなことを見込んだ委託料というような形で、賃料と、それに加えて委託料がかかるということで考えていいのでしょうか。","respondent":"黒田財政課長","answer":"先ほど申し上げましたが、あくまでも賃料は整備費相当というように考えた場合、運営費というものは別という考え方というふうに捉えております。","voiceIndex":15,"id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうはいっても、毎年１億５,０００万円近くの賃料がかかった上に、これだけすごく高い、イベントホールを全日借りると約６０万円、ギャラリーでも全日借りると９万９,０００円、エントランスロビーでも全日借りると５万５,０００円ということで、区のほかの施設に比べたら、ここは１０倍くらい高い施設であるにもかかわらず、それなのにそのように赤字になって。","respondent":"黒田財政課長","answer":"整備は日本郵政がするものを借りるという意味で、運営は、建てても借りても委託として行うものですので、そこは今回、整備費はかかっていないということであれば、基本的には運営のやり方としては、通常どおり公の施設を運営していくという考え方に立っているところです。","voiceIndex":17,"id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"日本郵政がもともと旧ゆうぽうと跡になぜこのようなホールをつくらなかったのかといったら、日本郵政としては採算が取れないというようなところでつくらないと、そのようなことで区から答弁もあったということなのですけれども、それをあまりに高い、一般の区民が使うというよりは、株主総会ですとか、セミナーとか、商品発表会とか、パーティですとか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":19,"id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"衛生費のところで、国庫支出金返還金とあります。実際では、予防接種を受けられる方の人数を想定してやったけれども、実際はそれだけ少なかったということで、最初の予定と違ったので、その分を国に対して、ただ単に返金したということと考えてよろしいでしょうか。","respondent":"黒田財政課長","answer":"時間外、休日の接種のほうも、予約が取りやすくなるに当たりまして、いわゆる個別医療機関のほうでも診療時間内に接種するような形が増えてきまして、そこの部分に計上した予算も不用となりまして、そういった複合的な要因で、１４億円余の返還となったというものです。","voiceIndex":21,"id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"逆に、ここでまた啓発事業というものに取り組んでいかないと、ますます接種する人が減ってしまうのか、ちょっと心配するのですけれども、その辺はどのようにお考えでしょうか。","respondent":"黒田財政課長","answer":"所管課から聞いておりますのは、これまでの様々な株の変異の中で、国のほうでもいわゆる重症化率というところも変異によって変わってきているという中で、区民の皆さんもいろいろ考えるところがあって、接種についていろいろな考えをお持ちなのだろうなと考えていますが。","voiceIndex":23,"id":"exchange-010"},{"speaker":"つる副委員長","kind":"質問・要望","question":"では順番に、総務費の選挙費のことなのですけれども、報酬で６００万円で、一応そのそれぞれの大括りの人件費に当たる部分として、投票事務費の中で、これは期日前と当日ということで分かれていると思うのですけれども、期日前が３３０万円で、当日と思われるものが２４５万円、それから開票事務費、開票作業所での事務経費だと思いますが、それが２５万円と分かれているのですけれども。","respondent":"鈴木選挙管理委員会事務局長","answer":"期日前につきましては、１３か所の地域センターで、投票管理者お一人と投票立会人お二人がいらっしゃいます。それの１３か所分の人数。それから、投票所に関しましては、４３か所に投票管理者１人ずつと、立会人が３人ずつということになります。","voiceIndex":26,"id":"exchange-011"},{"speaker":"つる副委員長","kind":"質問","question":"これはいろいろ一般論で伺っている中では、本選から逆算して何か月などというものがあったかと思うのですが、今回は再選挙という、そこを基本の日にちにしての、それに付随しての補欠選挙という扱いなのかなと理解している部分と、全く純然たる、ここが区長選挙の本選とはいつなのでしょう、であれば、ここで区議会議員の補欠選挙というものはできなかったのか、できたのかという。","respondent":"鈴木選挙管理委員会事務局長","answer":"区議会議員選挙の補欠選挙ですが、公職選挙法の規定によりまして、通常は定数の６分の１を欠けた場合に、単独でも補欠選挙を実施します。","voiceIndex":28,"id":"exchange-012"},{"speaker":"つる副委員長","kind":"確認","question":"そうすると、当然今後の品川区の中でも、考え方が、いろいろ条例だとかの改正、そのようなものがある等々しれませんけれども、今回の１２月４日執行の区長選挙というものが、ここで当選人が出ると、ここが４年後、何もなければ４年後の区長選挙が、また１２月４日に実施されるとなったときに、その間区議会側で欠員等が発生した場合には、ここでは補欠選挙は行わず、本選に寄せられるというか、本選で行う。","respondent":"鈴木選挙管理委員会事務局長","answer":"現在の区議会議員の皆様の任期が４月末日ですので、その任期が今後何かの事情でずれない限りは、１２月に区長選挙を行うときには補欠選挙は行わないと、区議会議員の補欠選挙は同時には行わないということが、４年後以降の想定になります。","voiceIndex":30,"id":"exchange-013"},{"speaker":"つる副委員長","kind":"質問・要望","question":"それで、所得制限がなければ、マイナンバーの情報から行政がそれを確認、マイナンバー経由ではなくても、いろいろな事務連携というのですか、それでできる部分もあるかとは思うのですけれども、それが、所得制限を東京都が設けなければ、その作業というものは現場の区にしてみると、どれだけの手間なのかどうか分かりませんが、必要なくいけたのかなという確認は、委員会後にさせていただいたのです。","respondent":"黒田財政課長","answer":"都からの補助金の考え方ですが、事務に関しては一定程度条件がありまして、その範囲で東京都で１０分の１０として出すというように聞いておりますので、明確に所得制限を超えている部分の対象事務に対する事務費が補助対象云々ということではなくて、全体の事業費の中で。","voiceIndex":32,"id":"exchange-014"},{"speaker":"つる副委員長","kind":"質問・要望","question":"それと、ここは私も不勉強な部分で、逆に教えていただきたいのですが、事項別明細書を見ると、この高校生等医療費助成というものは、子どもすこやか医療費助成の中でという理解でいるのですけれども、事項別明細書を見ると子どもすこやか医療費助成事業で２,８２０万円という部分と、それから高校生等医療費助成事業で２,８２０万円ということで、見積り総額が２つになっているのです。","respondent":"黒田財政課長","answer":"この高校生等医療費助成制度につきましては、今副委員長からご指摘があったとおり、もともとの区の制度の立てつけとしては、いわゆる１つの条例の中で、乳幼児医療ですとか、義務教育医療費助成制度と同じ枠組みの中で制度として立てつけているというところはありますが。","voiceIndex":34,"id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"先ほどの五反田産業文化施設について、料金設定のことで伺いたいのですけれども、きゅりあんなどのイベントホールが、５６０席で、平日であれば全日借りても８万３,７００円で、日曜・祝日が１０万４００円という状況ですし、ホールなどでいえば、荏原文化センターなどももっと本当に、この１０分の１ぐらいで全日借りられる状況なのですが、これだけ全日借りて約６０万円という利用料というものは。","respondent":"黒田財政課長","answer":"そういった中で、近隣のホール等の料金等も勘案しながら、区では大崎でＳＨＩＰが運営するブライトコアホールなどもありますので、そういったところも鑑みて、今回の使用料を設定したというふうに所管課からは伺っております。","voiceIndex":36,"id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"産業ものづくり部門として決めたというよりは、区の方針としてこれをつくろうというようなことで決めていると思うのですけれども、商業利用としてというようなことなのですが、対象や目的などというようなものは、にぎわいのあるまちづくりというようなことでしか書いていないのですけれども、どのように区としてそのような対象や目的をつくろうという方針になったのかということと。","respondent":"黒田財政課長","answer":"一定程度そういった運営費も見ながら設定しませんと、結局稼働率が１００％でも運営費が回収できないということでは施設が成り立ちませんので、そういった意味では、そういった運営費も鑑みて使用料を決定しているというふうに伺っています。","voiceIndex":38,"id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"賛成です。先ほど申し上げましたように、区民が使うというよりは、にぎわいの創出と言いながらほかの施設の１０倍近い料金設定で、本当に開発を誘導していくという、そのような施設としての位置づけになるのではないかなというような思いで、この施設に対しての補正予算は反対なのですが、そのほかのところは全て区民にとって有益な予算が組まれていると思いますので、総合的なところでは賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":43,"id":"exchange-018"},{"speaker":"吉田委員","kind":"質問","question":"賛成します。先ほど私たち品川・生活者ネットワークとしても、五反田産業文化施設のこの委託の補正について質問をいたしましたが、この補正、この建物自体は、私はたしか２０１９年の建設委員会の報告のときには建設委員会にいたのですけれども、様々なご意見が出たかと記憶しております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-019"}]},{"id":"topic-02","title":"令和４年１０月２日執行 品川区長選挙 品川区議会議員補欠選挙 結果","agenda":"令和４年１０月２日執行 品川区長選挙 品川区議会議員補欠選挙 結果","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"選挙のご報告等があるたびに、今まで障害者の方で、なかなか投票しにくい方からのご意見を基に、私の意見を申し上げていたのですけれども、昨日の陳情審査のときに、投票所に入れる人について、子どもは昔は駄目だったけれども、今は親と一緒に入っていく、入れるようになっているということなのですが、そのほか付添いというものはどうなのでしょうか。確認させていただきたいのですけれども。","respondent":"鈴木選挙管理委員会事務局長","answer":"障害をお持ちだったり、けがをしていたりして、付添いなり、介助が必要な方につきましては、各投票所にいる職員には、そのような支援が必要な方のための人員も配置しておりますので、基本的には職員のほうで、車椅子なり、お隣で介添えするというところの職務をしまして。","voiceIndex":53,"id":"exchange-020"},{"speaker":"吉田委員","kind":"質問","question":"分かりました。その私が直接意見を伺った方は、娘さんに手を引いてもらって入ろうとしたら、娘さんはそこの投票をする立場の方ではなかったと思うのですが、かといって誰かが手を引いてくれるわけでもなくという感じで、大変ご立腹だったのです。そのような指示が徹底されていなかったのか、その辺について見解を伺いたいと思います。","respondent":"鈴木選挙管理委員会事務局長","answer":"私ももう２０年以上投票所をやっておりましたが、必ずそのようなときには対応するようにしてきましたけれども、そのように一部対応が不足の部分があったのかもしれませんので、１２月の選挙では、改めてそのことについても注意喚起をしまして。","voiceIndex":55,"id":"exchange-021"},{"speaker":"吉田委員","kind":"意見","question":"今までもコミュニケーションボードでしたか、せっかく選挙管理委員会として用意されたものが掲示されていない。今回も何か所か聞いたのですけれども、もうしっかり出ていましたというところと、それからやはり見当たらないなというようなところがあったのです。現実的に。やはりそのような方たちが投票しやすいように、改めて徹底していただけると大変いいと思いますので、ぜひよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":57,"id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"要介護の方もこの対象になるのではないかと思うのですが、介護度が幾つまでの方がこの郵便等投票証明書をもらうことができるのか、そして郵便等投票証明書というものはいつまでにどのような形で申請すればいいのか、ちょっとその仕組みを教えてください。","respondent":"鈴木選挙管理委員会事務局長","answer":"それから介護を要する方のほうも、やはり基本的には移動を、投票所に、もしくは期日前投票所に移動してできない方ですので、介護３から５で四肢の支障のある方だというように、たしか記憶しております。すみません、ちょっと今手元に詳細を記載した資料がないのですが。","voiceIndex":58,"id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、障害の方というものは、基本的に身体障害者、身体障害の方ということになるのでしょうか。もちろん精神障害の方などはなかなかならないのだろうなと思うのですけれども、身体障害の１級、２級や、それとももっと軽くても、ちょっと移動が困難ということで選挙管理委員会のほうで認めてもらえればできるということなのか。ちょっとその辺の細かいところを、申し訳ないのですけれども。","respondent":"鈴木選挙管理委員会事務局長","answer":"選挙管理委員会の裁量で対象にする、しないと決められるものではなくて、障害者手帳、それから要介護認定の等級と、それからその要件、歩くのに支障はあるかとか、その要件が決まっていて、それに該当するかどうかになりますので。","voiceIndex":60,"id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、その要件というものは要綱か何かで決まっているという、何か基準を決めている文章というものはあるのか、ちょっとその点も教えてください。","respondent":"鈴木選挙管理委員会事務局長","answer":"この要件につきましては、公職選挙法に基づくものですので、区の要綱などではなくて、公職選挙法と、それからそれに関する国の基準、通知などで定められているものです。","voiceIndex":62,"id":"exchange-025"}]},{"id":"topic-03","title":"令和４年職員の給与等に関する報告及び勧告の概要","agenda":"令和４年職員の給与等に関する報告及び勧告の概要","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"ちょっと我々が新聞報道を見ている限りでは、民間でもうほとんど８０％、９０％を占める中小企業の人たち、お店をやっている人たち、商店街を含めて、給与が上がっているというような実感がほとんどないということと、どうしても比較に対してこれだけ職員の皆さんが給料が低い、民間と比べて低いというようにはどうも思えないのです。","respondent":"崎村人事課長","answer":"実態と違うのかというところのお話なのですけれども、今回の調査につきましては、これまでもご説明しておりますとおり、企業規模５０人以上で事業所規模５０人以上の事業所を対象としているというところについては、これはやはり公務と同様の役職段階を有しているという部分で。","voiceIndex":68,"id":"exchange-026"},{"speaker":"須貝委員","kind":"質問・要望","question":"ただ、このように区民に報告をするわけではないですか。それを私は、区に求めるということはきついのだろうけれども、やはりこれでは説得を、我々もできないし、なかなか説明がしにくいというのが１つなので、そこは人事課に言うよりは人事委員会のほうに意見として、明確な説明、区民でも分かりやすい説明をするように、私は要求していただきたいと思います。ご見解があったらお聞かせください。","respondent":"崎村人事課長","answer":"採用につきましては、これまでもお話をしてきましたとおり、特別区２３区全体で人事委員会というものを設置して、人事委員会による統一の採用選考というものを行っている中で、各区のほうで採用するという流れになっております。","voiceIndex":70,"id":"exchange-027"},{"speaker":"須貝委員","kind":"質問","question":"今、２３区のほうで決められるという話ですが、会社として見るならば、やはりその会社にいい人材が来れば、将来、この品川区というものは、私は安泰だと思うのです。いろいろ人材というものは、品川区を支えるという意味で大きな位置、事業もそうですが、事業をやるにはやはり人ですから、何とかいい人材をできるだけ１人でも採用するように、努力してほしいと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-028"},{"speaker":"吉田委員","kind":"質問・要望","question":"以前も伺ったかもしれないのですけれども、これは勧告なので、勧告ということで、特にいろいろな人事・給与制度、勤務環境の整備等に関する意見となっているのです。読めば何か分かっているのだけれども、それに対しての、これの文章の扱いというものは、ただ、はい分かりました、聞いておきますというようなことでいいのでしょうか。すみません、改めて教えていただきたいと思います。","respondent":"崎村人事課長","answer":"意見の部分につきましては、これも人事委員会が行うもの、また区が行うものと分かれておりますけれども、今後このような取組をしなさいではなくて、したほうがよいのではないかというようなお話ですが、ただ、こちらで書かれていることにつきましては。","voiceIndex":74,"id":"exchange-029"},{"speaker":"吉田委員","kind":"質問","question":"要は、３０％の目標値を達成するように努力するようにという、そして女性の取得者より男性の取得者のほうが短いから、もう少し長く取るように職場風土を変えていきなさいよという意見だというように読んで、分かりましたという、それだけのことなのでしょうか。以前も同じように違和感を感じて、同じようなことを伺ったかと思うのですけれども、そのような性質のものと理解してよろしいのでしょうか。","respondent":"崎村人事課長","answer":"意見に書いてあるものが「必要」でしたり、「懸念」でしたり、何かそういった言葉で締めくくられているので、何となく委員のお話もあるように、言いっ放しで終わっているような印象は受けるかもしれないのですけれども、ただ。","voiceIndex":76,"id":"exchange-030"},{"speaker":"吉田委員","kind":"質問・要望","question":"１点、４ページの３の、区民からの信頼の確保というところ。公益通報制度というものが、私の理解に違いがあるかもしれないので、改めてその制度について伺いたいということと、「従来の不祥事防止策に加えて」ですので、不祥事防止につながる制度ということを考えると、例えばこの辺は私としてもぜひ強化をしていただきたいと思うのですが、現段階で何かお考えがあったら伺いたいと思います。","respondent":"崎村人事課長","answer":"こちらの活用といったところにつきましては、公益通報制度は、確かになかなか制度として、これまでも通報件数がほぼ０件というような状況でもありますけれども、あることが正しいのか、ないことが喜ばしいのかという部分はかなり評価が難しいところではありますが。","voiceIndex":78,"id":"exchange-031"},{"speaker":"吉田委員","kind":"質問","question":"ぜひよろしくお願いします。ちょっと記憶が曖昧なのですけれども、それも保育士、退職した保育士からの通報で明らかになったという例を以前伺いました。今私が言っているのが、この公益通報制度の範囲に入るのかどうかも分からないのですけれども、その点について、もしご見解があればお伺いしたいと思います。","respondent":"崎村人事課長","answer":"公益通報の対象者としては、もちろん退職者も含まれますし、今委員のお話がありました事業等の委託事業者等々も含まれますので、そういった方が区の委託事業等を行う中で、違法または不当な行為というところの事案を認識して改善を求めるといったところでありましたら。","voiceIndex":80,"id":"exchange-032"},{"speaker":"吉田委員","kind":"質問・要望","question":"すみません。辞めないと言えないというのは不適切な表現だったかもしれませんけれども、おっしゃるとおり、何かあったときに適切な指摘をした人に関してのきちんとした権利の保障など、そのようなことがされるようになっていただきたいし、調査をした結果、特に問題はありませんでしたということもあると思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-033"}]},{"id":"topic-04","title":"意見書（案）","agenda":"意見書（案）","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"ちょっと１点だけ、私の解釈が悪いのかもしれないのですが、文面の初めに新型コロナウイルス感染症のことで、「一昨年より続く」と書いてありますね。これはもう、今回で３年目に入るのですけれども、この文章でいいですか。いや、解釈の話なのです。「続く」と書いてあるので、それでいいのかもしれない。「長年続く」より、いいのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-034"}]},{"id":"topic-05","title":"立会川緑道整備工事（２工区）請負契約","agenda":"立会川緑道整備工事（２工区）請負契約","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"建設委員会のほうの資料を見ていなくて、お聞きして申し訳ないのですけれども、この緑道の整備工事は１工区から４工区になっていて、そのうちの今回は２工区ということなのですが、その２工区のところというのは、たしかにぎわいゾーンという、そのような位置づけがされると思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-035"}]},{"id":"topic-06","title":"「よくわかる！品川区財務諸表」の作成","agenda":"「よくわかる！品川区財務諸表」の作成","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"質問というより意見です。データでは、ホームページで今まで財務４表のあたりが出ていたのですけれども、今度は求めなくても冊子で出てくるのでしょうかということが１つと、このように早く情報が出されるようになったということは大変歓迎したいということを意見として申し上げたいと思います。冊子は、できたら私は紙でいただきたいのですけれども、そのように理解していいか、それをお聞きします。","respondent":"中山会計管理者","answer":"こちらの「よくわかる！品川区財務諸表」につきましても、紙の状態で決算特別委員会の前には議員の皆様に配布して、区民の皆様への配布というのは決算の認定後というように、決算書のデータアップと一緒にと考えています。","voiceIndex":111,"id":"exchange-036"},{"speaker":"吉田委員","kind":"質問・要望","question":"では区民の皆さんにも、求めればどこか、地域センターとか、そのようなところに冊子を置かれているのでしょうか。それを教えてください。","respondent":"中山会計管理者","answer":"昨年度から実際に置かせていただいたのですが、地域センターや図書館、あるいは中小企業センター、そういったところには紙のものも置かせていただくようにいたします。","voiceIndex":113,"id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"９ページ、１０ページ辺りのところで伺いたいのですけれども、これは令和２年度の内訳と令和３年度の内訳ということで、どう変わったのかというようなことでグラフで一目瞭然というような形で配置していただいていると思うのですが、これはなぜこうなったかという理由は、例えばここでいえば、行政コスト計算書のところでいうと、扶助費・補助費等が５５％から４１％に減っているとか。","respondent":"中山会計管理者","answer":"最初のグラフの構成の変化についてですが、こちらのほうは８ページのところの「３年度のポイント」というところに、具体的な数字も載せながら記載しています。","voiceIndex":115,"id":"exchange-038"},{"speaker":"湯澤委員","kind":"意見","question":"それでちょっと意見になってしまうのですけれども、１点、もし可能であれば、このようなものは何か目次とか、そのようなものがあるといいかなと。何か今の説明だと、これはどこだ、どこだとページで追っていくような感じだったので、もしそのようなものがあると、さっと調べられてさらに分かりやすいかなという意見だけ述べします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":117,"id":"exchange-039"},{"speaker":"吉田委員","kind":"質問","question":"１０ページのところの行政費用の内訳という中に、減価償却費と引当金繰入額が一緒に表されているのですけれども、この減価償却費と引当金繰入額はどうして一緒なのですか。ごめんなさい、よく分からないので教えてください。","respondent":"中山会計管理者","answer":"なぜ減価償却費と引当金繰入額かというと、この２つはあまり現金の移動のない、今後の予定の、支出の可能性というところで、１つのカテゴリーとさせていただいています。","voiceIndex":118,"id":"exchange-040"},{"speaker":"つる副委員長","kind":"質問・要望","question":"今回３回目ですね。よく分かるというところで、そもそも新公会計制度の東京都方式ということで、ずっと、大分昔から要望、質問等をさせていただいて、それが取り入れられて、そして、このような形になって３年目ということですよね。それはそれでいいなと思うのですけれども、この過去の質疑を今見る中では、「よくわかる！その数字の位置、これとこれが一致していてなどと。","respondent":"中山会計管理者","answer":"まだまだ改善点はあるかと思いますので、皆さんのご意見をいただきながら、少しボリュームも増やしていこうかと考えているところです。","voiceIndex":120,"id":"exchange-041"},{"speaker":"つる副委員長","kind":"提案","question":"私も過去ずっと、十数年議員をさせていただいて、何年かにわたってこのことを質問しながら、自分も勉強しながら提案して、そして提案して勉強してという形で、それこそ公会計制度とか、会計制度そのものの本を何冊も買って、その読み方も、よく分かる読み方の本まで買わないと分からないぐらい、本当に複雑だなという思いをしながら見てきたわけです。この手のものというのは結構同じような書きぶりなのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":122,"id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2248#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":42538,"voices":130}},{"id":"r04-20221102-14","meetingId":"r04-cm11","date":"2022年11月2日","dateIso":"2022-11-02","committee":"行財政改革特別委員会","time":"午前１０時００分～午後 １時４２分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"新庁舎建築ともなると相当な税金が使われるはずで、高い税金がさらに上がったりしないのだろうかということに対して、国および都からの分担金で確保することを予定していますということで書かれているのですけれども、庁舎の国と都からの分担金というのは、どういう仕組みで、４００億円以上と想定されていますが、それに対して、どれぐらい分担金が来ることになるのかを教えていただきたいのが１点です。","respondent":"大友新庁舎建設担当課長","answer":"こちらの土地の交換で、適正化の根拠、大体幾らなのかというところです。今回、土地の交換や売買という形で取得するものではなくて、土地区画整理事業によって再編されるもので、土地の評価につきましては、売買という金額の形で評価されているものではないと認識しております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それが、およそ何％とか、４００億円に対してどれぐらいとか、試算されているものがどれぐらいなのかということをお聞かせいただきたいのと、土地区画整理事業の再編なので、それが的確かどうかというところがよく分からないのです。土地区画整理事業の再編で７,５００平米が８,３００平米になるということが適正だということは、何を基にして言えるのかというところを教えていただきたいと思います。","respondent":"山下新庁舎整備課長","answer":"２点目の土地区画整理事業に伴う評価ですけれども、建設委員会の報告であったかと思いますが、土地区画整理事業の中で土地評価基準というものが示される中、私どもが聞いておりますところは、その評価基準について、評価委員という方が選任されて。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"その妥当だという根拠はどのような形で示されているのかという辺りは、そういう評価委員が妥当だと言っているので妥当だと判断しているということではないと思うのです。評価委員が妥当だと示している根拠は、議会の中でどこかで報告されているのでしょうか。そこら辺のところを伺いたい。そこの確認をお願いしたいと思います。","respondent":"山下新庁舎整備課長、大友新庁舎建設担当課長","answer":"１点目の議会に報告されているのかという点ですけれども、私どもが認識していますのは、今年の６月２８日の建設委員会で、広町二丁目土地区画整理事業の進捗ということでのご報告があったかと認識しています。２点目の東京都と国の所有につきましては、今、おっしゃっていただいたとおり、所有する割合に応じて、これだけの面積を使うから、そのための分担金ということで、所有割合に応じた分担金となっています。","voiceIndex":9,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ちなみに、今は何％ぐらい使われているということが分かったら教えていただけたらと思います。それと、３３ページに「保健センター機能」というところがあるのです。これも、前に伺ったことがあるのですけれども、別紙２のＳＤＧｓのところでも、３に新たに付け加えたというところで、新庁舎での保健所機能の強化というものが入っているのです。","respondent":"大友新庁舎建設担当課長、山下新庁舎整備課長","answer":"１点目、国・都・区の割合についてですけれども、ざっくりで申しますと、今の現庁舎をベースに考えますと、区が約８割、東京都が２割弱、国が数％という形になるかと思われます。もともとは、ある意味では感染症対策ということを主眼に置きまして、今回、そういった打ち出しをしていったわけですけれども、今回、特に３３ページに多く出てありますし、実際。","voiceIndex":12,"id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"感染症対策ということであれば、今でも庁舎の中に保健所機能があって、保健予防課で感染症対策はやってきたので、これをさらに強化するというのは、強化する保健所機能だけでなく、検査なども含めて、感染症対策ということで強化していくということでしょうか。続いて、別紙２のＳＤＧｓで、８項目の記載を新たに追加ということです。","respondent":"山下新庁舎整備課長","answer":"実際に検査室を新庁舎に設置するとなると、その動線の区分けや、いわゆる医療法的な難しさが出てくるのかなというところ等々、いろいろございまして、それは、これから研究・検討、また、設計の中でどこまで行けるのかというところを考えていく必要があるのかなと考えています。","voiceIndex":15,"id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"もう一つ、最後に伺いたいのは、これは策定委員会の中でも何度か共産党から出て、また、安藤区議からも申し上げておりますし、本会議の中でも申し上げたことですけれども、この要約版の２の検討経緯というところで、一番初めの行財政改革特別委員会での新庁舎の方針についての検討が平成２９年からということで始まっているのです。このようなものは、なぜ検討の中に入らないのでしょうか。","respondent":"山下新庁舎整備課長","answer":"１点目に具体的なセンターの名前がございましたけれども、そういったところを含めまして、今現在、窓口機能については低層階に集約する形で、やはり区民の利便性の向上につなげることを大きな柱として考えておりますので、そういった中での検討と考えています。","voiceIndex":17,"id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この基本設計の案というのは、今回の基本設計の案には一切関わりがないのですか。これだけの税金を使って、同じ基本計画案を委託してきたわけですから、そこのところを入れないというのは、もう絶対おかしな話だと思うのです。なぜ入れないのか。これだけ長い間にわたって、これだけ税金を使って検討し続けてきたことを……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-007"},{"speaker":"あくつ委員","kind":"質問","question":"委員長。繰り返しの質問になっているので、そこについては、速やかなご進行をお願いしたいと思います。ご主張はご主張として。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"同じ品川区の中でありながら、これだけの税金をかけてやってきた基本計画案というものは、こちらとは全く連動していないということですか。","respondent":"榎本新庁舎整備担当部長","answer":"ほとんどは連動していないということで、全くというわけではないですけれども、要は、広町全体を考えるときと、新庁舎の建設予定地が分かって、それに対してどうやろうかというところとレベルが違いますので、そういった意味では。","voiceIndex":26,"id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうしますと、私は、この基本計画案というものが、丸々基本計画案となっているにもかかわらず、そのような形でこれが連動していない、それから、これを踏まえていないということであれば、これまで業務委託して３億円を使った、それから、この問題で言えば、１億何千万円と九百九十何万円ですから、１億６,０００万円。そのような税金の使い方そのものが壊れるということになってくるのではないでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３億円もかけて広町の開発について検討し、庁舎も、それから、隣のにぎわい施設も検討するということで、日建設計と、ＪＲと、品川区が一緒になって、これだけの税金を使って検討してきているわけですから、そこのところと切り離して考えるということはあり得ないと思います。これは、引き続き、様々なところで聞いていきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-011"},{"speaker":"塚本委員","kind":"質問","question":"そういったことについて、この回答では触れていない。そこまで細かく触れられないのかもしれませんけれども、ランニングコストを抑えていくようないろいろな工夫などについての考え方をお伺いしたいと思います。","respondent":"大友新庁舎建設担当課長","answer":"こちらは、ＬＥＤ照明で高効率のエネルギーを使う、また、空調など、高効率を使っていく設備にすることで、ＺＥＢで環境に優しい設備、また、エネルギーを縮減する設備にしていくということを設計段階でも検討していきたいと考えています。２点目といたしまして、保全費の縮減。","voiceIndex":33,"id":"exchange-012"},{"speaker":"塚本委員","kind":"意見","question":"それと、あともう一点ですけれども、４０ページの外観計画というところで、幾つかの方のご意見で、「シンボルとなる」とか、「ランドマークとして」とか、「シンボリックな庁舎」ということで、区民の方々がそのような思いを抱けるデザインということで、区の回答としては、長きにわたり利用される建物として長く愛されるデザイン。","respondent":"大友新庁舎建設担当課長","answer":"品川区らしさを踏まえていくというところも視点に置いておりまして、品川区の歴史を踏まえつつ、周辺と調和したデザインにしていきたいと、現状考えているところです。","voiceIndex":35,"id":"exchange-013"},{"speaker":"塚本委員","kind":"質問・要望","question":"１つお願いしておきたいところとしては、やはり長年にわたり品川区の庁舎という存在になるので、品川区民なのだということが、この庁舎を見ることで気持ちが沸き上がってくるような、品川区民の帰属意識のようなものをしっかりと根づかせていけるような、口で言うのと、現実的にそれを実現するのは相当難しいと思いますけれども、そういうものを１つ考えに入れていただいて。","respondent":"大友新庁舎建設担当課長","answer":"ご意見を踏まえまして、設計段階で精査して、よりよいデザインにしていきたいと考えています。","voiceIndex":37,"id":"exchange-014"},{"speaker":"松本委員","kind":"質問","question":"今日は、パブリックコメントの実施結果と第１０回のところということで、今、委員長からご発言がありましたけれども、できるだけ設計には行かないようにしつつと思いながらお伺いしたいのですけれども、パブリックコメントの中で意見交換などもやってほしいという話もあったかと思います。答申案のほうではこれが維持されているのですけれども、今後、このままのスケジュールで行くご予定なのか、伺います。","respondent":"山下新庁舎整備課長","answer":"現状、こちらは、基本計画案をご答申いただいた後に策定に至るというところでは、再選挙というところは読み込んでいない中で、この素案説明会を８月に実施しての基本計画素案という段階でございましたので、今後、こちらの部分については。","voiceIndex":40,"id":"exchange-015"},{"speaker":"松本委員","kind":"質問・要望","question":"説明会のほうは、またご検討いただければと思いますし、動画の配信だと、質疑応答というところがなかなか難しくなってきますので、説明会という表現はしておりますけれども、やはり設計段階でも区民の皆様のご意見を伺う機会というのは、できるだけ増やしていただきたいなと思います。スケジュールについては、なかなか分からないところもあるかと思いますので、この程度にしておきたいと思います。","respondent":"大友新庁舎建設担当課長","answer":"議会棟の通路であったり、議会棟の一部に大きな窓を設けて、椅子を設けて、見晴らしができる場所を設ける、または、その下の執務機能の一部の場所を一般に開放できるようなところを設けて展望できる、また、おっしゃっていただいたように。","voiceIndex":42,"id":"exchange-016"},{"speaker":"松本委員","kind":"意見","question":"繰り返しになるので、計画自体については、いろいろ考えはあるのですけれども、結構展望部分については、区民の方からもご意見をいただいておりますので、ぜひ引き続きご検討いただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":44,"id":"exchange-017"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ご説明ありがとうございました。策定委員会でも様々質問させていただいたのですけれども、そのときも確認させていただいたことで、もう一度確認をさせていただきたいのです。今回を踏まえて、修正事項についてというペーパーの一番下のＣＭ方式のところに修正が入って、導入も視野に入れるというところから、「活用を企図し」ということで、前回、質問させていただきました。","respondent":"大友新庁舎建設担当課長","answer":"こちらは、国土交通省のマニュアル等でも、業者選定をかなり慎重にやっていかないと、求める成果が出てこないというところもありまして、プロポーザルにて業者をしっかりと見極めて選定していきたいと考えているところです。","voiceIndex":46,"id":"exchange-018"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私も素人ながら、心配なところがあるのですが、そのような時間との戦いになってくるのかなというところで、これは要望も含めてですが、そこについては、慎重かつ速やかにというところで確認させていただき、お願いをさせていただきたいのですけれども、いかがでしょうか。","respondent":"大友新庁舎建設担当課長","answer":"こちらは、我々といたしましても、他の自治体がどのように決めていったというところをいろいろお聞きしながら手法を選定して、業者選定に当たっていきたいと考えています。","voiceIndex":48,"id":"exchange-019"},{"speaker":"あくつ委員","kind":"質問・要望","question":"最後です。できる限り、最大限、そこのところは配慮して、選定に至っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これからの検討委員会の中にも、障害者団体の方々を入れてほしいということもあったと思うのです。これからは、検討委員会というのはつくられないで、設計のほうに入っていくということですか。その中にも入れてほしいという要望があったりしていたと思うのですけれども、どのような形で、どの場面で障害者の方々のご意見を伺っていくのかということを伺いたいと思います。","respondent":"山下新庁舎整備課長","answer":"今回、誰にでも優しく、便利で機能性にあふれる庁舎ということでうたっておりますので、設計を始められる早い段階で、まず、意見聴取に臨みまして、一定このような形でというところをお示しし、また、そういった障害のある方だけでなくて、区民の皆様にもお知らせをした中で。","voiceIndex":52,"id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"設計の業者が決まった後で、速やかにということで考えていいのでしょうか。設計の業者を選定するに当たっても、障害者の方に対しての配慮などが行き届くような業者の選定が必要かなと思うのです。もちろん、その辺りもそのようになってくるとは思うのですが、改めて確認をさせていただきたいと思います。","respondent":"山下新庁舎整備課長","answer":"各設計事業者で、障害者の方の意見を聞かないで設計していこうということをおっしゃるところはまずないのかなと考えていますので、先ほど、別の委員からもございましたけれども、ＣＭ方式、また、基本設計の事業者選定に当たりましては、いろいろな点を複合的に考えながら。","voiceIndex":54,"id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"以前にも世田谷区の庁舎建て替えに当たって、世田谷区にお伺いして、委員会で伺ったことがあったのですけれども、改めて伺いたいことが何点かあるのですけれども、申し上げていいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"１つは、計画の検討に当たり、区民に対しての情報提供と区民参加の位置づけ、その具体的な手法について、伺いたいと思います。それと、３点目には、なぜ中低層にしたのか。高層の建物にしなかった理由について、伺いたいと思います。それから、４つ目が、災害拠点としての本庁舎というものが位置づけられているのですけれども、具体的にどのような機能があるのかを伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-024"},{"speaker":"松本委員","kind":"質問","question":"建設費に関して、物価高騰などの関係で、世田谷区もかなりご苦労されたと伺っています。今後、やはりあちらもＤＸを進められていますので、庁舎のスペースに対する考え方。今後、どのようにＤＸ等の関係で職員数を考えて、スペースを確保する、スペースをどの程度にしていこうと思っていたのか、検討されたのかというところをお伺いできればと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-025"},{"speaker":"あくつ委員","kind":"質問","question":"先ほど、質問もしましたけれども、今、調べると、世田谷区役所もコンストラクション・マネジメントの手法をとっている。事業者も決定したと思いますので、そこについての、いわゆるコンストラクション・マネジメントを入れた成果と課題、また、どれぐらいの費用がかかったのかというところでのコスト、その辺りも教えていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-026"},{"speaker":"渡部委員","kind":"質問","question":"丁寧に説明できる仕組みをどのように考えているのか。要は、マイナンバーカードを持っている人全員から利用者登録をしてもらいたいわけです。本当だったら、５０％ぐらい使ってほしいのだけれども、そこまで上がっていないということは、どちらにしてもその辺がうまく伝わっていないのです。ですから、その辺をどのような意図を持って行政が誘導していくかというのは、僕はすごく大事だと思うのです。","respondent":"河西情報戦略担当課長","answer":"こちらを一度使っていただきましたら、そのよさを分かっていただけると思うのですけれども、確かに、そちらのメリットの訴求方法に関しては、我々、不十分なところもあると思いますので、これから研究してまいりたいと思います。","voiceIndex":72,"id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この４ページの「新システム導入と手続拡充の取組」、私も電子の手続きはよく分からないのですが、１２月１日から開始するということで、本人確認は、このマイナンバーのところを見ると、本人確認の手段の１つとして活用する予定ですとあります。マイナンバーを使いたくない方の本人確認は何で行うことができるのかを伺いたい。その仕組みを教えていただきたいと思います。","respondent":"河西情報戦略担当課長","answer":"支払決済の方法については、オンライン決済になります。具体的には、一番分かりやすいのはクレジット決済です。クレジット番号をネットショッピングなどでも入れられていると思いますが、そういったやり方。ＱＲ決済、口座の引き落としといったところを、今、検討しております。","voiceIndex":76,"id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう人が不利益にならない仕組みというのは、ぜひしっかりとやっていただきたいと思います。それと、６ページのところに、「品川区電子申請サービス」が１から４まであります。これは、何かで区別されなければいけない部分があるのでしょうか。その辺りを少し伺いたいと思います。それから、これを使っていくには、使いやすい仕組みもすごく大事になってくると思うのです。その点も教えてください。","respondent":"河西情報戦略担当課長","answer":"サービスですが、今回、お示しした６枚目のスライドを見ていただきますと４つあります。基本的には、１番の「品川区電子申請サービス」に載せていく予定です。こちらの１番のいいところは、先ほどご説明しましたが、汎用的な手続き、事務フローに対応しているところです。","voiceIndex":78,"id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この項目は電子申請ができますという一覧表みたいなものはどこかに案内されるのでしょうか。その点を伺いたいと思います。そういう電子サービスの項目と、品川区が条例で定める、区として紹介したりするときに使う条例の中に定める事業というのは、どのように関わってくるのか、関わりがないのか、その点も教えてください。","respondent":"河西情報戦略担当課長、宮澤情報推進課長","answer":"こちらは、今の総手続き数に対して、オンライン化の手続きの数を記載しております。これから具体的な手続き面に関してもホームページで掲載する方向で検討を進めております。先ほど説明で言ったマイナンバーカードを活用するというのは、申請する際の本人確認のために使うということで、マイナンバーを使っているというわけではございません。","voiceIndex":80,"id":"exchange-030"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"分かりました。マイナンバーを使わなくても申請できるということですし、マイナンバーを使わなかったことによって不利益は生じないということだと思います。最後に、高齢者のスマホ教室ですけれども、これは、開催箇所を拡大したということです。高齢者スマホよろず相談、これはどこでやっているのか、どのように拡大したのかを具体的に教えていただきたいと思います。","respondent":"宮澤情報推進課長","answer":"併せて、スマホよろず相談につきましては、その３か所プラス、平塚橋ゆうゆうプラザ、大井三丁目高齢者憩いの場というところでも行っている状況です。","voiceIndex":83,"id":"exchange-031"},{"speaker":"あくつ委員","kind":"質問","question":"引き続き、よろしくお願いします。午前中の議論でもあったのですけれども、今回、一般質問でも質問しましたが、マイナンバーカード活用の取組のところをお伺いします。時間がなかったので、あまり一般質問では言えなかったのですけれども、今、交付率がナンバー１からナンバー１０まで出ているのですが、ナンバー２からナンバー１０までは、全部１０万人以下の小さな都市です。そこからまずお伺いします。","respondent":"宮澤情報推進課長","answer":"区の職員のマイナンバーカードの保有に関しては、情報推進課としては把握、調査等はしていないという状況です。","voiceIndex":87,"id":"exchange-032"},{"speaker":"あくつ委員","kind":"質問","question":"例えば、私は行政書士ですけれども、行政書士会などは、総務省を通じて、行政書士の方にはマイナンバーカードを取得するようにということでの依頼文書が来ているのです。品川区役所には、自治体に対して、職員にこういうものは来ているのでしょうか。","respondent":"堀越総務部長","answer":"所持状況を見ながら、例えば、共済組合のいろいろなサービスについて、そういったものを活用していくとか、そういうものを検討していくという、まだ途上の段階であると認識しています。","voiceIndex":89,"id":"exchange-033"},{"speaker":"あくつ委員","kind":"質問","question":"すみません。後半の部分で、先ほどの質問で、国から自治体に対して、職員の方については、マイナンバーカードを積極的に取得してくださいという取得依頼が来ているのか、来ていないかというのは、今、分かりますか。","respondent":"堀越総務部長","answer":"その調査の中で、実際にそのような文言があったかどうかというのは記憶にないのですけれども、ただ、本人の希望でのアンケート調査の形式でありまして、前提になる位置づけははっきりお答えできないのですが、回答について。","voiceIndex":91,"id":"exchange-034"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ここに書いてある、いわゆる戸籍や住民票についても、一般質問でも申し上げましたが、一律１５０円にしたら、品川区の場合は十数％ですけれども、当然、それなりに安ければみんなコンビニで取るということで、半分ぐらいがもうコンビニで取っている。簡単です。窓口に並んで待って取るより、自分で機械で取ったほうが早いですから、そのようなこともされてきた。ほかにもいろいろなことをやっています。","respondent":"宮澤情報推進課長","answer":"マイナンバーカードの利活用です。委員にご指摘いただきました、職員の出退勤や図書カードをカード自体の空き領域を使って活用しているという自治体の例も認識しているところです。","voiceIndex":93,"id":"exchange-035"},{"speaker":"あくつ委員","kind":"質問・要望","question":"マイナンバー制度が始まってから７年ぐらいですか。もう少したっているのですか。そういう中で、９月末で全国的には４９％ぐらいですか。品川区はその上を行っているのですけれども、独自の利活用ということについて、それに全精力を注力するのも少し違うのかなとは思うのですが、やはり品川区として独自の利活用を考えていただきたいなというところです。その辺のお考えをお伺いしたいと思います。","respondent":"久保田企画部長","answer":"今のところは、区としてはコンビニ交付等ができるメリットしか訴えることができませんけれども、今後、独自活用でどういったものができるかということについても研究していきたいと思いますし、また、そういったものがあれば、幅広く取り入れて進めていきたいと考えております。","voiceIndex":95,"id":"exchange-036"},{"speaker":"あくつ委員","kind":"質問","question":"都城市の例ばかりで申し訳ないのですが、７年前にこの取り組みを始めたときには、まず、職員の研修から始めたそうです。デジタル研修は、皆様さんざんやっていらっしゃると思うのですけれども、先ほど、一番最初に申し上げたように、職員の方の取得率はどうなのですか、交付率はどうなのですかと申し上げました。ですから、これは絶好の機会というか、必ずインフラにすべきものだと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":97,"id":"exchange-037"},{"speaker":"塚本委員","kind":"質問","question":"初めに、「品川区電子申請サービス」を始められるということでお伺いします。これは、マイナンバーカードを持っていない方もいらっしゃるということで、そのような方々については、これまでどおり紙による申請をして、ＩＤ申請をして使っていただくというご説明がありました。このような仕組みにしたことについて、なぜかなというところを少しお伺いしたいと思います。","respondent":"河西情報戦略担当課長","answer":"今のご質問にお答えします。今回、新しく始める新サービスですが、システムの考え方について、ご紹介します。システムの考え方ですが、まず、システムで取り扱う手続きは、マイナンバーが必要なものと、そうでないもの、２種類を扱います。","voiceIndex":99,"id":"exchange-038"},{"speaker":"塚本委員","kind":"意見","question":"分かりました。これは、少し細かな話になるのですけれども、品川区から区外に転出された方々の申請されたＩＤというのは、今のお話で言うと、多分マイナンバーがあるから、自動的に削除されるということにはならずに、別のやり方で管理というか、転出された方は削除していくということになるのか。そこのところをご説明いただければと思います。","respondent":"河西情報戦略担当課長","answer":"今のご質問にお答えします。基本的には、先ほどご紹介したとおり、手続きは２種類ございまして、マイナンバーを利用するものと、しないもの。対象者に関しても、基本的には品川区民となっておりますが、マイナンバーの認証をかける際に、住所情報が確認できます。","voiceIndex":101,"id":"exchange-039"},{"speaker":"塚本委員","kind":"質問・要望","question":"これは、情報システムの担当にお答えを求めるのは少し難しいかもしれないですが、そういうクレジットカードを持たないために、来庁しないオンラインでの行政サービスの外に置かれてしまう方が一定程度いるのだなということに対して、何かしらオンラインでの決済をできるようなことを考える。研究から始まるのかもしれませんが、やはりそのようなことは必要ではないかなと思うのですが、いかがでしょうか。","respondent":"宮澤情報推進課長","answer":"事業者にお話を聞きますと、やはりそういう引き合いがありますので、ＱＲコードの会社もいろいろありますが、取扱いを少しずつ増やすという方向は聞いておりますので、そういったところでサービスを提供できればと考えております。","voiceIndex":103,"id":"exchange-040"},{"speaker":"塚本委員","kind":"質問","question":"分かりました。そこら辺についても、そのように手を打っていただいているということで、大変すばらしいと思います。クレジットカードがないということは、そういうことでしょうか。スマホ等にアプリを入れて、そのスマホのアプリが銀行口座とひもづいて、そこで決済ができますという仕組みなのでしょうか。","respondent":"宮澤情報推進課長","answer":"先ほどのいわゆるＱＲコードの仕組みですけれども、１２月のスタート時からの実装は難しくて、年明け以降になってくるところです。そのお支払いの中身やブランドについては、今、調整しているところですので、詳細については、お答えできない状況になっております。","voiceIndex":105,"id":"exchange-041"},{"speaker":"塚本委員","kind":"質問・要望","question":"分かりました。いずれにしても、来年になれば、その辺がもう少し明らかになるということです。オンライン申請等で、来庁せずに区民サービスを受けられる。これも、ある意味でのデジタルデバイドになるような話であるので、そういったことの解消に向けてしっかり取り組んでいただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":107,"id":"exchange-042"},{"speaker":"西村委員","kind":"質問","question":"電子申請について、伺います。「ぴったりサービス」や「ＬＩＮＥ申請サービス」など、サービスが様々あっても、「品川区電子申請サービス」で、まず窓口のフロントの部分が一括されるというのが大変いいなと感じておりまして、ご質問をします。１２月１日からぜひとも分かりやすくお願いしたいなと考えています。","respondent":"河西情報戦略担当課長","answer":"今回の新しいサービスの区民への周知ですが、広報紙を利用した周知や各種ＳＮＳを使って周知を行ってまいりますので、そういったところで区民の方にもしっかり情報発信していきたいと考えております。","voiceIndex":109,"id":"exchange-043"},{"speaker":"西村委員","kind":"提案","question":"ＳＮＳ、広報紙はそうですけれども、度々、ＬＩＮＥだとセグメント配信ができるということを提案させていただいておりまして、若い方ではなくて、６０、７０代の方でもＬＩＮＥを使っている方が増えてきたなという肌感覚があります。ですので、この「ＬＩＮＥ申請サービス」はシナジーがたくさんあるのではないかなと考えていますが、その辺りのご意見をお聞かせください。","respondent":"河西情報戦略担当課長","answer":"お言葉のとおり、確かにＬＩＮＥの利用者はかなり多いですので、利用されているＳＮＳに、しっかり漏れなく配信していきたいと考えております。","voiceIndex":111,"id":"exchange-044"},{"speaker":"西村委員","kind":"質問・要望","question":"例えば、粗大ごみの受付システムをＬＩＮＥ申請でしている自治体がありまして、支払いまでＬＩＮＥＰａｙで完結してしまうということで、コンビニまでチケットを買いに行かなくてもいいと伺っていますので、ぜひとも参考にしていただきたいと考えています。全部で１２か所あったかと思うのですけれども、あと残り４か所は、令和４年度目標の２９か所の中に入っていますでしょうか、お聞かせください。","respondent":"宮澤情報推進課長","answer":"今年度の２９か所については、その３か所は含まれておりません。キャッシュレス決済の目標値というのが、令和５年度は３８か所を目標としておりまして、所管部署と連携しながら検討していきたいと考えております。","voiceIndex":113,"id":"exchange-045"},{"speaker":"西村委員","kind":"意見","question":"このオンライン化に関しましては、オアシスルームはキャッシュレスですけれども、申請件数が多くて需要が高い手続きからということが、すごくありがたいなと思っていますので、同じようにオアシスルームも大変ニーズが高いですので、引き続き、実施をお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":115,"id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6140#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":38995,"voices":121}},{"id":"r04-20221102-10","meetingId":"r04-cm11","date":"2022年11月2日","dateIso":"2022-11-02","committee":"議会運営委員会","time":"午後 ０時４５分～午後 ０時４７分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5484#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":1171,"voices":8}},{"id":"r04-20221104-19","meetingId":"r04-cm11","date":"2022年11月4日","dateIso":"2022-11-04","committee":"災害・環境対策特別委員会","time":"午前１０時００分～午後 ０時１４分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を55件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"３点ほどあります。前回も指摘しましたけれども、脱炭素社会の実現のやはり大きな障害となっている石炭火力発電の廃止、それから原発ゼロ、これをやはり国に働きかけていくことを、区の環境基本計画に盛り込んでおくべきだと、私はこの日常的に実践する人という形で実践主体を問題にするなら、やはり一言でも入れておくべきではないかと思ったのですが、その点、どうお考えになっているか伺いたいと思います。","respondent":"河内環境課長","answer":"したがいまして、区民の方にご提案するこの計画の中につきましては、このような表現の中でしっかりして推進していくというような考えです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"おくの委員","kind":"質問・要望","question":"それで、私の要望としては入れていただきたいということは言っておきたいと思います。環境団体からも多々指摘されて、岸田首相が会議に出るたびに環境団体からは化石賞をもらったりしているわけですから、品川区はそういう環境団体と同じように、真剣にカーボンゼロを目指しているのだということを宣言する意味でも、環境基本計画に盛り込んでいただきたいと思います。意見・要望として述べします。","respondent":"河内環境課長","answer":"したがいまして、大事なものをしっかり受け継ぐというところの精神と、見つけることといったものは既にこの中に合わさっているというふうに考えてあります。なお表現の中で、今委員がおっしゃったような形で取り入れたいと考えていますが、現在のところ、検討状況は今の状況です。","voiceIndex":7,"id":"exchange-002"},{"speaker":"おくの委員","kind":"質問・要望","question":"そういう私の要望・意見ということで、受け止めていただければと思います。それから３番目は、基本目標１のところなのですけれども、これが前回の案では「脱炭素社会」を実現するとそのものずばりの表現だったのです。以上のことから、元の案を生かしたものにするほうがいいと私は思ったのですけれども、その点いかがでしょうかということです。","respondent":"河内環境課長","answer":"将来に向けての対応といたしまして、区民の皆様に意識の向上、意識の醸成ではないのですが、そういったものを取り組む社会とともに、それに付加するような暮らしをいろいろ考えていただきたいというところが計画の大事な点だと思っておりまして。","voiceIndex":9,"id":"exchange-003"},{"speaker":"おくの委員","kind":"意見","question":"そういう意味で、やはり今回のほうは弱められているなという印象が強いので、私はそういうふうに思っているということで受け止めていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":11,"id":"exchange-004"},{"speaker":"田中委員","kind":"質問","question":"裏面なのですけれども、先ほどもあった８月２４日の案と見比べたときに、まず共通目標のところの施策の中で書き加えられたというか、この「他地域での環境活動の促進」とあるのですけれども、これがどういう意味なのかというところを伺いたいというのと、基本目標４のところで、前回では、「化学物質の適正な管理に努める」という文言があったのですけれども、そこがなくなってしまいました。","respondent":"河内環境課長","answer":"こちらにつきまして、施策の中のものとして、案として挙げておりましたが、取組内容の中できちんと取り上げるというところで、全体でいきますと「すこやかな暮らしを守る」で例示が書いてありますが、こういったものを進めていきたいというところで考えているところです。","voiceIndex":13,"id":"exchange-005"},{"speaker":"田中委員","kind":"質問・要望","question":"水素のところなのですけれども、基盤整備ということで、８月２４日のときにも伝えたのですけれども、ぜひグリーン水素の考え方ということで受け止めたいと思うのですが、いかがでしょうかというところと、サスティナブルファッションの推進についても、より強い言葉でＣＯ２の削減のためにということだったのですけれども、プラスチックを使って服にするといった。","respondent":"河内環境課長","answer":"そういったところの意識を変えることによりまして、平均でワンシーズンで６着、７着と言われているものをより吟味し、さらにそういった素材がリサイクルできるようなサイクルに落ち着くというところで、プラの削減にもつながるというところで、大変重要な取組と認識しています。","voiceIndex":17,"id":"exchange-006"},{"speaker":"田中委員","kind":"質問・要望","question":"１点だけ。学生が多く参加されているということは理解しました。ただ、その学生たちが今どういうことを思ってとか、どういったことを知っていってとか、そういうことも分かるような、やはりその方たちが特定されるような表現ではなくて、委員の発言、それに対する答弁とか意見交換の状況が分かるような、やはり議事録というのはぜひ公開していただきたいと思うのですが、いかがでしょうか。","respondent":"河内環境課長","answer":"要望として承りました。そのように努めたいと思います。","voiceIndex":19,"id":"exchange-007"},{"speaker":"中塚委員","kind":"質問","question":"素案に向けた検討状況ということでご説明を伺いました。まだこれは概要の資料ですけれども、やはりこの環境基本計画そのものにそうした地球規模の気候危機を克服しなければならない、また、今手をつけなければ、熱波や干ばつや巨大なハリケーンなど、深刻な状況になると。そういう危機認識をしっかりとまず品川区環境基本計画の前提に据えることが必要だと思うのですけれども、その点伺いたいと思います。","respondent":"河内環境課長","answer":"ご意見ありがとうあります。地球温暖化に向けて大変厳しい状況である点、こういったものを背景、状況といたしまして、巻頭からそういった説明をした上でこういった取組というような流れで、案につきまして作成したいと考えているところです。","voiceIndex":22,"id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"それと、続けて今後のスケジュールについて少し伺いたいのですけれども、１２月上旬と１２月中旬から下旬に、課長級の環境対策庁内会議と部長級の環境対策推進会議とそれぞれ設定されておりますけれども、ぜひ議事録を作成していただきたいという点と、公表をしていただきたいと思うのですけれども、それぞれいかがでしょうか。","respondent":"河内環境課長","answer":"環境基本計画にしっかり位置づけるという点。そちらの考えにつきましては、私どもも同じという点で、しっかり環境基本計画の中に、今回カーボンハーフになぜ至るのかというようなところはしっかりと説明させていただきたいと考えています。","voiceIndex":24,"id":"exchange-009"},{"speaker":"中塚委員","kind":"確認","question":"議事録の作成と公表ですけれども、今の説明ですと、この課長級の環境対策庁内会議と部長級の環境対策推進会議は議事録を作成するということと、いろいろな形の公表もありますけれども、例えばホームページに示すということでよいのか、確認させてください。","respondent":"河内環境課長","answer":"そういったところも踏まえ、前向きに検討させていただきたいと考えております。","voiceIndex":26,"id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"検討するということで、やはりどういう議論の経過でこの素案ができたのかということの経過をしっかり公表するということが必要だと思います。少なくとも１３地域センターごとに、品川区がその素案について説明をし、１か月間のパブリックコメントがありますので、ご意見・ご要望をこの場でも伺いますし、後ほど郵送でもメールでもという説明会を開催していただきたいと思いますが、いかがでしょうか。","respondent":"河内環境課長","answer":"パブリックコメントの経過・結果に基づく説明ですが、現状エコルとごしにおきまして、こういった説明会をさせていただきたいという考えで検討を進めているところです。","voiceIndex":28,"id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"エコルとごしで説明会をということですけれども、その狙いや目的は何かということを伺いたいと思います。改めて、やはり区内全域で開催することが必要だと思うのですけれども、エコルとごしだけではなく、各地域センター管内ごとに説明会を開いていただきたいと思うのですが、いかがでしょうか。","respondent":"河内環境課長","answer":"そういった中で、そういった記載を壁などに張っているものから含めまして、しっかりと発信できればというようなところがありまして、エコルとごしというところで考えているところです。１３地域につきましては、今後の検討事項にしたいと考えています。","voiceIndex":30,"id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"この品川区環境基本計画に限らず、パブリックコメントを開催する際にはぜひ説明会をとこの間求めてきました。住民参加は徹底した情報公開の下で保証されると思います。なので、ぜひパブリックコメントをする際には丁寧な説明会を行って進めていただきたいと思うのですけれども、改めていかがでしょうか。","respondent":"河内環境課長","answer":"説明会など、それから今後、予算の中で出てくるかと思いますが、動画など分かりやすくお手元に届きやすいものをいろいろ作りまして、こういったものを取り組んでいただきたい、こういった目標に向かってみんなで頑張ろうというようなところで。","voiceIndex":32,"id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"区が勝手に決めました。区民の皆さん、これ、どうぞではなくて、自分も参加してその計画をつくることによって、今回で言えば品川区環境基本計画の実施に向けて、区民自らが主体者となって取り組むことができる。そういう関係もあると思いますので、様々な行政計画を策定する際には、住民参加・情報公開の徹底を改めて求めたいという要望で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-014"},{"speaker":"田中委員","kind":"質問","question":"今もありました環境学習交流施設、エコルとごしのところで、資料の裏面の共通目標の施策の中の２個目に、８月２４日には「子どもと大人が一緒に行う環境学習」という文言があったのですけれども、それも今回消えてしまったのがとても残念だったなと思って、これはどういう意図でなくなってしまったのかというところを伺いたいのと、やはり子どもと大人が一緒にというのはとてもいいと思っていたので。","respondent":"河内環境課長","answer":"そういった中で、こういった項目づけの中で文言として整理したものです。今、委員がおっしゃった意見につきましては、参考といたしまして、今後の検討事項といたしたいと考えております。ありがとうございました。","voiceIndex":36,"id":"exchange-015"},{"speaker":"つる委員","kind":"質問・要望","question":"裏面の基本目標２－４、これは前回８月のときも確認をさせていただきまして、「地域循環共生圏（ローカルＳＤＧｓ）の形成推進」、「地産地消の推進」、「サスティナブルファッションの」当時は「啓発」で、今回「推進」ということで、より強い表現に進めていただいたと先ほどの答弁で伺いました。それがエシカルの部分の領域になってくるのかもしれませんけれども、地産地消のとこも入ってくると思うのです。","respondent":"河内環境課長","answer":"今後様々なお声を生かしながら、こういったところを進めてまいりたいと考えているところです。","voiceIndex":39,"id":"exchange-016"},{"speaker":"つる委員","kind":"質問・要望","question":"この会議そのものに小・中学生の参画をということは求めてきている中で、非常に意識をしていただいて、まずは知っていただく機会を広げていただいたのかなという理解で受け止めましたけれども、なので、やっていること自体を概要として伝えるということも大事ですし、なぜそれをしなくてはいけないのかというその時系列のつながりですね。それとあともう一つ、併せて伺います。","respondent":"河内環境課長","answer":"ウォーカブルの点ですが、環境面ということなので、脱炭素に向けてという点、やはり考えているところではありますが、こういった中身につきまして、まず啓発の中で意識の醸成も含めましてきちんと掘り起こした上で、環境面等を踏まえいろいろなところに計画は絡むと思うのですが。","voiceIndex":41,"id":"exchange-017"},{"speaker":"つる委員","kind":"質問・要望","question":"ありがとうございました。それがしながわ健康ポイントですね。そういうのがあったりすると思うのですけれども、そういうのをうまく結びつけて、まさに歩きたくなる、ウォーカブルな取組については、区全体として取り組んでいただきたいと思います。身近なところというところで、これは質問ではないですけれども、歴史学者でアーノルド・トインビーという人がいるのです。要望です。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-018"},{"speaker":"新妻委員","kind":"質問・要望","question":"ご説明ありがとうございました。１点だけ確認します。先ほどこの環境基本計画中間見直しにあたって、パブリックコメントが終わり、その後の説明会をエコルとごしを活用して行っていくという話がありました。この環境基本計画の冊子の中でエコルとごしの紹介があるのかというようなところをどのようにご検討されているのか、お知らせいただきたいと思います。","respondent":"河内環境課長","answer":"そういったところを含めまして、いろいろな方がやはりこの環境基本計画を担っていき、全体で一丸となって達成するというようなところの醸成を当該施設でしっかり担っていきたいというような考えで、現在進めているところです。","voiceIndex":45,"id":"exchange-019"},{"speaker":"新妻委員","kind":"質問","question":"そうすると、この冊子の中には特にエコルとごしの表現というのは入ってこないということでしょうか。","respondent":"河内環境課長","answer":"エコルとごし自体は紹介いたしますが、そういった単にハードだとかで、これをこうやったとかそういったところにとどまらず、こういった機能をぜひ活用しながら、皆様の中でこういったことをやっていただきたいというようなところで、環境登録団体しかり、ボランティアしかり。","voiceIndex":47,"id":"exchange-020"},{"speaker":"たけうち委員","kind":"質問","question":"おもて面の表４で業務というのがあって、それ以外の農業、建設業、製造業とあって、これも業務だと思うのですけれども、ここを特出して出しているというのは、何か国のほうでそのような感じになっているのか、区のほうでそういう考えで出しているのかということと、それから廃棄物が出ていますけれども、家庭と業務の中でも廃棄物が出るのですけれども。","respondent":"河内環境課長","answer":"こちらにつきましては、オール東京６２市区町村共同事業というものがございまして、そちらの中で、この該当項目につきまして、こういった数値を取りまとめているです。各区とも共通なものでございまして、それに照らし合わせました数値が、今回このように出ているところです。","voiceIndex":50,"id":"exchange-021"},{"speaker":"たけうち委員","kind":"質問","question":"これで見ると、廃棄物の全体の割合としてはＣＯ２の排出量は低いのですけれども、廃棄物のところだけが基準年と比べて増えているということを考えると、この部分での取組というのは、クローズアップしていくのは非常に大事なのかなと思うのですけれども、この理由としてはやはり簡単に言うと、廃棄物が増えているということなのでしょうか。","respondent":"河内環境課長","answer":"改めましてそういった面について啓発をしっかりやっていきながら、ここの数値の低下に向けてというところで、一般廃棄物処理基本計画に合わせまして、連携をとりながら進めてまいりたいという考えです。","voiceIndex":52,"id":"exchange-022"},{"speaker":"たけうち委員","kind":"意見","question":"区民の方が見て、単純にやはりここをもし計画で出すとすれば、ここが増えているのだなというところで、自分たちができるのは何なのかなという、多分そういうところでくると思いますので、恐らくこの裏面の計画のところでもそこが強調されてきていると思うのです。食品ロスですとかプラスチックのことですね。そういったところを分かりやすく、ぜひ計画の中で位置づけていただければと思います。","respondent":"河内環境課長","answer":"一方で、こういったものにつきまして、まずはごみの減量化というものも非常にこの中に絡んでまいりますので、委員のおっしゃるとおり、分かりやすい、何を取り組んだらいいのかという点につきまして、取組の中で取り入れながら計画を進めてまいりたいと考えております。","voiceIndex":54,"id":"exchange-023"},{"speaker":"須貝委員","kind":"質問","question":"いろいろ環境基本計画を見直すのは、すごく大変だなと。基本的に私が思うのは、１つは行政が音頭を取るということですが、やはりそこには、購入する側、使用する側の区民に対しての普及啓発。そして事業所。その加工方法。そういうのも全然整ってない中で、今目標は立てられているのですが、これで本当に大丈夫ですかという、逆に疑問すら覚えてしまうのです。そういう点について、ご見解をお聞かせください。","respondent":"河内環境課長","answer":"全文はなかなか皆さん読まないでしょうし、それから業界の方につきましてもやはり立場を考えていろいろ発信いたしませんと、電気自動車の例を挙げていただきましたが、現在例えば日産の某軽自動車の電気自動車など、国と都の補助金を合わせれば１００万円近くの補助金が出て。","voiceIndex":57,"id":"exchange-024"},{"speaker":"須貝委員","kind":"質問・要望","question":"電気自動車は補助金もありますよ。車検も安い。販売されるスーパーでいろいろなもの売っていますけれども、ですから、本当に区からも発信していただきたいのは、やはり国が引っ張っていっているのですから、財源がもうないのだと思うのだけれども、やはりどこかからひねり出して各自治体に配って、そして区民に、皆さんこうやってちゃんと補助金を出しますよと。もしご意見があったらお願いいたします。","respondent":"河内環境課長","answer":"要望としてはよく理解いたしました。そのような形も念頭に踏まえまして、進めてまいりたいと考えております。ご意見ありがとうございました。","voiceIndex":59,"id":"exchange-025"},{"speaker":"のだて副委員長","kind":"確認","question":"先ほど反映はもちろんしていきますということでしたけれども、４月１日の環境基本計画運用開始まで何も手順が示されていないので、ここにどうやって反映をさせていくのかというところを伺いたいと思います。それと、先ほどエコルとごしでの説明会のお話がありましたけれども、これはパブリックコメントの期日の前にやるのか、後にやるのか、そこも確認したいと思います。","respondent":"河内環境課長","answer":"説明会の件につきましては、そういったものが決定されたものにつきまして、皆さんがどういうふうにお守りいただいて進めていただきたいかという説明会ですので、その後になるものです。","voiceIndex":61,"id":"exchange-026"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"パブリックコメントの意見反映は、変えるべきものは変えるということですけれども、この手順が示されていなかったので、今回環境対策庁内会議などで検討して、反映させていくのかどうかというところを確認させていただきたいのと、エコルとごしでの説明会がパブリックコメント後ということで、やはりこのパブリックコメントに意見を出すためにも、説明会をぜひやっていただきたいと思うのです。","respondent":"河内環境課長","answer":"パブリックコメントの内容につきましての説明会につきましては、これは現状まだやるつもりはございません。結果につきましての周知・啓発に向けて、力を尽くしてまいりたいと考えているところです。","voiceIndex":63,"id":"exchange-027"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"パブリックコメント前に説明会をやるつもりはないということですけれども、やはりここは意見をしっかり集めるためにもやるべきだと思いますし、当然その後、啓発のためにやっていくということも必要だと思いますし、そこはやはり充実させていくということが私は必要だと思いますので、ここは要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-028"}]},{"id":"topic-02","title":"令和４年度区内一斉防災訓練の実施","agenda":"令和４年度区内一斉防災訓練の実施","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"医師会の方から、より有効な医療救護活動を展開するために要望を伺っておりますので、それに関連して質問いたします。それから２点目、学校医療救護所における医療救護活動に従事する医師の受入れ体制が明確になっていないとして、医師の休憩場所の確保や飲料水や食料の提供など、支援体制の確立を要望されていますが、この点いかがでしょうかというのが２点目です。いかがでしょうかというのが３点目です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-029"},{"speaker":"おくの委員","kind":"質問・要望","question":"検討中ということで、検討を進めていただきたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-030"},{"speaker":"田中委員","kind":"確認","question":"すみません。伺いたいのですけれども、防災訓練の実施の周知方法と、町会の方だけしか参加できないとかそういうことはないと思うのですけれども、そこの確認と、今、新型コロナウイルスの感染者数が増えてきている中で、この実施時期にもしそういったことがあったら人数制限とかがされてしまうのかとか、そういった部分についても伺いたいと思います。","respondent":"五十嵐災害対策担当課長","answer":"コロナ禍の人数制限につきましては、基本的には区としましては、感染防止用品は貸与しますよという形でお話はさせていただいているところですが、各避難所のほうで人数制限を実施するとか、あるいは分散実施をするとか。","voiceIndex":76,"id":"exchange-031"},{"speaker":"田中委員","kind":"質問・要望","question":"感染拡大を抑止するため、広がらないようにするための人数制限も必要だと思いますし、あと町会に入っていない方でもやはり防災訓練には参加してほしいですし、特にやはり障害のある方には参加していただきたいと思いつつ、この感染状況も不安だしという、とても曖昧というか何というかというところなのですけれども、ぜひ周知のほうと、感染状況によって。","respondent":"五十嵐災害対策担当課長","answer":"訓練は公助と共助のほうをメインに実施していくわけなのですけれども、もちろん町会・自治会以外にＳＮＳやホームページ等を使って周知はさせていただきたいと思っています。","voiceIndex":78,"id":"exchange-032"},{"speaker":"中塚委員","kind":"質問・要望","question":"今の質疑にも関わるのですけれども、区内一斉防災訓練の実施ということですけれども、障害がある方の参加の保証について、その視点があるのか、ないのか伺いたいと思います。ぜひ障害がある方の訓練の参加もしっかりと位置づけていただきたいと思うのですか、いかがでしょうか。","respondent":"五十嵐災害対策担当課長","answer":"これの狙いというのは、今後、町会・自治会が実施するような地区防災訓練等々に参加していくのに、障害者の方々がストレスなく入っていく、さらに町会のほうもストレスなく受け入れられるような、そのデリケートな部分についていろいろとヒアリングしながら。","voiceIndex":81,"id":"exchange-033"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ、この区内一斉防災訓練についても、この障害がある方の参加を保証していただきたいと思いますし、保証するというかその参加を位置づけていただきたいと思います。それがひいては実際の災害が起きた際の対策にもつながっていくという視点で、障害者７団体など各団体のヒアリングを位置づけていただきたいと思うのですが、その点いかがでしょうか。そこも伺いたいと思います。","respondent":"五十嵐災害対策担当課長","answer":"障害のある方の位置づけにつきましては、先ほどの繰り返しになってしまうのですけれども、参加する方が参加した際にストレスを感じてしまうようだったら、訓練から離れていってしまいますし、受け入れるほうもストレスを感じるようになってしまうと。","voiceIndex":83,"id":"exchange-034"},{"speaker":"中塚委員","kind":"質問・要望","question":"今、課題の抽出をされているということですけれども、そういう意味でも、障害者７団体のヒアリングをぜひ実施していただきたいのと、実際、どういった方が参加をしているのか、障害がある方の人数とか、そういう実態の把握を位置づけていただきたいと思いますけれども、いかがでしょうか。","respondent":"滝澤災害対策担当部長","answer":"障害者の受入れについても、今、福祉部で福祉避難所に避難をされる方と、一般の区民避難所に避難をされる方というのを明確に分けるということもやっておりますので、その辺も具体化したときに、訓練の中にも内容を盛り込みながら。","voiceIndex":85,"id":"exchange-035"},{"speaker":"中塚委員","kind":"質問・要望","question":"福祉避難所に避難される方と、一般の学校に避難される方、今様々整理されているということで、ぜひ進めていただきたいと思います。最後に一言意見だけ。今、様々検討中だということなので、ぜひ参考にしていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-036"},{"speaker":"田中委員","kind":"確認","question":"すみません。先ほどの質疑で確認したいのですけれども、１０月２１日のヒアリングと防災体験館での体験をされたのは聴覚障害の方たちだけなのか、それとも、ほかの障害種別の方も、ほかの日とかにヒアリングと防災体験館での訓練をされているのか、それとも今検討がされているところなのかというところだけ確認させてください。","respondent":"五十嵐災害対策担当課長","answer":"聴覚障害者団体にだけ、１０月２１日にお伺いなのかということなのですけれども、そのとおりです。聴覚障害者の団体の方々から、東京都と品川区の合同総合防災訓練のヒアリングをする際に、プラスアルファでしながわ防災体験館でご体験をしていただいたというところになります。","voiceIndex":89,"id":"exchange-037"},{"speaker":"田中委員","kind":"確認","question":"今後はほかの障害種別の方たちにも防災に関するヒアリングを行って、防災体験館でも体験をしていただくというような、そういう計画はあるのかないのかというところを確認させてください。","respondent":"五十嵐災害対策担当課長","answer":"他の障害者団体でそういった計画があるのかというところで、現在のところはありません。ただ、聴覚障害者団体の訓練がある程度進むようになったら、そちらのほうも進められればなというふうには思っております。","voiceIndex":91,"id":"exchange-038"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひほかの障害のある方たちにも、ほかの方たちもすごく焦っていますので、いつそういう災害が起きるかも分からないですし、ぜひ早めにヒアリングだったりとか、訓練だったりとか、そういったものに参加できるような体制をぜひ整えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":93,"id":"exchange-039"},{"speaker":"小芝委員","kind":"確認","question":"は確認をしたいのですけれども、今回の訓練、発災３日後の区の対応を実施されるということなのですが、これは区民避難所での訓練も、同様に発災３日後のことを対象としているのかどうか、まず確認をお願いします。","respondent":"五十嵐災害対策担当課長","answer":"ただ、学校参集職員は、３日後想定の物資の要求等をパソコン等を使って通信しながら対応するというような訓練も、今検討しております。","voiceIndex":95,"id":"exchange-040"},{"speaker":"小芝委員","kind":"確認","question":"一応切り離して考えているということで、学校に参集される職員は３日後のことを想定しているということで、確かに発災３日後に避難されることというのはなかなかイメージしづらいものでしたので、それで安心といいますか確認できましたので、ありがとうあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":97,"id":"exchange-041"},{"speaker":"新妻委員","kind":"質問・要望","question":"そうすると町会・自治会も、そういう方たちにも声をかけていいのだ、声をかけていく必要があるのだという意識づけになっていくのではないかなと思っていますし、この１２月に開催される中で、もし町会・自治会のほうからそういう方々が参加をされるということで何か必要なことがあるのであれば、ぜひ区にご対応いただきたいと思うのですけれども、いかがでしょうか。","respondent":"五十嵐災害対策担当課長","answer":"障害者の方を受け入れるには、私は障害者団体の方々にもいろいろとお勉強していただくことが必要だと思いますし、また、受け入れる町会・自治会の方々にも勉強していただくことがあるのかなと思っておりまして。","voiceIndex":99,"id":"exchange-042"},{"speaker":"松澤委員","kind":"質問・要望","question":"本当に形骸化していない訓練というのが、品川区はできているといいますか、できているというのは、すみません、上から目線ですけれども、放水訓練は放水訓練、映像を見る訓練は映像を見る訓練、本当に町会の中でしっかりばらけて、それがローテーションで飽きないというか、しっかりそういった訓練の進展というのですか、これが品川区はすごく見えていて、私は非常に感謝しております。","respondent":"五十嵐災害対策担当課長、平原防災課長","answer":"不参加の避難所の対応というか、どうするのかというところの話なのですが、別日で実施したいというところが複数ございました。まだやはりコロナがあるのでというふうなことをおっしゃるところもございました。地域からは、やはり避難所が分かれることによって、役員を２つに分散するといったところの人的な確保等々の問題をいただいているところでございまして、それ以外の各町会との連携という点でまずは工夫していただいているところですが。","voiceIndex":103,"id":"exchange-043"},{"speaker":"松澤委員","kind":"提案","question":"そうですよね。やらない町会や、やれない町会の中で、別日というのとコロナというのがあって、やりたくないとかやれないということがないということでよろしいのですか。","respondent":"五十嵐災害対策担当課長","answer":"委員のおっしゃるとおりです。","voiceIndex":106,"id":"exchange-044"},{"speaker":"松澤委員","kind":"質問・要望","question":"やれない町会がもし仮にあるとしたら、そういうときこそやはり行政の方の支援というか、そういった部分でお声かけしてあげるといいかなと思ったのでこれは余計な心配でした。以上です。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":108,"id":"exchange-045"},{"speaker":"田中委員","kind":"質問","question":"すみません。ただ、障害者団体の方たちが参加する際に勉強が必要ということがあったのですけれども、勉強と思って、私は訓練に参加するときに勉強していないなと思って、勉強といったのはどういったことを指すのかという、むしろ防災訓練では学ぶ場、知るところなので、勉強は何か必要なのかなというのが私は分からなかったので、そこの部分を教えていただけたらと思います。","respondent":"五十嵐災害対策担当課長","answer":"参加するほうに関しては、今回、ここの訓練ではこういったことをやりますよとあらかじめお知らせしておけば、いろいろなことがイメージできるかなと、次に発展するのではないかなというところの勉強会というか、お知らせというか、そういったものができればと思っていました。","voiceIndex":110,"id":"exchange-046"},{"speaker":"田中委員","kind":"質問","question":"参加する側にはそういった勉強というか、こういう目的があるよというお知らせがきちんとされるということで、それを理解して参加してくださいねということですよね。分かりました。少し気になったので、伺いました。そういう勉強できる材料が区民の方たち皆に届くということで、理解したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":112,"id":"exchange-047"}]},{"id":"topic-03","title":"令和４年度東京都・品川区合同総合防災訓練の実施結果","agenda":"令和４年度東京都・品川区合同総合防災訓練の実施結果","exchanges":[{"speaker":"新妻委員","kind":"提案","question":"ご説明ありがとうございました。２点お伺いしたいのですが、林試の森公園の会場のところにトイレトレーラーの展示がありました。少し私もお話を伺わせていただきました。これまで、トイレトレーラーの導入をということで、どうですかという提案をしていますが、そこにトイレトレーラーが展示をされた経緯と、また品川区のお考えをお聞きします。ドローンの活用についてお聞きしたいと思います。","respondent":"平原防災課長","answer":"一方で区の導入といったところにつきましては、どのような形で導入するか。災害時協力協定であるとか、区が所有するとかいろいろな考え方がありますけれども、それぞれに正直まだ課題があるところでございまして、引き続き検討させていただいているところです。","voiceIndex":117,"id":"exchange-048"},{"speaker":"たけうち委員","kind":"質問・要望","question":"それで少し気になったのは、西大井広場の外のあれは何だろうな。それから、この表の下から３番目の緊急支援物資のところなのですけれども、この地域内輸送拠点の常時稼働が課題だと書いてあるのですけれども、今この地域内輸送拠点というのがどの辺になっていて、何か所ぐらいあるのかとか、それで物流を協定も含めて検討するとなっていて、その辺、もう少し課題を教えていただきたい。","respondent":"五十嵐災害対策担当課長、平原防災課長","answer":"私からは、会場外の民間ビルの降下訓練のお話と、「真災害」についてお答えします。会場外の民間ビルにつきましては、ニコンの本社ビルになります。そういった中で仮に災害が発生した場合には、直ちに地域内輸送拠点としての開設が難しいという課題もございまして、そういったところから、今回の課題として常時開設、そういったところについてはどのような形で進めていけるだろうか。","voiceIndex":120,"id":"exchange-049"},{"speaker":"たけうち委員","kind":"質問","question":"分かりました。真災害というのは初めて言葉として聞いたので、今ちょっと衝撃を受けました。今後何か質問で使おうかなと。では地域内輸送拠点というのは、今、品川区は大井競馬場だけなのですね。それと、目黒川会場というところでやったのでしょうけれども、そうすると、東京都から来る物資の受け入れ先が、今後もしかしたらもう少し別の場所でも増やすみたいなことも検討するということなのでしょうか。","respondent":"平原防災課長","answer":"ただ、そういったような問題点もありますので、現状、例えば２４時間稼働できるようなトラックヤードのようなそもそも物流に向いたような施設、こういったところの活用を前提に、検討を進めさせていただいているところです。","voiceIndex":123,"id":"exchange-050"},{"speaker":"田中委員","kind":"質問・要望","question":"ただ、ほかの障害の方たちの参加状況がもし把握できていれば、それを伺いたいということと、その参加がもしあった場合には、そこから見えた課題等があったらお知らせいただきたいということがまず１点です。小山台小学校にそのバスが止まっているのを見て、これほど大型なのだとちょっとびっくりしたのですけれども、３ルートあった中で、バスの利用状況について伺いたい。","respondent":"五十嵐災害対策担当課長","answer":"各臨時バス停のところで待機寮の寮生が対応させていただきましたので、何かありましたら、その待機寮生から介護タクシーの要請という形で、本庁舎に詰めていただいた介護タクシーが現地に向かうということで考えていたところなのですけれども、結果として。","voiceIndex":126,"id":"exchange-051"},{"speaker":"田中委員","kind":"質問","question":"バスの利用状況と介護タクシーの状況は分かりました。障害団体の方ではなくて、聴覚障害の個人の方でもいいのですけれども、個人として聴覚障害以外の障害がある方が、参加されたものの把握がもしできていれば、そこの状況をお知らせいただきたかったのですけれども、いかがでしょうか。","respondent":"五十嵐災害対策担当課長","answer":"個人としての参加も私の知るところではなかったので、今後、そういったことがあれば、またお知らせしていきたいと思います。","voiceIndex":128,"id":"exchange-052"},{"speaker":"田中委員","kind":"質問・要望","question":"多分参加されている方もいると思うので、ぜひこれから結果をまとめるといったときには、そういった参加された方からどのような声が聞かれたかとか、そういったことも今度お知らせいただければと思います。要望にとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":130,"id":"exchange-053"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"当日は私も朝から医療救護訓練を見させていただきました。この訓練開始に合わせて、被災者役の方々が次々と助けを求める姿を見て、この発災時の混乱状況というのは本当にカオスだなと思って想像することができました。今回、こうしたことで行った教訓というのを洗い出して、生かしていっていただきたいと思うのですけれども、この点、１点お伺いしたいと思います。","respondent":"平原防災課長","answer":"医療救護のところの今回の訓練を受けた今後の教訓といったところですけれども、副委員長ご指摘のとおり、まず超急性期における医療活動というものは、なかなか制約が多い中で大変な状況だということもありますが。","voiceIndex":132,"id":"exchange-054"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"そうすると、その現地連絡調整所の方がすべてを把握してというか、すべてを把握するのはなかなか難しいと思うのですけれども、どういったときにどう対応するのかというのを頭にしっかり入れてやっていかないと、その現場で滞ってしまうなというふうに思いましたので、そこはぜひスムーズにいくようにしていただきたいと思います。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":134,"id":"exchange-055"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6626#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":44468,"voices":138}},{"id":"r04-20221108-4","meetingId":"r04-c-settlement","date":"2022年11月8日","dateIso":"2022-11-08","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時２５分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を160件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"若林副委員長","kind":"質問","question":"第４項、款別審査の質疑等についてです。なお、質問時間は、会派におかれましては、１人当たりの質問時間は、答弁時間も含めて、１０分、１５分、２０分のいずれかとし、無所属の委員は、答弁時間も含めて、１日につき１０分となります。終了時間のお知らせにつきましては、残り時間がなくなった時点で振鈴を２回鳴らしますので、質問の途中でありましても、直ちに取りやめていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":4,"id":"exchange-001"}]},{"id":"topic-02","title":"以上で、決算統計上の数値および財政健全化法に基づく各指標についての説明が終わりました。 それでは、令和３年度品川区一般会計歳入歳出決算","agenda":"以上で、決算統計上の数値および財政健全化法に基づく各指標についての説明が終わりました。 それでは、令和３年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問","question":"おはようあります。今日からの決算特別委員会、７日間しっかりと審議していきたいと思いますので、どうぞよろしくお願いいたします。質問は、６０ページの特別区交付金、特別区財政調整交付金を含め、決算全般についてと、９０ページの国庫支出金、衛生費負担金に関連した内容でお聞きしたいと思います。それから執行率なのですが、今回、約９１.６％と、前年の９４.７％に比べて低下しています。","respondent":"黒田財政課長、坂野保健予防課長","answer":"経常収支比率が２３区の平均より悪いのではないかというご指摘ですが、経常収支比率は、おおむね８割を下回っていれば良好と言われておりまして、これが１００％に近づきますと財政が硬直化して。それでも内容自体はあまり大きく変わっておりませんので、積極的疫学調査、あるいはそれに伴う療養の調整、特に介護関係などがある方はそういった調整が結構複雑になってまいりますので。","voiceIndex":13,"id":"exchange-002"},{"speaker":"鈴木（真）委員","kind":"確認","question":"その点に関しまして、それから、こども家庭庁でいくと妊産婦ということも出てきますので、保健師の数というのはやはり重要な問題だと思うのですが、その辺、何か課題があるのかという点を１点お聞きしたいと思います。それから児童相談所の開設も考えた場合に、やはり財政調整交付金から出る部分が大きいと思うのですが、どのぐらい見込んでいけるのか、歳入という点で確認をさせてください。","respondent":"若生健康課長、黒田財政課長","answer":"今後、介護の部門あるいは子ども家庭支援センター、それから児童相談所といったところへの保健師の配置が求められてくるということで、今現在、庁内に、健康課に統括保健師ということで１名置いておりまして、人材の育成等、統括的に。いわゆる特別交付金の、これからの、特に協議項目としての重要な項目のご指摘だと思いますけれども、高校生等の医療費助成につきましては、令和５年度の４月から、２３区が足並みをそろえて。","voiceIndex":16,"id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"財政調整の問題は大変難しく、私もまだ分からないところがいっぱいある。基準財政需要額の算出のための項目設定も、品川区にとっていい方向にやれば歳入が増えてくるとは聞いているのですけれども、その辺がなかなか調整できないので、議会側として十分には分からないところなので、専門の中で、品川区にとって有効な形を取って、調整も進めていっていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-004"},{"speaker":"新妻委員","kind":"質問・要望","question":"３点お伺いいたします。６５ページ、シルバー人材センター、９３ページ、個人番号カード経費、１２５ページ、感染症対策事業に関連いたしまして、それぞれお伺いしてまいります。私たち公明党として求めていることは、この大きな波が起きたときにどういう対応をしていくのかということ、区民の皆様が困らないためにどういう対応をしていくのかということを求めてまいりました。","respondent":"坂野保健予防課長","answer":"前回、議会でご質問いただきまして、コールセンターの強化ということで、なかなか増員は、かなり難しい部分もあって、やはりＩＴの力を借りて機能強化をしていこうということでございまして、増員と並びまして、コールセンターに、自動応答装置、ＩＶＲと言いますが。","voiceIndex":21,"id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"東京都もかなり抱えてくださっているので、品川区の保健所の負担は少なくなっていることと思いますが、いざ感染爆発が起きた場合に備えて、しっかり体制を整えていただき、区民が不安に思わない体制を求めたいと思いますので、どうぞよろしくお願いいたします。続きまして、シルバー人材センターについてお伺いいたします。３４４万円、計上されております。この内訳をお知らせいただきたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"何の内訳か聞こえませんでした。申し訳ございません。","voiceIndex":23,"id":"exchange-006"},{"speaker":"新妻委員","kind":"質問・要望","question":"ではすみません。内訳は結構です。求めるものと、また、そこまではできないというシルバー人材センターとのマッチングがあるのですけれども、ここに対してのマッチング状況ということを少しお伺いさせていただきたいと思います。ホームページには、令和４年１０月１日現在の新たな金額が出ておりますので、そのことも踏まえて、ぜひパンフレットに反映していただきたいと思いますが、いかがでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"大変失礼いたしました。先ほど６５ページのシルバー人材センターの内訳ですが、品川第一地域センタービルの管理費負担金ということで、こちらはシルバー人材センターが事務所として借り受けておりまして、そこの部分の光熱水費等を払っているという部分の金額です。","voiceIndex":25,"id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"求めることが、やはり、なかなかマッチングが難しいところもあると思うのですけれども、多くの人材をシルバー人材センターに募集していただき、受けていただける方法を、ぜひまた品川区からもお伝えいただきたいと思いますので、よろしくお願いいたします。例えば都営住宅、区営住宅、高齢者の多いところでの出張申請サポートを進めていただきたいと思いますが、いかがでしょうか。","respondent":"吉野戸籍住民課長","answer":"マイナンバーカードの件で、出張申請サポートですけれども、イトーヨーカドー、青色申告会など、方々でやっております。全部で１,０４２件ほど申請があったです。","voiceIndex":27,"id":"exchange-008"},{"speaker":"田中委員","kind":"質問","question":"９８ページ、感染症予防費、１６７ページ、議会費、１１７ページ、区内私立保育園経費、関連して区立園についても伺います。時間があれば１３２ページ、埋蔵文化財調査費、広町御料車庫について伺います。初めに、コロナウイルス感染症対策について伺います。現在、第８波が始まっていると警戒する声が聞こえてきます。","respondent":"坂野保健予防課長","answer":"こういったコロナの後遺症は小児には限らないものではあるのですが、東京都でも、コロナウイルス後遺症の研修をやっておりまして、直近、１１月２０日に予定されているのですが、そういったものにも職員を積極的に参加させて、スキルアップを図ってまいりたいと考えております。","voiceIndex":30,"id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"続いて議会費について、委員会中継について伺います。区議会事務局に調査を依頼し、２３区と市部の議会のインターネット映像配信状況について確認しました。この２つの調査結果を基に質問をします。品川区議会でもぜひ進めていただきたいと考えますが、現在進められない課題がどこにあるのか伺います。品川区でも、デジタルサイネージの活用も含めて進めるべきと考えますが、見解を伺います。","respondent":"坂野保健予防課長、工藤区議会事務局長","answer":"小児の後遺症の件です。教育委員会からご相談等があれば、保健所でも相談に乗らせていただいて、考えていきたいと考えております。実施の可否につきましては、やはりこれまで、議会改革の各会議体において、ご議論され、検討され、決定してきた経緯があります。","voiceIndex":32,"id":"exchange-010"},{"speaker":"田中委員","kind":"質問・要望","question":"後遺症の部分です。品川区情報公開・個人情報保護条例の目的に掲げられている区政の透明性を確保し、区民と区政との信頼関係の強化につながるように、品川区議会として情報公開手数料を無料にすることを求めますが、見解を伺います。しかし、今、過去の議員一人ひとりの活動が注目されているため、現在保管されている資料は一定期間、５年を経過しても保存しておくべきだと考えますが、見解を伺います。","respondent":"工藤区議会事務局長","answer":"これは議会の規定の中でも、区の条例と同一での取扱いというところで運用しています。それから、最後の保存期間の件につきましては、現状は５年というところで位置づけしておりますので、そのように運営をさせていただいているところです。","voiceIndex":35,"id":"exchange-011"},{"speaker":"田中委員","kind":"質問・要望","question":"次の質問に続きます。置き去り事案について伺います。私立園では、１歳児をエレベーター内に置き去りにしてしまって全く気づかず、同じビルにいた職員の方が「この子はそうではないですか」と声をかけてきた事例。区内保育園の保育の質を維持・向上させるために、園の名前などは要らないです、事故報告と再発防止に向けた対策についても、市民に分かるように公表すべきと考えますが、見解を伺います。","respondent":"工藤区議会事務局長、中元保育支援課長","answer":"保存期限の件です。こちらは、やはり議会改革等の各会議体の中でまずはご議論され、結論を出されるべきだと考えています。議会の中で合意形成が図られるということであれば、事務局としましてもその手続を進めてまいるです。置き去りの事故報告の件ですが、こちらは、公立保育園、私立保育園と、それぞれの課に報告をいただいておりまして、また、その中で、今後の対策につきましても、公・私立保育園地域連携協議会で。","voiceIndex":37,"id":"exchange-012"},{"speaker":"田中委員","kind":"質問・要望","question":"事故報告の公開、再発防止策の公開についても伺ったので、再度伺いたいと思います。区として区内保育園の安全を向上するためには、やはり区として独自の保育士配置基準を１歳以外にも設け、保育者の目と手を増やし、子どものための保育、そして命を守る保育が実行されるようにすべきと考えますが、見解を伺います。","respondent":"中元保育支援課長","answer":"事故報告の様式につきましては、今後確認させていただきまして、どのような形が適切なのかというところを引き続き研究してまいりたいと思います。配置基準におきましては、現在のところ、適正に配置されているところと考えておりますが、今後の課題として受け止めします。","voiceIndex":40,"id":"exchange-013"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひそこの部分も公開を求めたいのですが、もう一度伺いたいと思います。次に、財務情報について伺います。２０２０年１０月の決算特別委員会のときに、事業者側の財務情報の記入不備・不足を指摘し、改善を求めました。ほかに、人件費割合の計算が合わない。収支報告の空欄が多い事業者。区としてのチェック体制と、記載不備に対して事業者にどのような改善を呼びかけているのか改めて伺います。","respondent":"中元保育支援課長","answer":"不備なところがございましたら、これは最終的には東京都が責任を持ってチェックするものですので、東京都から不備事項の修正等について指示があり、それについて対応しています。今後につきましても、鋭意、精査して、点検してまいりたいです。","voiceIndex":42,"id":"exchange-014"},{"speaker":"横山委員","kind":"質問・要望","question":"私からは、１４ページ、特別区財政調整交付金、９７ページ、児童相談所移管推進事業、代替職員雇用経費、１１２ページ、人権啓発活動費補助金、１２４ページ、地域自殺対策強化交付金についてお伺いいたします。１点目に、児童相談所移管推進事業についてお伺いいたします。そこでお伺いいたします。そして２点目に、特別区財政調整交付金についてお伺いいたします。そこでお伺いいたします。","respondent":"長谷川児童相談所移管担当課長、黒田財政課長、崎村人事課長、加島人権啓発課長","answer":"区としましては、子ども家庭支援センターと連携し、児童虐待の未然防止に努めるとともに、社会全体へのさらなる意識啓発に努めるべく。区長会で、総務省に清掃移管時の割合の変更などの経緯の法的な見解を求めておりまして、そういったところから、特別区の児童相談所設置は。もし品川区役所で、職場内で自殺者が出たときの対応というご質問ですけれども、これは特にマニュアル等を定めているわけではございませんが、ただ。","voiceIndex":45,"id":"exchange-015"},{"speaker":"横山委員","kind":"質問・要望","question":"時間がなければ衛生費のところでお伺いできればと思います。一言で構いません。こうした映像作品は様々な活用の仕方があると思いますが、映画「ほどけそうな、息」を、安田真奈監督のＮＨＫドラマ「やさしい花」などとあわせて、品川区で、児童相談所準備に関わる部署に異動するタイミングで、ぜひ活用していただきたいということを要望いたします。","respondent":"坂野保健予防課長、長谷川児童相談所移管担当課長","answer":"先ほど人事課長からもお話があったのですが、保健センターでどういう相談をしているかということは、一般的なお悩みの相談以外に、品川区のユニークな取組といたしましては自死遺族の会をやっておりまして。ニュース等で負の側面が取り上げられることが多い児童相談所……。","voiceIndex":50,"id":"exchange-016"},{"speaker":"鈴木（博）委員","kind":"質問","question":"本日は、９２ページ、衛生費負担金、新型コロナウイルスワクチン接種負担金から、乳幼児の新型コロナワクチンについてお尋ねいたします。１１月からいよいよ、６か月から４歳の乳幼児コロナワクチンの接種が始まります。最後に、現在接種の続いている５歳から１１歳の小児用コロナワクチンの接種率、接種数およびその評価について、参考にするために一緒にご説明をお願いします。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"年齢によって、もしくはお子様の体形によって接種の部位が異なること、また接種後の副反応が出た場合、的確な対応をしなければならないことなどを考慮したことによるものです。","voiceIndex":54,"id":"exchange-017"},{"speaker":"鈴木（博）委員","kind":"確認","question":"４歳以下の１４人のうち６人は、基礎疾患がない、もともと健康な子どもでした。乳幼児コロナワクチンは、ファイザー社が生後６か月から４歳の子どもを対象に臨床試験を行った結果、３回接種後には、年長児や大人の臨床検査の結果と同じレベルまで抗体が上昇することが確認されました。心配な乳幼児のコロナワクチンの副反応を、現在、区はどのように理解しているでしょうか。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"倦怠感、下痢、それから３８度以上の発熱が主に見られるということが書かれておりまして、また生後６か月から１歳につきましても、不機嫌になったり、食欲不振になったり、やはり３８度以上の発熱の症状が見られたようですが、重い副反応は認められなかったという報告がされて。","voiceIndex":56,"id":"exchange-018"},{"speaker":"鈴木（博）委員","kind":"確認","question":"本ワクチンの３回目接種から１か月後、免疫原性が事前に規定された基準を達成したこと、オミクロン株等に対する中和抗体価の上昇が確認されたこと等から、一定の有効性が期待されるとされています。区としても、小さな子どもをコロナから守るために、もう少し積極的なコロナウイルスワクチンの啓発に取り組むべきだと思われますが、区の考えと現在の取組についてご説明をお願いいたします。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"関係所管とも連携しながら、こうしたものが保護者の方の目につくよう、行き渡るよう、そういった方法を今後検討していきたいと考えています。","voiceIndex":58,"id":"exchange-019"},{"speaker":"鈴木（博）委員","kind":"提案","question":"中立的な立場の講演会の開催などもいかがでしょうか。これは要望といたします。もう今現在でも保育園とか小学校とか増えてきているので、先週も小学校で学級閉鎖がありましたけど、小さなお子さんをコロナ感染症と、あるいは起こるかもしれないインフルエンザの感染症から守るために、ぜひこの冬は、区の関係者の方もより一層のご努力をお願いしたいと思いまして、私の質問を終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":60,"id":"exchange-020"},{"speaker":"たけうち委員","kind":"質問・要望","question":"９８ページの新型コロナウイルスワクチン接種体制確保事業費補助金、５２ページの特別区民税をお伺いします。目黒区とか大田区とか世田谷区とか、城南５区と言われているところはほとんど減少しているのですけれども、品川区は増えているのですけれども、この辺の何か情報、ほかの区ではこんなことが原因で減ったのだとか、品川区はこういうことで大丈夫だったのだとか、その辺がありましたら教えてください。","respondent":"坂野保健予防課長、提坂税務課長","answer":"９月２６日以降の発生届のシステム変更ですが、９月２６日以降は、先ほどもお話があったところなのですが、４要件を満たす方だけ発生届が上がってきて、そこには、発生届ということで患者の住所が書いているということがあります。品川区においては幸い、増収になったのですけれども、まずは我々税務課の職員一人ひとりのモチベーションを上げて一生懸命取り組んでいるということで、具体的には、従来から行っているところですけれども。","voiceIndex":62,"id":"exchange-021"},{"speaker":"たけうち委員","kind":"質問・要望","question":"コロナのほうは、保健師は本当に引き続きいろいろな形で決して業務が楽になるということはないとは思うのですけれども、保健所全体でいろいろな業務が少し削減されてきて、これから第８波に向けての対策、対応、いろいろあると思いますけれども、しっかりそこに充てていただきたいと思うのですけれども、そうすると、品川区の数は。","respondent":"提坂税務課長、渡部委員長","answer":"それに伴って納税義務者数も３,９００人増加しているのですが、その中で年齢別で分析しますと、５０歳から６５歳の所得が高い方が増えたのではないかということで。第二委員会室の品川区保健所および健康課の関係理事者の方々もご退席ください。ありがとうございました。進めします。次は石田ちひろ委員ですが、本日欠席のため、次に進みます。質疑を続けます。次に、松永委員。","voiceIndex":65,"id":"exchange-022"},{"speaker":"松永委員","kind":"確認","question":"私からは、５４ページの特別区たばこ税、１１２ページの喫煙環境整備事業補助金、１４４ページのふるさと納税寄附金について伺いたいと思います。そこで質問ですが、区のホームページを確認させていただいたところ、「ふるさと納税により品川区の財源が失われています」と、切実な思いが掲載されており、返礼品の種類も１６種類と増えていると思います。","respondent":"提坂税務課長","answer":"昨年度の品目としてベスト３ですけれども、１番目が、フライトシミュレーターの操縦体験３０分コース、２番目が、しながわ観光大使シナモロール３体セットぬいぐるみ、３番目が、先ほど申し上げた『シナモロールのわくわくしながわさんぽ』の絵本です。","voiceIndex":68,"id":"exchange-023"},{"speaker":"松永委員","kind":"確認","question":"そういった形で頑張っていただければと思うのですが、確認です。品川区では返礼品以外にも、応援したい事業へふるさと納税を希望する方へとあり、子ども食堂への寄附と、ブラインドサッカー応援プロジェクトの２つのみでしたが、ほかにはありますでしょうか。","respondent":"提坂税務課長","answer":"現在はその２品目だけかと把握しています。","voiceIndex":70,"id":"exchange-024"},{"speaker":"松永委員","kind":"意見","question":"他の自治体では、福祉施設の建設費に充ててほしいとか、各種団体の応援に充ててほしいという取組をされているところもあります。そして、受け取った側から写真やメッセージを添付するなどを行えば、また一層深まるのではないか、品川区に寄附したいというような思いをされる方が増えるのではないかと思うのですが、区の考えをお聞かせください。","respondent":"提坂税務課長","answer":"これに対して、区内在住の方、それから区外在住の方から、どの程度の賛同を得ることができるか、寄附をいただけるか、それから費用対効果など個別の事例についても、各担当する主管課で調査・分析する必要があると考えてございまして、今後の研究課題と捉えておりますけれども。","voiceIndex":72,"id":"exchange-025"},{"speaker":"松永委員","kind":"質問","question":"次に移ります。５４ページの特別区たばこ税の収入が、予算当初に比べて約２億５,０００万円ほど差が出てきております。そうした中、品川区では喫煙所の整備や廃止を進めておりますが、この状況を考えますと、廃止や撤去ではなく、整備を進めたほうがいいと考えますが、税収入も含めて、今後の喫煙所のあり方について区の見解をお願いします。","respondent":"森田生活安全担当課長","answer":"現在、９か所のうち１か所を一時閉鎖という形にはしておりますが、廃止という形では進めてはおりません。現状のところでは、大崎駅東口のコンテナ喫煙所設置であるとか、そういったものは、現在の状況の中で進めさせていただいているところです。","voiceIndex":74,"id":"exchange-026"},{"speaker":"松永委員","kind":"質問・要望","question":"こうした中で、先ほどもありましたが、大崎駅はコンテナ式のスペースをつくっているということですが、ほかのエリア、例えば大井町でも２か所あるのですが、そちらについてもコンテナ式にしてはどうかと思います。それはなぜかというと、すぐ横が歩道になっておりまして、特に陸橋の下ですけれども、ベビーカーを押している方やお子さんなどがすごく通られるのです。例えば武蔵小山もそうです。お願いします。","respondent":"森田生活安全担当課長","answer":"空き店舗についての、喫煙所等の活用についてです。現状、空き店舗を利用して品川区で喫煙所にしようという取組については、現在は検討しておりません。ですが、現在、民間喫煙所の補助要綱を策定しています。","voiceIndex":76,"id":"exchange-027"},{"speaker":"藤原委員","kind":"質問","question":"５２ページ、特別区民税、１３７ページ、衆議院議員選挙執行費をお伺いします。税金のほうから伺いますけれども、国民の三大義務とは何でしょうか。お答えください。","respondent":"提坂税務課長","answer":"国民の三大義務は、納税の義務、教育を受けさせる義務、あと勤労の義務です。","voiceIndex":80,"id":"exchange-028"},{"speaker":"藤原委員","kind":"質問","question":"大切なことだと思って質問しますが、区民税の徴収率、それとも収納率、これは、まずどちらが正しいのでしょうか。答弁も含めて、徴収率か収納率かも含めて、どのぐらいなのか教えていただけますか。","respondent":"提坂税務課長","answer":"直接税金を集める、徴収する部門からは、徴収率という言い方をしていることが多いようです。それで、徴収率につきまして、令和３年度におきましては、特別区民税については過去最高の９９.１２％を記録いたしました。","voiceIndex":82,"id":"exchange-029"},{"speaker":"藤原委員","kind":"質問・要望","question":"たしか、順位的に言うと２３区でずっと２位だったのですけれども、そういう意味では、順位で競うわけではないですけれども、もっと限りなく１００％に近くしていただきたいと思うのです。だって納税の義務ですから、税金は払っていただくことが義務ですから、そういう思いも含めて、課長、いかがでしょうか。","respondent":"提坂税務課長","answer":"９９.１２％という数字は限りなく１００％に近い数字ではありますけれども、残念ながら２３区の中ではまだ２位ということで、１位が江戸川区です。","voiceIndex":84,"id":"exchange-030"},{"speaker":"藤原委員","kind":"質問・要望","question":"そういう意味を持って、課長、ぜひまた１位に復活していただきたいと思うのが１点と、もう一点は今言った照会システム。これはすごいですよね。だって、区民税は、前年の所得があって、それにかかるわけですから、前年の所得をキープしていてくれれば払えるわけですよね。それを使ってしまったりして払えませんというのはルール違反だと思うので、その辺についてはいかがでしょうか。","respondent":"提坂税務課長","answer":"その１位を目指すために、預貯金照会システムというものを導入しまして、従来は回答まで一、二か月を要していたものが、一日、二日で回答が返ってくるということを踏まえて、差押え件数についても、昨年度、約２,６００件実施しているのですけれども。","voiceIndex":86,"id":"exchange-031"},{"speaker":"藤原委員","kind":"質問","question":"選挙についてお伺いします。でも、区議会議員および区長は、その印刷代は出ませんよね。国は国、都は都、区は区という意味において議会があるわけですけれども、私はそういう区別というのはなしにしていただいて、区議会議員の選挙、区長の選挙も、法定はがきの印刷代は公費で出るべきものだと思うのですけれども、その辺についてはいかがでしょうか。","respondent":"鈴木選挙管理委員会事務局長","answer":"ところが、ご質問いただいた、はがきの印刷代につきましては、その根拠規定がないというところで、根拠がないということで、区の条例での公費負担の定めの中に入っていないです。","voiceIndex":88,"id":"exchange-032"},{"speaker":"藤原委員","kind":"質問・要望","question":"つくればいいじゃないですか。民主主義の根幹なのですから。これはおかしいんじゃないですかと。そうしたら、今回の区議会議員補欠選挙・区長選挙においては１.１倍になったじゃないですか。それで二十何万円、お給料をお支払いしているわけですから、こういうふうに議会で話が出ましたというのを、回数を増やしてでも議論していただきたいと思うのですけれども、その辺についてはいかがでしょうか。","respondent":"鈴木選挙管理委員会事務局長","answer":"ご指摘のとおり、もしその必要性もしくは実施の可否について検討することになれば、選挙管理委員会にかけて、議題として正式に検討したいと考えております。","voiceIndex":90,"id":"exchange-033"},{"speaker":"藤原委員","kind":"質問・要望","question":"我が会派の須貝委員が、時給１０万円とよく言うじゃないですか。渋谷区、日額２万５,０００円です。だから、そういう意味において、せっかく今、選挙管理委員会があるわけですから、選挙管理委員会はきちんと選ばれているわけですから、こういうことも含めて、やはり通常のときでも回数を増やして、どんどん議論をしていっていただきたいと思うのですけれども、その辺についてはいかがでしょうか。","respondent":"鈴木選挙管理委員会事務局長","answer":"先ほど申し上げましたように、法的に可能であれば検討はいたします。委員会の回数につきましては、委員長の判断、それから選挙時の必要がある場合においては回数を増やすことが可能ですので、その辺もあわせて委員会で話し合いたいと思います。","voiceIndex":92,"id":"exchange-034"},{"speaker":"せらく委員","kind":"質問","question":"私からは歳入において、５４ページ、特別区たばこ税、６８ページの公園運動施設使用料について質問します。子どもたちの安全と健康を願って、受動喫煙のない品川区を目指していきたいので、たばこ税を使って喫煙所をしっかり確保してほしいと考えています。現在、区で管理している喫煙所は９か所、うち１か所が閉鎖ということですが、今後の増設の予定、喫煙所の設置の計画を伺います。","respondent":"森田生活安全担当課長","answer":"品川区におきましては、現在９つの喫煙所があります。今後の計画にございましては、現在、大崎駅西口に喫煙所はありますが、そちらにつきましてはコンテナ化のリニューアルを検討しています。","voiceIndex":95,"id":"exchange-035"},{"speaker":"せらく委員","kind":"質問","question":"その後、露天型の喫煙所は閉鎖されて、コンテナ型の喫煙所が設置されたということですが、開設して半年と少したちまして、周辺の吸い殻のポイ捨てや路上喫煙などの環境は改善されていますでしょうか。その状況と、また、ほかにご意見が寄せられているものがございましたら伺わせてください。","respondent":"森田生活安全担当課長","answer":"大崎駅東口コンテナ型指定喫煙所につきましては、本年の４月２０日に開所しております。","voiceIndex":97,"id":"exchange-036"},{"speaker":"せらく委員","kind":"質問・要望","question":"公園運動施設使用料について質問します。息子がサッカー少年で、小学校のサッカーチームに入っておりまして、イベントや試合などで度々、公園運動施設を利用しています。このしながわ中央公園の多目的広場は、学校をはじめ、様々な団体が利用していると思いますが、年間でいうと何日ぐらいの利用があるか教えていただきたいと思います。あわせて、この施設の利用方法を伺います。","respondent":"辻スポーツ推進課長","answer":"公園運動施設についてのお尋ねかと思います。しながわ中央公園の多目的広場ですが、土日についてはほぼ満杯、数字については今ちょっと持ち合わせはないのですが、平日も、昼間は学校がお使いになられているときもありまして、ほぼ８割から９割は埋まっているという状況です。","voiceIndex":99,"id":"exchange-037"},{"speaker":"せらく委員","kind":"質問","question":"ほかの運動施設では、インターネットや電話での利用申込みができるということなので、郵送ですと時間もかかってしまいますし、利便性を考えたシステムを導入して、デジタルで完結できるように、時代に合わせて改善したほうがいいと考えますが、往復はがきとオンラインの申込み、併用でできるように選択肢を増やしていくのはいかがでしょうか。","respondent":"辻スポーツ推進課長","answer":"例えば教室等では、往復はがきを使ってのお申込みというのはさせていただいているのですけれども、グラウンドを取るだけの場合には今のところはやっていないところです。","voiceIndex":101,"id":"exchange-038"},{"speaker":"せらく委員","kind":"質問","question":"登録していれば、オンライン上で申込みができるということで、かしこまりました。ありがとうございました。いつもたくさんの少年少女、大人まで汗を流して楽しんでおられますが、ほかの公園運動施設では一般開放を行っているか、状況を伺います。","respondent":"辻スポーツ推進課長","answer":"例えば鮫洲運動公園というところがございまして、子ども向けのところなのですが、そちらやはり朝、自由に使っていいというふうに開放しております。","voiceIndex":103,"id":"exchange-039"},{"speaker":"せらく委員","kind":"意見","question":"品川区は小さい公園が多くて、ボール遊びもできない公園もありますので、子どもたちの体力向上のためにも、利用がない場合の公園運動施設は積極的に開放してくだされば、子育て世代の皆様の満足度がさらに上がるのではないかと思いますので、ぜひご検討いただけることを願います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":105,"id":"exchange-040"},{"speaker":"芹澤委員","kind":"質問・要望","question":"私からは、１１３ページの生活安全活動費から、まもるっちのことを伺います。１４４ページのふるさと納税寄附金、時間があれば１１３ページのオリンピック・パラリンピック開催周知事業についてお伺いします。最初にふるさと納税からお伺いします。決算・予算のところで何度も、ふるさと納税についてお話をさせていただきました。","respondent":"提坂税務課長","answer":"流出額の対応はなかなか難しいところがあって、これから研究してまいります。","voiceIndex":107,"id":"exchange-041"},{"speaker":"芹澤委員","kind":"質問・要望","question":"流出のところに関連して、今日、冒頭、和氣副区長からもお話がありましたが、物価高騰のところが今、品川区の多くの方のお悩みになっているかと思います。例えば、令和２年度に、特別区全国連携プロジェクトのときですか、福井県坂井市と連携して、ふるさと納税をしていただいて、ひとり親家庭への米の宅配というものをやったかと思います。ご見解をお聞かせください。","respondent":"提坂税務課長","answer":"友好都市や災害拠点都市など、様々お付き合いのある自治体もありますけれども、そちらで品川区に関連する取組の企画があれば、最終的にはそれぞれの自治体が主体的に企画・実施していただくものですけれども、積極的に情報提供をしていって。","voiceIndex":109,"id":"exchange-042"},{"speaker":"芹澤委員","kind":"提案","question":"以前もふるさと納税について１つ、疑問というか提案を投げさせていただいたのは、やはり今、税務課長もお話しいただいたとおり、ふるさと納税はシティプロモーションの観点でというようなお話があり、流出に対してもこれから他の自治体との連携というところで、ふるさと納税は税だからといって税務課が主として対応するのは、なかなか難しいのではないかというのはいまだに思っていまして、２３区の中でも。","respondent":"森田生活安全担当課長","answer":"現在、委員がおっしゃられました協力者につきましては、令和３年度で１,９１４人となっております。この方々に対する通報につきましては、現在のところ、実績はございません。","voiceIndex":111,"id":"exchange-043"},{"speaker":"芹澤委員","kind":"質問・要望","question":"まもるっちですから、何か児童が身の危険を感じた際に防犯ブザーを鳴らして、その情報が地域の方々に連絡・連携されると。それは本当にいいことなのだと思いますが、今の時代を考えると、やはりメールで連絡というのがどうなのかと思う次第で、なかなかメールをリアルタイムで見る方がいらっしゃらないのではないかと思っています。そういったところに関して、まずご見解をお聞かせください。","respondent":"森田生活安全担当課長","answer":"１年に１回は訓練を行いまして、メールアドレスに、訓練ですということで発報しまして、それで現場に集まっていただく訓練も実施しています。","voiceIndex":113,"id":"exchange-044"},{"speaker":"芹澤委員","kind":"意見","question":"地図を添付してということでありますが、今、私はスマートフォンを使っていますけれども、基本的に画像も送れる機種がほとんどなのではないかと思います。まもるっちについてなのですが、一部の公営住宅、区民住宅や区営住宅で、電波が届かないというようなご連絡もいただいていまして、家の中も含めてですが、児童の安全確保というのを、まず区はどこまで保障していくべきだとお考えか、お聞かせください。","respondent":"森田生活安全担当課長","answer":"そういった意味では、そういった時間帯における児童の安全につきましては、万全を期していくように実施していきたいと考えています。","voiceIndex":115,"id":"exchange-045"},{"speaker":"芹澤委員","kind":"提案","question":"区営住宅等に関しては、いろいろ交渉は必要なのだと思いますが、まもるっちは当然、全てＫＤＤＩの電波だと思いますので、アンテナの基地局を設置するというのも１つの解決策になろうかと思っています。最後、１１３ページ、オリンピック・パラリンピックに関して、レガシーとしてボッチャの大会をというのを以前からご提案させていただいていました。","respondent":"辻スポーツ推進課長","answer":"先日の土曜日も、地域スポーツクラブのボッチャの大会がございまして、２０チームが集まって熱戦を繰り広げました。１０歳ぐらいの小学生から８０歳を超える方までが混ざり合ってやる、非常にすばらしいスポーツだと考えています。","voiceIndex":117,"id":"exchange-046"},{"speaker":"芹澤委員","kind":"提案","question":"私はボッチャを区の公式スポーツにもしたほうがいいのではないかというご提案も以前したことがありますが、やはりボッチャというのは、体力もそこまで求められずに、子どもたちや高齢者や障害者が混ざり合ってできるスポーツだということでお願いしているところでありますが、なかなか大会でも、障害者の当事者の方が実際にボッチャをやっていなかったりというのは、残念ながら見られていて。","respondent":"辻スポーツ推進課長","answer":"ボッチャ大会、障害者の当事者の方にも出ていただくというのは、こちらからの投げかけや問いかけの形が必要かなと考えています。広報の仕方も、いろいろな形で工夫しながら、地域のいろいろな方が参加して混ざり合えるような大会を、これから研究していきたいと考えています。","voiceIndex":119,"id":"exchange-047"},{"speaker":"おくの委員","kind":"質問","question":"昨年、荏原第一地域センターと荏原第一区民集会所が武蔵小山駅前に移転しましたけれども、移転前には集会所の使用料を払いさえすれば、それ以上の負担がなく、放送装置やマイクなどの設備を使えていたのに、移転してからは、それらの設備の使用料を別に取られるようになったと、利用者の方から伺いました。なぜ設備の使用料を有料にしたのでしょうか。伺います。","respondent":"川島地域活動課長","answer":"新しくきれいな施設で使っていただくですので、有料化についてもご理解をいただきたいと考えています。","voiceIndex":122,"id":"exchange-048"},{"speaker":"おくの委員","kind":"質問","question":"そうしますと、建物の改築でなくても、古くなれば、新しい設備が導入されることはもちろんあるのですけれども、そのような設備だけの更新によっても有料化していくというのが区の方針なのでしょうか。その点、伺います。","respondent":"川島地域活動課長","answer":"区民集会所の設備の使用料につきましては、区民集会所を改築したり新しくなったときには、料金をいただくような形で順次行ってきたところですので、区の方針というふうな考え方で言っても差し支えないと思います。","voiceIndex":124,"id":"exchange-049"},{"speaker":"おくの委員","kind":"質問","question":"今の説明ですと、設備が新しくなったからというよりは、区民集会所自体を改築したり、区民集会所自体を新しくしたときに、それをきっかけに、区民集会所自体の使用料ではなくて、設備の使用料を有料化するという理解でいいのでしょうか。もう一度、念のため伺っておきます。","respondent":"川島地域活動課長","answer":"当然、建物等が新しく更新された際は設備も新しくなるということで、今ご質問のとおりのご理解でよろしいかと思います。","voiceIndex":126,"id":"exchange-050"},{"speaker":"おくの委員","kind":"質問","question":"念押しなのですけれども、設備が新しくなるということなのですけれども、建物は古いままで設備だけを新しくする場合もありますよね。そういう場合はどうなるのですか。念のため、もう一度お伺いしますけれども、そういう場合も値上げする、有料化するということなのでしょうか。","respondent":"川島地域活動課長","answer":"現状では、建物が新しく建て替わった際、そのタイミングで設備使用料について有料にしていくというような形でやってきております。","voiceIndex":128,"id":"exchange-051"},{"speaker":"おくの委員","kind":"質問","question":"それからもう一点、お伺いしておきたいのですけれども、今は設備のことをお伺いしましたが、集会所の使用料の決め方のことも同時に伺っておきたいと思います。施設によって上限等はあるのですけれども、最小限ということで、３割というようなところを目安にして考えていると、当時の行財政改革担当課長が答弁されているのですが、こういう考え方は今も同様だと考えてよろしいのでしょうか。伺います。","respondent":"川島地域活動課長","answer":"その当時のお話のとおりの形で料金の設定がされていると認識しております。","voiceIndex":130,"id":"exchange-052"},{"speaker":"おくの委員","kind":"質問","question":"第一区民集会所の使用料は、午前中は２,６００円ですし、夜は５,２００円です。ですから、午前中はそれまでは２,６００円で借りられていたものが、現在は新しくなって、８２０円をそれにプラスして払わないといけないので、３,４２０円払わないといけない。その点、伺っておきます。","respondent":"川島地域活動課長","answer":"部屋の使用料につきましては、ほぼ増減がなく、新しい建物になっても同じような体系の料金をいただくというように設定しているところですけれども、繰り返しお話ししておりますが、改築したということで、設備使用料につきましては新たに徴収するような形に変更させていただいて。","voiceIndex":132,"id":"exchange-053"},{"speaker":"おくの委員","kind":"質問","question":"値上げしたということなのですが、そうしますと、最初に戻りますけれども、なぜ改築したことをきっかけに使用料を値上げされたのでしょうか。それは結局、新しくなったからとおっしゃるのですけれども、新しくなったらなぜ値上げするのでしょうか。この点、伺っておきます。","respondent":"川島地域活動課長","answer":"こちらは今、免除や減額で使っていただいている方について、設備使用料についても半額になったり免除になるというときに適用されますので、そういった部分を含めて有料の設定をさせていただいているということになります。","voiceIndex":134,"id":"exchange-054"},{"speaker":"おくの委員","kind":"質問","question":"結局、値上げされたということに対して、なぜかということに対して、お答えがないと思います。区民集会所は、区民の皆さんが、学習活動や文化活動、それからボランティアなどの拠点として、非常に便利に使っていらっしゃいます。このような値上げは撤回していただいて、元のとおりに戻していただくことを要求して、質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":136,"id":"exchange-055"},{"speaker":"くにば委員","kind":"質問","question":"本日は、８２ページ、廃棄物処理手数料、粗大系、また５４ページ、特別区たばこ税、および１２５ページ、受動喫煙防止対策費です。粗大ごみのリユース事業を、株式会社ジモティーと提携し、９月末からスタートしたばかりです。それで、まずはお伺いします。まだスタートしたばかりですけれども、ジモティーとスタートしたリユース事業、これまでの利用実績や例えば来場者数、その辺りをお聞かせください。","respondent":"品川品川区清掃事務所長","answer":"引き取った件数が１５９人です。それから、チョイスした品目が３１９点となっています。一部有料で販売もしておりまして、１か月の売上げが４万７,０００円という形になってあります。","voiceIndex":138,"id":"exchange-056"},{"speaker":"くにば委員","kind":"意見","question":"こちらは週１回、日曜日だけ、八潮にある品川区の資源化センターに、わざわざ直接取りに行かなければいけないということで、若干不便かなと思っていたのですけれども、ある程度の利用実績がある。例えば、１回当たり何品までという制限をしたり、あとは月間で何品目という設定をしたり、そういった転売防止策、どのような転売防止策を取っておられるのでしょう。お聞かせください。","respondent":"品川品川区清掃事務所長","answer":"ですので、一応、引取りをするときに本人確認というような形を取らせていただいて、それでまた今後、状況を見て、複数回、それから数量も多く引き取る方、そういう方につきましては少し注意を促すとか、そのような対応は想定しているところなのですが、まだ現在。","voiceIndex":140,"id":"exchange-057"},{"speaker":"くにば委員","kind":"質問・要望","question":"もう一点伺います。現在、取扱いの品目が、テーブル、棚、カラーボックスなどの家具、あとは電子レンジ、扇風機、空気清浄機などの家電、ゴルフ用品などのスポーツ用品、あとはベビーカーやチャイルドシートなどの子ども用品の４種目に限られているのですけれども、なぜ、この４種目に限られているのか、また、今後どういった品目に広げていく予定とか可能性があるかというのをお聞かせください。","respondent":"品川品川区清掃事務所長","answer":"品目につきましては、基本的にはまず粗大ごみで出されているものというところが対象になりますので、区が扱う粗大ごみの範疇の部分について、これからもやっていきたいと考えています。","voiceIndex":142,"id":"exchange-058"},{"speaker":"くにば委員","kind":"質問","question":"「多分それは持っていかれたのだと思います」という形で、私が住んでいるマンションは団地なのですが、そこでも使えるものがまだまだ捨ててあったりして、本来であれば区が入手できた資源を、その方が、何ですか、盗品というのですか、本来は区が収集するものであったものを、資源抜き取りといった形で、明らかに違法な行為をされていると思いますので、きちんとそこに関して。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":144,"id":"exchange-059"},{"speaker":"つる委員","kind":"確認","question":"午前中の質疑なども含めて、区民税についての状況などは確認できたところがありまして、先ほど、たけうち委員の質疑のときに、区民税に関して、人口の１０％に当たる方が、これは所得だと思うのですが、７００万円以上ということ、ただ区民税の４割を占めているということで、約２００億円ぐらいの区民税がその方たち、人口の１０％で４万人ぐらいでしょうか。","respondent":"黒田財政課長","answer":"財政調整交付金も一般財源では大きなところですが、税収の中では、固定資産税でありますとか、特に法人住民税の影響が大きいというところがありますので、いわゆる２３区の域内で、企業活動が活発に行われるというところも税収増につながるのではないかと考えています。","voiceIndex":146,"id":"exchange-060"},{"speaker":"つる委員","kind":"確認","question":"人口が増える要因というのは行政のサービスだけではないというのは、当然、質疑の中でも確認しているところなのですが、品川区の人口は１０年間で約５万人、出入りも当然、変遷はあるのですけれども、５万人が増えているというところ。それは要因ですね。ファミリー世帯はそんなに多くなくて、転入が、これは少し前の数字ですけれども、３.何％とか、そういうのがあったりする。それを教えてください。","respondent":"佐藤計画担当課長","answer":"年齢層的には、２０代の若い単身の方の転入がもともと多かったので、その部分で増えてきたというところが現状です。","voiceIndex":148,"id":"exchange-061"},{"speaker":"つる委員","kind":"提案","question":"ただ、それを世帯でクロスで見られるのかどうかというのは、私も事前には確認できなかったのですが、表現はなかなか難しいのですけれど、自治体が歳入を増やす、そのメインが住民税などとなってきたときに、当然、人口が増える。もしくはこれまでの、この約１０年間でもいいですが、どういう部分を特に評価しているのか教えてください。","respondent":"佐藤企画調整課長","answer":"最近ですが、中間所得層も含めた支援につきましては、区では所得制限を設けずに実施している事業も様々あります。","voiceIndex":150,"id":"exchange-062"},{"speaker":"つる委員","kind":"質問・要望","question":"区民住宅のところについて、この歳入の時間の中で確認しようと思ったのですが、残り時間も僅かなので、改めて歳出のところでやりたいと思いますが、この間確認させていただいて、今、一応全体で４３戸ということで、これは、完全な空き室だけの維持管理で１戸１か月当たり４万円というのが１つ数字であるのですが、平均すると今８種類の使用料があって。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":152,"id":"exchange-063"},{"speaker":"西村委員","kind":"質問","question":"順不同ですみません。１０８ページ、民生費負担金から在宅子育て支援、家事用品の購入支援について伺ってまいります。は児童手当について伺います。しかし、２０２２年１０月の児童手当支給分から、制度改正により支給されない世帯が出てきます。所得制限については様々議論がありますが、まずは児童手当の所得制限で受給対象外となった人数、また、分かりましたら全体の何％に値するのか伺います。","respondent":"飛田子育て応援課長","answer":"子育て施策等は、様々な方向からの充実が必要だということは十分理解しております。今後も国や都の動向を注視してまいりたいと考えております。","voiceIndex":154,"id":"exchange-064"},{"speaker":"西村委員","kind":"提案","question":"１つご提案をさせていただきたいと思うのですが、所得制限で児童手当の特例給付の対象外となったご家庭への支援について、例えばですが、次世代の社会を担う児童の健全な育成を支援する一環として、独自に手当を支給している区もあります。財源や将来への負担に配慮するなど様々課題があるかとは思いますが、このような独自の施策を品川区でも新設できないでしょうか。伺います。","respondent":"飛田子育て応援課長","answer":"今、他区でも例えば千代田区で行っている事業となりますが、とても先駆的なことかと思います。区にとっては財源確保などの課題もありますので、現段階での導入は非常に困難であり、今後も研究したいと考えております。","voiceIndex":156,"id":"exchange-065"},{"speaker":"西村委員","kind":"質問・要望","question":"財源の問題は分かっておりますが、ぜひともご検討いただきたいと思います。区としては各担当課ごとにご判断をしていただいていると思うのですけれども、産み育てやすい品川区をつくるという観点からもご検討をお願いしたいと考えています。本制度導入に当たりまして、これまで所得制限に対して東京都とどのように協議して、区としてどのようなご所見をお持ちか伺います。","respondent":"飛田子育て応援課長","answer":"品川区では今までも入院費の助成を、高校生等に対してもしておりました。そういう意味でも、これからも高校生等の医療費に対しては無償で準備を進めていきたいと考えております。","voiceIndex":158,"id":"exchange-066"},{"speaker":"西村委員","kind":"提案","question":"超過する部分の財源については、都との４年目以降の財源等の協議が整うまでの間、各区が自主財源で負担し実施すると整理されたと伺いました。本制度改正は、令和５年からの導入を予定しておりますが、将来的には所得制限超過に対する財政措置を東京都に求めていくのか、その辺りはいかがでしょうか。ご所見を伺います。","respondent":"飛田子育て応援課長","answer":"こちらに関しても、特別区長会では継続的にまた審議を重ねていくということで言われております。そこのところも動向を見ながら、区としては見届けていきたいと考えております。","voiceIndex":160,"id":"exchange-067"},{"speaker":"西村委員","kind":"質問","question":"少し先の話になりますので、質問しまして申し訳ございませんでしたが、今後、２０２６年度以降の制度設計については都と自治体がどのように負担するか、新区長の下、他区の動向も踏まえて、引き続きお願いしたいと考えています。１歳・２歳というところで、お子さん１人につき２万円が支給されておりますけれども、この経緯と意義についてお伺いいたします。","respondent":"染谷子ども家庭支援センター長","answer":"子育てサポート商品券の事業の実施におきましては、コロナ禍におきまして物価高騰等の影響を受けている子育て世帯のご家庭に対しまして、実際にお子さんの衣類や食料品など、比較的に若い世代の方たちにかかってくる、生計費にかける割合が高いというところがございましたので。","voiceIndex":162,"id":"exchange-068"},{"speaker":"西村委員","kind":"質問","question":"委員会でも様々議論がされてきた議事録を拝見しておりますけれども、対象年齢に関しましてどのようなお考えがあったのかお伺いいたします。","respondent":"染谷子ども家庭支援センター長","answer":"実際に、物価高騰の影響という部分につきましては、１歳・２歳という年齢層のご家庭に限らず、全てのご家庭に関して該当する部分であるかと思いますけれども、まず１点は、家事用品購入支援の１歳・２歳、都の事業について、そこの年齢層を横引きさせていただいたというのが１つ。","voiceIndex":164,"id":"exchange-069"},{"speaker":"西村委員","kind":"質問","question":"実際に利用されている方たちの声が届いていたらお聞かせいただけますか。どれぐらいの方が利用されているか、実数まで分からなくてもいいですが、教えてください。","respondent":"染谷子ども家庭支援センター長","answer":"こちらの事業ですが、８月から実施いたしまして、対象の児童につきましては１万３００名程度なのですけれども、現時点において、およそ８,０００名の児童の家庭から申請をいただいているところです。","voiceIndex":166,"id":"exchange-070"},{"speaker":"西村委員","kind":"質問・要望","question":"１点、身体障害者手帳を所持している方の、失われた身体機能や損傷のある機能を補うための用具、補装具の購入や修理にかかる費用が支給されておりますけれども、これが特別児童扶養手当と同じように、同様の所得制限がかかっているという、区民の方からのお声もありまして、繰り返しになりますが、この所得制限の考え方というのが大変難しいなと、私自身もいろいろ勉強して思うのですけれども、やはり今。","respondent":"松山障害者支援課長","answer":"区民税が４６万円以上ある方について、かかるものです。それは国の制度となっておりますので、なかなか区の中だけでということが難しいというところになっておりますが、補装具以外の部分に対しましても、手当、いろいろな制度を利用して、経済的な支援を行ってまいります。","voiceIndex":170,"id":"exchange-071"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、８９ページと１１１ページの区内私立保育園経費に関わって、豊かな保育の実現を求めて質問します。私立保育園には公定価格が算定され、保育園に寄附されていますけれども、その中で保育士など職員の人件費は約８割を想定して国が出しています。この公定価格について、８割を人件費として想定していることについて、区は認識しているのでしょうか。伺います。","respondent":"中元保育支援課長","answer":"その点については、認識しております。","voiceIndex":176,"id":"exchange-072"},{"speaker":"のだて委員","kind":"質問","question":"一方で、人件費率が８割以上の園は、賃金が約３８万円で、約１０万円高い。経験年数は８.９年、約３.５年長い。株式会社立の保育園では９４％が、人件費率が５割台より低い状況になっています。こうした状況を問題だと思わないのか、伺います。人件費率は保育士の処遇に直結し、保育士が保育を行うのですから、保育の質に直接関わる重要なものだと思いますけれども、いかがでしょうか。","respondent":"中元保育支援課長","answer":"各事業者、各園によって、職員の方の年齢構成や職種、雇用形態は様々です。そちらが民間ならではのメリットだと思ってあります。そのようなものが反映された数字ですので、一旦、軽々に人件費率だけをもって職員の配置を判断することはできないという認識です。","voiceIndex":178,"id":"exchange-073"},{"speaker":"のだて委員","kind":"質問","question":"様々な状況があるからということでしたけれども、３割台の園というのは、先ほど紹介しました、公定価格としては８割を人件費と想定しているということで、それは区も認識しているということでしたけれども、その中で３割台の園などもあるわけです。そうしたところがやはり問題だとは思わないのか、伺います。","respondent":"中元保育支援課長","answer":"国の通知でも、きちんとした保育が確保されていれば、国からの公定価格、その中で上手に使って運営してくださいという通知が出てありますので、その中できちんと保育の質を確保されているものと認識しています。","voiceIndex":180,"id":"exchange-074"},{"speaker":"のだて委員","kind":"質問・要望","question":"上手に使ってと言いますけれども、上手に使って人件費が削減されてしまっては困るわけです。保育士を含め、職員の処遇改善、待遇改善をしていくということが、社会的にもこの間、求められ、少しずつ上がってきてはいますけれども、やはりそれがまだまだ足りないと思います。改めて、人件費率が低い園について改善を求めていくことが必要ではないかと思いますが、いかがでしょう。","respondent":"中元保育支援課長","answer":"処遇改善につきましては、様々、補助金等も出して支援しています。実際に本当に低いようなところには、様々な指導・検査、東京都の検査等でもメスが入っているところだと認識しています。","voiceIndex":182,"id":"exchange-075"},{"speaker":"のだて委員","kind":"質問・要望","question":"そこをしっかり改善していくことが必要だと思います。それは都にもぜひ求めていただきたいと思いますし、区でも指導・検査を行っております。一般質問でもお聞きしましたけれども、人件費については、各園の報告書を確認して、適正に指導しているとの答弁でしたけれども、３割台の園が１１園もあるわけです。区として、これをチェックして、人件費率３割台の園を認めているということなのか、伺います。","respondent":"中元保育支援課長","answer":"人件費だけの問題ではなく、総合的に考えて、こちらから保育園の運営状況については、実態とはまた違うような保護者の方からのご意見も寄せられているところです。","voiceIndex":184,"id":"exchange-076"},{"speaker":"のだて委員","kind":"質問・要望","question":"これによりますと、２０２０年度には１２社・３０園が、約７億円も本部経費や新規園の開設費用に流用しています。１企業では最大１億１,０００万円が流用されています。本来、保育園で使われるべきものとして国や区から出されているものであるのに、本部や新規園の開設のために１年でこれだけ流用されているということは問題だと思いますが、いかがでしょうか。","respondent":"中元保育支援課長","answer":"これに沿いまして、各園から私どもに、そのような取崩しの協議書が参りまして、それを東京都に提出し、東京都できちんと判断され審査されているということで認識しています。","voiceIndex":186,"id":"exchange-077"},{"speaker":"のだて委員","kind":"質問","question":"国がある程度認めているというご答弁でしたけれども、これはやはり、ある程度、本部としてもうけがあるわけではありませんから、本部経費に回すことは必要かもしれませんが、１０％超は取り過ぎだと言われているわけです。そういった園が１５園もあるということですから、やはりこれは問題だと思うのですが、いかがでしょうか。","respondent":"中元保育支援課長","answer":"そちらにつきましては、私どもとしては判断する立場にないと思ってあります。東京都できちんとその辺の取崩しのところについて協議書を認めたものですので、それは総合的に考えた上で、園の恒常的な運営に資するものだということで判断されたという認識です。","voiceIndex":188,"id":"exchange-078"},{"speaker":"のだて委員","kind":"質問・要望","question":"都が審査する機関かもしれませんが、これは区にある保育園ですから、ぜひ区としても認識を持っていただきたいと思います。新規園の開設に使用されているのは、ほとんどが他自治体の保育園に使用されているわけで、本来、品川区の保育園に使われるものが別の自治体に流れているということですので、この点は問題だと考えないのか、伺います。","respondent":"中元保育支援課長","answer":"そこのところにつきまして、私どもは知り得るところではございませんので、そちらの会社の判断、また東京都の指導監査の範囲の中で行われていると認識しています。","voiceIndex":190,"id":"exchange-079"},{"speaker":"のだて委員","kind":"質問・要望","question":"知り得る立場にないということですが、区を通して書類がやり取りされているわけですから、区も知り得る立場にはあると思います。実際、現場ではこの配置を増やして保育をしています。やはり、こうした充実した配置が必要だと思いますので、区として、やはり国に引上げを求める意見を言っていただきたいと思いますけれども、いかがでしょうか。在籍数で公定価格が出ていることについて、区の認識を伺います。","respondent":"中元保育支援課長","answer":"１歳児について１人多く配置していただくことで出す補助金等もあります。０歳児園に看護師を配置していただくことで出すということで、区として相当数の加算の運営費も助成していますので、このような支援を続けていきたいという認識です。","voiceIndex":192,"id":"exchange-080"},{"speaker":"のだて委員","kind":"質問・要望","question":"区が加算していただいているのはいいのですけれども、区の１歳児に加算している園の数、今、０歳児の看護師の加算もおっしゃいましたので、その数も伺いたいと思いますが、やはり配置基準を国にぜひ求めていただきたい、求めるべきだと思いますけれども、いかがでしょうか。","respondent":"中元保育支援課長","answer":"すみません。人数のところはちょっと、手持ちですぐに数字が出ませんが、申し訳ありません。そちらは持ち合わせておりません。国への支援というところを求めるというところは今後の課題としたいと思います。","voiceIndex":194,"id":"exchange-081"},{"speaker":"のだて委員","kind":"質問・要望","question":"課題とするということですので、ぜひ配置基準の引き上げを含め、在籍数で出ている問題を含め、ぜひ国に求めていただいて、保育士の待遇を改善して、保育の質を上げていくということをお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":196,"id":"exchange-082"},{"speaker":"せお委員","kind":"質問・要望","question":"私からは、１０４ページ・１０５ページの学校施設整備費についてお伺いします。当初予算では３億６,０００万円余となっていましたが、収入済額は７億２,０００万円余となっています。２倍程度になっているのですが、この理由をまずお聞かせいただきたいと思います。","respondent":"森学校施設担当課長","answer":"予算についてのご質問です。収入済額が倍増程度していますけれども、こちらは当初予算で見込んでいた部分よりも多く補助金がいただけることになりましたので、収入増となっています。","voiceIndex":198,"id":"exchange-083"},{"speaker":"せお委員","kind":"質問・要望","question":"それ以降は、この４項目を具体的には掘り下げてはいない状況です。そして、品川区の長寿命化計画は、維持管理やコストの縮減の面での長寿命化というのが主な整備内容だと思っているのですけれども、渋谷区のように、長寿命化を、教育効果などを含めた様々な面から広く捉えた計画とするのが、現在の公教育には求められていると私は考えていますが、そちらに関して見解をお聞かせください。","respondent":"森学校施設担当課長","answer":"３点ご質問をいただきました。区立学校の財政等の環境の変化ですけれども、財政収入が増減したりした場合、基本的には、１年で１校ずつ改築していく予定で考えているのですけれども、それができるかどうかというのはあるかもしれません。","voiceIndex":200,"id":"exchange-084"},{"speaker":"せお委員","kind":"質問・要望","question":"現在、ハード面で工夫しているところがあれば、改めて教えていただきたいと思いますけれども、あと、ちょっと１点感じたのが、子どもたちの声というのは聞いているのかなと思って、「こんな学校がいい」とか、そういったところの子どもたちのアンケートとか、そういった声は今まで聞いているのか、そちらもお聞かせください。","respondent":"森学校施設担当課長","answer":"今のところどのようなことをされているかということで、多目的ホールであったり、交流できるような場所、ベンチを設置したり、広い空間、多目的な部分を用意して、様々、学年であったり、障害があってもなくても交流ができるように、改築校では検討しております。","voiceIndex":202,"id":"exchange-085"},{"speaker":"小芝委員","kind":"質問","question":"私からは、１５４ページ、競馬組合配分金に関連しまして、大井競馬場を含みます、勝島・立会川まちづくりプランについてお聞きします。昨今、コロナ禍にもかかわらず、大井競馬場の純利益は年々増加しています。純利益が増えておりますので、品川区に分配される額も当然増えていると思いますが、最近の推移、品川区に分配されている金額の推移について教えてください。","respondent":"古巻総務課長","answer":"競馬組合からの分配金の推移ですけれども、令和３年度につきましては、決算書に記載のあるとおりですけれども、例えば……、すみません。","voiceIndex":205,"id":"exchange-086"},{"speaker":"小芝委員","kind":"質問","question":"後ほど教えてください。その後、昭和６１年に、大井競馬場で初めてのナイター競馬が開催され、品川区の中でも１つのランドマークとも言える施設となってきました。立会川・勝島まちづくりプランの範囲は、西に旧東海道と立会川の商店街を抱え、そして東には６９棟の団地から成る八潮地域を抱えております、それぞれの地域の特色があるわけですが、特にこの勝島地域の特色について教えてください。","respondent":"鈴木都市計画課長","answer":"地域資源としましては、勝島運河、近くに京浜運河と、非常に水辺、水資源が豊かで充実しているというところと、それとあわせて、地域の方々が積極的に取り組んでいる花海道のまちづくり等々が、非常に地域としての魅力の一つです。","voiceIndex":209,"id":"exchange-087"},{"speaker":"小芝委員","kind":"質問","question":"具体的に、勝島地区に住む区民の年代、例えば６５歳以上の方の年代だとか、現役世代、それ以下、例えば４０歳ぐらいまでの年代について、分かれば教えてください。割合です。","respondent":"鈴木都市計画課長","answer":"令和４年現在の状況ですが、０歳から９歳が２０.２％という構成です。５人に１人が０歳から９歳以下というところで、２０歳から３９歳までの子育て世代の方々が３１.２％というところ、６０歳以上の方々が約８％という、非常に若い世帯で構成されている地域です。","voiceIndex":211,"id":"exchange-088"},{"speaker":"小芝委員","kind":"質問","question":"先ほど話しましたミュージカル劇場が新しい文化の中心となるかどうかはまだ分かりません。立会川・勝島まちづくりプランの中では、第３駐車場の開発計画をどのように捉えておられるのか。まちづくりを進める中で、事業者、これは競馬会社だけではなく、この周辺の事業者とも密に連携を取っていくべきと考えますが、区のお考えを教えてください。","respondent":"鈴木都市計画課長、古巻総務課長","answer":"区としましては、まちづくりビジョンの中で、地域のにぎわいというところも、１つ、非常に強く打ち出しています。先ほどの分配金の件ですけれども、令和に入りましてから、様々な分配金の交付金の内訳がありますけれども、合計で令和元年度で４億７,２００万円余、令和２年度で５億円余、令和３年度で６億円余ということで、年々増えている状況です。","voiceIndex":213,"id":"exchange-089"},{"speaker":"小芝委員","kind":"質問・要望","question":"大井競馬場駅から観客の方がこの劇場に流れてくる動線を考える上で、なるべくでしたら勝島エリアに住む区民の方がストレスに感じないようなまちづくりというのも考えていただきたいと思いますが、区の見解について教えてください。今後のまちづくりプランのスケジュールについてもあわせて教えていただければと思います。","respondent":"鈴木都市計画課長","answer":"区としましては、先ほどご紹介いただいたまちづくりビジョン、特に勝島運河上に人道橋の整備、あるいは花海道の修景整備、新浜川公園の再整備というところで、ビジョンに基づく計画をこれから着々と進めていく予定です。","voiceIndex":216,"id":"exchange-090"},{"speaker":"小芝委員","kind":"質問・要望","question":"事業者との連携を深めつつ、区民ニーズに沿ったまちづくりを進めていっていただきたいと思います。アンケートも、たしかホームページで見ました、平成２９年のアンケートが載っていたと思いますが、これも改めて、新たな区民ニーズの掘り起こしをしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":218,"id":"exchange-091"},{"speaker":"木村委員","kind":"質問","question":"議会広報費ですけれども、令和２年度は４,７２６万円余、令和３年度が４,６５３万円余からですが、以前にも一度お聞きしたことがあったかと思いますが、年間６回発行し、区内全域に２,７４６万円余の費用をかけて配布していただいていますが、区内で何件配り、それから配布は何日間を目途に期間を縛ってやっているのかどうか、これが分かればお聞きしたいと思います。","respondent":"工藤区議会事務局長","answer":"区議会だよりの配布につきましての件です。区内全戸に配布しておりまして、令和３年度は約２３万５,０００世帯にお配りしているものです。配布の期間は、発行日から３日間かけまして配布しているものです。","voiceIndex":220,"id":"exchange-092"},{"speaker":"木村委員","kind":"質問・要望","question":"この２,７４６万円余の中には、発行費と配布費用が含まれていると思いますけれども、それでよろしいのかどうか。そして、含まれているのであれば、その内訳はどのようになっているのかをお聞かせいただきたいと思います。","respondent":"工藤区議会事務局長","answer":"経費の件です。ご指摘のとおりでございまして、まず発行に要する経費が、主に冊子の印刷経費でございまして約１,３４７万円、それから配布に要する委託経費が約１,３９９万円となっています。","voiceIndex":222,"id":"exchange-093"},{"speaker":"木村委員","kind":"質問","question":"問題は、区民の皆さんにこれを読んでいただくには、まず手に取って開いていただくことが第一の目標でありますけれども、手に取って読んでいただくことで、制作に携わった方々の苦労というものが報われると私は思いますけれども、その点について、行政から見ていかが思われているでしょうか。お聞かせください。","respondent":"工藤区議会事務局長","answer":"区議会だよりにつきましては、制作につきましては、以前は職員が作成しておりましたが、議員主導で、議会改革の情報発信分科会で検討され、現在の広報会議に引き継がれまして、平成３０年から、手に取っていただくためにサイズをＡ４判に変更することや。","voiceIndex":224,"id":"exchange-094"},{"speaker":"木村委員","kind":"質問・要望","question":"品川区の現状の姿を知っていただくためには、区に興味を持っていただくことというのは大変大事だと私は思っています。民間の方々の、また声というもの、意見、アイデア的なものも取り入れてみても面白いとは思いますけれども、もしその点が分かれば、何か回答があればお聞かせいただきたいと思います。区民の心を引きつけるために、どのようなところに一番注意をされているのか、そこもお聞かせください。","respondent":"工藤区議会事務局長","answer":"作成に当たりましては、議会改革の中で、区議会だよりの編集方針というものを策定しておりまして、基本コンセプトを、読みやすい、親しみやすい、分かりやすいの３点といたしまして、文書やレイアウトに注意しながら作成して、お届けしています。","voiceIndex":226,"id":"exchange-095"},{"speaker":"木村委員","kind":"質問","question":"購読率というものが分かるシステムというのは、何かあるのでしょうか。実際、購読率が分かっていないのではと私は思っているのですけれども、実際のところ、もし購読率が正しく分かっているのであれば、いかにしてこの調査を行っているのか、調査方法もまたお聞かせください。","respondent":"工藤区議会事務局長","answer":"調査につきましては研究は必要ですが、例えば区の世論調査の中で、それらを調査項目として追加するなども考えられますので、そのようなところも含めての検討になると考えております。","voiceIndex":228,"id":"exchange-096"},{"speaker":"木村委員","kind":"質問","question":"購読率をもっと上げるためにも、我々区議会が、個人的にでも構いませんけれども、どのようなことをお手伝いできるとお思いでしょうか。","respondent":"工藤区議会事務局長","answer":"やはり今、議会改革を進めている中で、議会報告会や、様々な地域団体との意見交換会、あるいは小学生の議会傍聴や職場体験の受入れ等も、積極的に今現在、区議会で行っていると感じておりまして、やはりこれらの取組が、区議会への関心につながり。","voiceIndex":230,"id":"exchange-097"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私からは、決算書の８９ページ、生活困窮者自立支援事業についてと、成果報告書の６１ページから、歳入全般、特に特別区税、地方消費税交付金、財政調整交付金について、それから基金積立金について伺いたいと思います。生活困窮者自立支援事業について伺いたいのですが、緊急小口資金と総合支援資金が９月末で打切りとなりました。","respondent":"櫻木生活福祉課長","answer":"区全体として重層的支援を進めておりますので、生活困窮者相談も、その中の１つの窓口として、連携して対応していきたいと考えております。","voiceIndex":233,"id":"exchange-098"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"コロナがまだ終息するどころか、今も拡大し続けているという状況で、第８波が起こる可能性も非常に高いと言われています。返済猶予とか、そういうきめ細やかな対応が必要なのではないかと思うのですけれども、そういうことも含めて、区からも国にぜひとも求めていただきたいと私は思うのですけれども、いかがでしょうか。この制度の延長も求めていただきたいと思うのですけれども、いかがでしょうか。","respondent":"櫻木生活福祉課長","answer":"免除申請もしくは猶予または拡大というお話、または自立支援給付金の延長について国に求めるですが、こちらは厚生労働省および社会福祉協議会等できちんと適切な判断をするということと考えていますので、それを注視してまいりたいと考えています。","voiceIndex":235,"id":"exchange-099"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"リーフレットもいろいろなところに置いていただくということにもなりましたけれども、さらに私は広報などでも、暮らし・しごと応援センターの周知を、もう困ったときには１人で悩まずにご相談くださいというのを、ぜひしていただきたいと思うのですけれども、いかがでしょうかということが１点です。そういうこととか、それから、いろいろなところにつなげていく。","respondent":"提坂税務課長、櫻木生活福祉課長","answer":"ただ、何回もお手紙をお送りしたにもかかわらず、あと今、コロナ禍で、なかなか実態調査などができない状態ではありますけれども、何の反応もない方については、やむを得ず最終手段ということで。関係機関にパンフレットを置いていただいたり、定期的に広報しながわにも掲載しています。今後も関係部署と相談して、目に止まりやすいような周知方法を工夫するなど、努めてまいりたいと考えています。","voiceIndex":237,"id":"exchange-100"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひよろしくお願いいたします。それから基金なのですけれども、最後にちょっと、決算状況一覧表では、９１４億３,７００万円余ということになっているのですけれども、決算書の５２８ページ・５２９ページの数字と違うのですけれども、これは決算状況一覧表の９１４億円余ということが、令和３年度の決算の基金残高ということで捉えていいのか、その点を伺いたいと思います。","respondent":"黒田財政課長","answer":"決算状況一覧表に記載しております令和３年度末現在高の基金残高の合計額は、様々な基金の残高を合計したものですので、令和３年度末の基金の残高は、決算状況一覧表にある９１４億円余というのが、品川区の基金の保有している残高です。","voiceIndex":240,"id":"exchange-101"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"こちらは時間がなくなってしまったのですけれども、この基金残高というのは昨年度よりも９２億７,３００万円余増えているのです。歳入の分野でも、特別区税が９億円増えています。地方消費税交付金が１０億３,０００万円増えています。そして、セーフティーネットをもっと厚くするというところにも、ぜひご検討いただきたいと要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":242,"id":"exchange-102"},{"speaker":"松澤委員","kind":"質問","question":"私からは、決算書１００ページの社会資本整備総合交付金より住宅・建築物耐震化支援事業、１億２,１５３万７,０００円と、コンクリートブロック塀等安全化支援事業、６３９万９,０００円について、同じく１０２ページになります防災・安全交付金より密集住宅市街地整備促進事業、５,１３５万２,０００円について、まとめて質問いたします。","respondent":"長尾建築課長","answer":"令和３年度の実績としましては、国費が充当されている主なものとしては、ブロック塀等の除却工事助成が４０件、軽量フェンスの設置は５件というような内容となっております。","voiceIndex":245,"id":"exchange-103"},{"speaker":"松澤委員","kind":"確認","question":"例えば１９８１年、ここで初めて新耐震基準というものが設けられました。さらに、２０００年にも基準の強化というのがあるのです。今までの例だと旧耐震基準というのが主になっていますので、１９８１年から２０００年の１９年間、これは新耐震基準ですけれども、要は基準の改正があったということは、耐震化のまた最後の確認といったものもしなければいけないのではないかと私は考えております。","respondent":"長尾建築課長","answer":"こういった都の調査結果や、あと、まだ国や都の助成に対しての動向も注視して、より効果的な耐震化支援というものを行っていきたいと考えております。","voiceIndex":249,"id":"exchange-104"},{"speaker":"松澤委員","kind":"質問・要望","question":"そうですね。東京都でもそういったお話が出てきたというのは初めてお聞きしました。だんだん進展しているものだと感じています。耐震診断といったものの抜本的な見直しであったり工事助成の増額といったものを引き続き要望させていただいて、次の質問に移ります。次に、密集住宅市街地整備促進事業についてお聞きいたします。","respondent":"大石木密整備推進課長","answer":"区といたしましては現在、３例目として、東中延一丁目で事業を進めてあります。引き続き、密集住宅市街地の改善に向け、各種事業を展開していくとともに、委員ご紹介の整備事例も参考にしながら研究を進めてまいりたいと思います。","voiceIndex":251,"id":"exchange-105"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私からは、質問順で、９３ページ、個人番号カード経費、４３ページ、災害復旧特別会計、１２７ページ、共通商品券普及促進事業について伺っていきます。充当事業で「個人番号カード経費ほか２事業」とあるのですけれども、これについて何なのか教えていただきたいと思います。","respondent":"吉野戸籍住民課長","answer":"こちらなのですが、法改正によりまして、令和３年９月から、国がＪ－ＬＩＳに対して直接補助するような形になりました。そのため、以降、この補助金は出ていない状況になっております。","voiceIndex":254,"id":"exchange-106"},{"speaker":"あくつ委員","kind":"質問・要望","question":"法改正で２分の１になりましたということで、確認させていただきました。関連して、区の職員のカード交付について確認させていただきたいと思います。マイナンバーカードの交付については、２０１６年の１月から始まりましたので、もうすぐ７年になろうとしています。あったのであればどのような内容であるのか教えてください。","respondent":"崎村人事課長","answer":"令和２年度、令和３年度についても、申請取得状況の調査とあわせて、取得の推進について通知があったところです。今年度も５月と７月に、同じような内容で取得の推進について通知があったところです。","voiceIndex":256,"id":"exchange-107"},{"speaker":"あくつ委員","kind":"確認","question":"それは確認しておきたいと思います。もう一つ、幾つか勧奨の中に、技術的助言ということの中の通知の中には、職員に対して、被扶養者もあわせて令和２年３月までのマイナンバーカード取得について勧奨するようお願いしますと書いてあるのですが、これは職員に関して、いわゆる人事課が勧奨してくださいと書いてあるのですけれども、それは行ったのか、またそれは何回程度行われたのか、確認させてください。","respondent":"崎村人事課長","answer":"取得の推進について、被扶養者を含めてというところのご質問ですけれども、令和元年から、先ほどお話しさせていただきました国からの通知があるたびに、通知に関しての取得状況の調査の中で、被扶養者も含めて報告していただくようにしておりますので。","voiceIndex":258,"id":"exchange-108"},{"speaker":"あくつ委員","kind":"質問","question":"今ご答弁の中にあったとおり、人事担当課においては、職員等の申請取得状況の把握をお願いしますとあります。国の通知のとおり、人事担当課において、区職員の申請と取得状況を把握されていらっしゃるのか。されているのであれば、調査の手法、その頻度について教えてください。","respondent":"崎村人事課長","answer":"令和４年度につきましては、５月末現在のほか、６月末現在、８月末現在と、結構期限を細かく設定して調査を実施しておりまして、今回も１０月末現在で調査を実施しています。","voiceIndex":260,"id":"exchange-109"},{"speaker":"あくつ委員","kind":"確認","question":"もう一つ、いわゆる、何というのですか、マイナンバーカードのやはり１つの問題点として、できたものを取りに行くというのが非常に手間がかかるというところがあって、本人確認等があるというところで、それを取りに行く場合、例えば公務員の方が所属長に申入れをした場合、それは認められるのか、認められないのか、その辺りについてご見解を教えてください。","respondent":"崎村人事課長","answer":"調査結果の公表というお話ですけれども、こちらは総務省において調査を実施しているのですけれども、これまで各自治体ごとの実績というのを公表しておりません。したがいまして、区として職員についての取得率を公表することは現在考えておりません。","voiceIndex":262,"id":"exchange-110"},{"speaker":"あくつ委員","kind":"提案","question":"非常に難しい問題で、このことが明らかになったときに、結構、反対の声というか、強制なのかということで、公務員の団体の方からも、結構、問題の声が上がったということは報道で確認しましたけれども、先日の一般質問で交付への決意を伺った際に、地域振興部長からは、区としても申請サポート等を積極的に実施し、交付の拡大に取り組んでいくと、業務としてのこういうご答弁をいただきました。","respondent":"平原防災課長","answer":"一方で、ご指摘のとおり、訓練の高齢化、あるいは決まったメンバーのみの参加といったところの課題も見受けられるところでございまして、そういったところに対応して、また別立てでということで、しながわ防災体験館の充実。","voiceIndex":264,"id":"exchange-111"},{"speaker":"あくつ委員","kind":"提案","question":"私たちの命は私たちで守る。大地震は必ずやってきます。今、地震が起きたら、どう行動しようかと。こういう機会の中で、もう少し、一歩踏み込んだ、自助・共助の意識の高揚・醸成というのは、そういうことで求めていきたいと考えているのですけれども、防災区民憲章についてどのようにお考えか、前に長期的な検討をしていただくというご答弁をいただいていたので、その辺り、もう一度ご答弁をお願いします。","respondent":"平原防災課長","answer":"防災区民憲章についてのお尋ねですけれども、令和元年の第３回定例会での、長期的に検討というところの答弁と重なるところもありますけれども、区では、まずは平成２６年に制定させていただきました品川区災害対策基本条例にうたいます、自助・共助の重要性につきまして。","voiceIndex":266,"id":"exchange-112"},{"speaker":"高橋（し）委員","kind":"質問","question":"１６２ページ、特別区債と、３８６ページ、公債費についてお尋ねします。特別区債のほうなのですが、令和３年度は学校施設整備費で１５億４,４００万円の教育区債を発行いたしました。逆に言うと、１１億８,６００万円は起債しなかったということなのですが、なぜ予算現額の起債が行われなかったのでしょうか。","respondent":"黒田財政課長","answer":"令和３年度の特別区債の中で、学校用地費として取得しておりますが、予算で計上した金額よりも、実際に購入した額が、国の契約した額に落差がありますと、その部分は金額として差がありますので、そういった関係で金額に差があるものです。","voiceIndex":269,"id":"exchange-113"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、１１億円も予算があったということなのでしょうか。学校用地取得費１校６億円云々とありますけれども、そこのところをお願いします。","respondent":"森学校施設担当課長","answer":"今のご質問ですけれども、学校用地取得につきましては、落差の関係で、７.４億円ぐらい減です。続いて学校改築のほうで、国庫補助金が想定より多かったというところで、４.５億円ほど減なので、約１１億円ということになってあります。","voiceIndex":271,"id":"exchange-114"},{"speaker":"高橋（し）委員","kind":"質問","question":"用地取得費のほうが落差で７.４億円、先ほどもやり取りがありましたが、教育費補助金の中の、恐らく国庫補助金の約４億円が入ってきたので、その分起債しなくてよかったという理解で、分かりました。工事などが進まないので、その分の費用というか、かからなくなってしまったというようなことではないという理解でよろしいでしょうか。","respondent":"森学校施設担当課長","answer":"そのとおりです。工事については、そういうことはしておりません。","voiceIndex":273,"id":"exchange-115"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"工事は円滑に進んでいるということが確認できました。それから、平成１２年から令和２年度の起債利子が１億３,７２０万円強の決算額です。この起債と償還金について、いろいろお話を伺ったり、これまで来ているのですが、なかなか整理できていないので、区として起債するときに、予算が議決されました。その後、どのような手続が行われて、起債が進められていくのか、教えていただきたいと思います。","respondent":"黒田財政課長","answer":"予算編成の中で、先ほど申し上げたとおり、用地購入費でありますとか施設整備費について、そのうちの幾らが起債対象になるかというところも協議しながら、予算額を決めてまいりまして、予算が編成されるです。","voiceIndex":275,"id":"exchange-116"},{"speaker":"高橋（し）委員","kind":"質問","question":"そこで、実際に手続して借りることになるというところなのですが、何といいますか、それぞれの事業によって資金の割当てはいろいろあると思うのですが、具体的な、いわゆる引受け先というのですか、それから借入れの金額等は、どこのセクションで、どこに借りるというのですか、どこに引き受けてもらうかというのを、どのようにして決めて、それで具体的に申請というか起債していくことになるのでしょうか。","respondent":"黒田財政課長","answer":"その中で様々、銀行から借りるものもあれば、政府債というのですか、財政投融資から借りるというようなものもありますので、そういったものにつきましても、起債メニューの中で東京都と協議して決まっていくというような状況です。","voiceIndex":277,"id":"exchange-117"},{"speaker":"高橋（し）委員","kind":"質問","question":"今お話があった政府系だと、例えば財政融資債でお借りするとか、あと、今、民間銀行から等もありますが、そういうものを東京都などと協議しながら、借入れ先や借入金額を決めていくということが分かりました。そうすると、令和３年度の学校施設整備費の起債ですけれども、金額が大きいので１本ではないのかもしれませんけれども、どのような引受け先になるのでしょうか。もし分かればお願いします。","respondent":"黒田財政課長","answer":"令和３年度の起債につきましては、借入れ先は、国の財政融資資金から借入れをしているものです。","voiceIndex":279,"id":"exchange-118"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"細かい話で、すみません。ありがとうございました。先日の報道では、ワクチン接種費用を全部国費で負担していることについて、特例的な措置は廃止すべきだという議論があったという報道もありましたが、国庫支出金について、例えばその年度で国庫支出金を受けて、しかし余ったという場合は、どのような形で返還するのでしょうか。それは、決算書の中でどのように記載されるのでしょうか。","respondent":"黒田財政課長","answer":"決算書の中では、国庫支出金の衛生費負担金の、９２ページにありますけれども、新型コロナウイルスワクチン接種負担金を見ていただきますと、９３ページ、右側のところに、収入超過額という形で１４億８,４００万円余と記載がありますので。","voiceIndex":281,"id":"exchange-119"},{"speaker":"高橋（し）委員","kind":"質問","question":"令和３年度の決算から令和４年度につながって、先日の補正予算のところに出てきまして、その説明が非常に複雑だったので、今、お話を伺いました。ここも、予算というか、決算の方法など、起債を含めたいろいろな国庫支出金などについてはお尋ねしていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":283,"id":"exchange-120"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"令和３年度主要施策の成果報告書の財政全般について、１２９ページ、（仮称）旗の台六丁目公園、１３１ページ、密集住宅市街地整備促進事業について、お伺いします。成果について、区の歳入が特別区民税の対前年度プラス約６.６億円、プラス６３億円の増加となったと。一般財源では８.５％の増となって、３年ぶりに前年度プラスとなっているところです。よろしくお願いします。","respondent":"黒田財政課長","answer":"は決算の全般ですけれども、今、委員からご指摘がありましたとおり、執行率については、やや低い部分もございましたが、令和３年度は補正予算を第９号まで編成いたしまして、いわゆる新型コロナウイルスの対応でありますとか、それに伴う経済対策というところで。","voiceIndex":285,"id":"exchange-121"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"そんな中、来年度、本年度期末には中小零細企業の方たちは本当に今大変な思いをしております。あえて来年度に向けて、この支援対策をいま一度、しっかりとやっていただいているのは分かるのですけれども、やっていただきたいという思いで私は発言させてもらっているのですけれども、それについて、来年度に向けての意気込みというか、教えていただきたいと思います。ぜひよろしくお願いします。","respondent":"黒田財政課長","answer":"令和４年度、今年度に入りまして、補正予算で物価高騰対策ということで、いわゆる中小企業の資金の融資あっせんの物価高騰対策版というのも実施したりという中で、時期を捉えて施策を打っておりますので、今お話がありましたように、これから当初予算の編成をしていく中で。","voiceIndex":287,"id":"exchange-122"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひよろしくお願いいたします。続きまして、１２９ページ、（仮称）旗の台六丁目公園についてお伺いします。これはまず確認なのですけれども、都市計画交付金で、当初予算ですと１億４,６８０万円、決算では１億７,２００万円余となっているのですけれども、もし分かればその詳細を教えていただきたいと思います。","respondent":"黒田財政課長","answer":"（仮称）旗の台六丁目公園に対する都市計画交付金ですが、都市計画交付金につきましては、東京都が固定資産税と都市計画税を合わせて徴収し、特別区がある区域内でも徴収しておりまして、事業に応じて都が交付するというような仕組みになっておりますが。","voiceIndex":289,"id":"exchange-123"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"理解できました。どうもありがとうあります。この公園の事業なのですけれども、都市計画公園に基づいて防災広場の整備推進をやって、今現在も公園が整備されております。今の進捗状況をお知らせいただきたいと思います。","respondent":"高梨公園課長","answer":"工事は１２月上旬竣工予定で、現在順調に進んでおりまして、今年度内、１２月中旬頃の開園を目指して、現在も実施しています。","voiceIndex":291,"id":"exchange-124"},{"speaker":"高橋（伸）委員","kind":"質問","question":"私も先日、整備の現場を見てきました。そのときに、複数の若い家族の方が「公園ができるのだ」と、すごく楽しみにしている姿を私は見ました。今、課長がおっしゃられたように、１２月上旬ということで、告知・啓発、すごく静かな場所なので、どの程度、周知をするのかというのは私は分からないのだけど、今、（仮称）旗の台六丁目公園となっているじゃないですか。もう公園の呼称というのはついたのですか。","respondent":"高梨公園課長","answer":"失礼いたしました。仮称で旗の台六丁目公園ということで事業を進めてまいりましたが、先般、町会を中心とした地元の方の意見を取り入れまして、この公園は、旗の台六丁目のハタロク公園として、名称は区で決定したものです。","voiceIndex":293,"id":"exchange-125"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"分かりました。ハタロク公園ということで、私も周知しておきます。ぜひ、楽しみにしていますので、ありがとうございました。続きまして１３１ページ、密集住宅市街地整備促進事業に関連しまして、二葉三丁目２４番街区事業用地は、防災広場が今、検討されているかと思うのですけれども、それについて詳細を教えていただきたいと思います。","respondent":"大石木密整備推進課長","answer":"二葉三丁目に整備を予定しております防災広場については、現在、地域の皆様とワークショップ形式で検討を行っているところです。今年度中に基本計画を取りまとめまして、来年度、基本計画を基に、令和５年度に設計を行い、令和６年度に工事の予定をしております。","voiceIndex":295,"id":"exchange-126"},{"speaker":"高橋（伸）委員","kind":"質問","question":"私もこの防災広場検討会第１回目の資料を見ながら、今、質疑させていただいているのですけれども、これはいろいろ事例があります。その中で、お子さんの健康遊具とか、子どもの遊具が記載されているのですけれども、これは検討会の中で子どもの遊具についてというのがあったのかということと、今後検討していくのかということだけお聞きしたいと思います。","respondent":"大石木密整備推進課長","answer":"実際に１回目の検討会の中では、検討会の委員の皆様から、やはり少し面積が狭いということがありまして、あまり要望がないのではないかという意見だったり、実際に置かなくて、走り回っている子どもを見たほうがいいという意見がございまして。","voiceIndex":297,"id":"exchange-127"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これをぜひ防災広場の中に、健康器具もそうですけれども、遊具を備えていただきたい。これは要望です。ぜひよろしくお願いします。それと、防災広場について、また所管がまたがると思うのですけれども、公園課との連携という部分で、どういうふうに連携されているのかというのも、いま一度私も理解しておきたいので、お知らせをお願いしたいと思います。","respondent":"高梨公園課長","answer":"計画の段階でも、ワークショップ等、木密整備推進課で行う際には、公園課から整備部隊・維持部隊の人間を派遣して、一緒になって検討していくという形で連携を取って進めているところです。","voiceIndex":299,"id":"exchange-128"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"二葉も木密地域は本当に密集しているところなので、防災広場と、もう本当に理解しているのですけれども、公園の整備の中に、ぜひ遊具を取り入れていただきたいというのを、改めて要望させていただきたいと思います。最後に何かあったら、よろしくお願いします。","respondent":"大石木密整備推進課長","answer":"今回につきましては、今いただいた意見を、今月予定しております２回目の検討会で意見としてフィードバックして、検討会の皆様で議論をしていただければと考えているところです。","voiceIndex":301,"id":"exchange-129"},{"speaker":"松本委員","kind":"質問","question":"私は、５２ページ、特別区民税、１６２ページ、特別区債、７８ページ、区民住宅使用料について伺います。中でも、ずっと議論もありましたけれども、令和３年度特別区民税というのは、令和２年の所得に基づいて決定されると。人口が、４,０００人ぐらいですか、増えたということがあったかと思いますし、あとは収納率はもう本当に、税務課の皆様に頑張っていただいたというところかと思います。お願いします。","respondent":"提坂税務課長","answer":"それで、その年齢層の方がやはり高額所得の方が多いかと推測できるところなのですけれども、実際に課税標準額７００万円を超える方が、人数的には納税義務者全体の約１割にすぎないのですけれども、税額としては全体の約４割を占めているという現実があります。","voiceIndex":304,"id":"exchange-130"},{"speaker":"松本委員","kind":"確認","question":"１人当たりの収入額が上昇してきているというふうな話になってきていると思います。先ほど年齢層のお話もありましたけれども、もう一個、一応確認しておきたいのですけれども、税制改正で、何がしか税収面で影響があったのか、お考えを伺います。","respondent":"提坂税務課長","answer":"ここ数年、度重なる税制改正が行われているところですけれども、主なところでは、税収増につながったと思われる部分ですけれども、合計所得２,４００万円以上の基礎控除額が一律３３万円だった部分が低減されたと。","voiceIndex":306,"id":"exchange-131"},{"speaker":"松本委員","kind":"質問・要望","question":"間違いだったら指摘していただきたいのですけれども、今の税制改正は、たしか令和３年度の税収からの反映だったかと思うのですけれども、それで間違いなかったでしょうか。","respondent":"提坂税務課長","answer":"間違いないかと思います。","voiceIndex":308,"id":"exchange-132"},{"speaker":"松本委員","kind":"質問","question":"令和２年度と令和３年度を比較すると、そこは納得感があるのですけれども、先ほど申し上げたように、平成３０年度からかなり上がってきているという状況です。そうすると、そこに入る人たちというのは、基本的には品川区も今、物価、地価が上がっていますから、そういう方たちのことを考えると、比較的、高額な所得の方たちが入ってきたのかなと思うのですけれども、そこの部分はいかがでしょうか。","respondent":"提坂税務課長","answer":"７００万円超の所得の方が増えているということで、先ほどの税制改正で、住宅ローンの借入金控除の特例延長というのもありますので、その辺の制度をうまく活用してタワーマンションに入居する方が増えていて、それが結果的に税収増にもつながっていると考えています。","voiceIndex":310,"id":"exchange-133"},{"speaker":"松本委員","kind":"質問","question":"そのように考えたときに、これは都市計画あるいは都市開発との関係で、そういった視点が区としてあるのかというところも１つ重要かと思います。こういった考え方、より多くの収入を得ている方が流入してくることによって、それが区の全体のプラスになっていくというお考えを持って、計画あるいは開発を行われているのか伺います。","respondent":"鈴木都市計画課長","answer":"ただ、区が基本的な再開発やまちづくりを進める上で、今、マスタープランの検討もしておりますが、そうした視点がしっかりうたわれているかというと、今現在、計画上はうたわれていないというところがありますが、側面的には当然、そうした視点もあろうかと思います。","voiceIndex":312,"id":"exchange-134"},{"speaker":"松本委員","kind":"質問","question":"特別区債についてなのですけれども、エコルとごしがグッドデザイン賞を獲得するなど、品川区は環境のまちという認識も少しずつ広がってほしいというところがあります。これは東京都との協議は必要かと思いますが、品川区としても、これは環境のまちというところを訴えていく中でも、こうしたＳＤＧｓ債、グリーンボンド、サステナビリティボンドを発行するというお考えはあるのか伺います。","respondent":"黒田財政課長","answer":"いわゆるＥＳＧ債は、先ほど申し上げた地方債の仕組みでいいますと、いわゆる民間資金を活用した市場公募債ということになろうかと思いますが、引受け先が民間の金融機関になりますと、どうしても利率が高いというところもありますので、発行目的と資金調達の側面から考えて。","voiceIndex":314,"id":"exchange-135"},{"speaker":"松本委員","kind":"意見","question":"時間がない中でありがとうございました。品川区としても、環境に取り組んでいくのだという姿勢が大事だと思いますので、ぜひ引き続きご検討をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":316,"id":"exchange-136"},{"speaker":"須貝委員","kind":"質問","question":"私は、１００ページ、防災・安全交付金についてお聞きしたいと思います。その中で、震災後、家屋が全壊したり火災で焼失した場合、災害弔慰金をはじめ、被災者生活再建支援金、災害援護資金など、被災者に対するお見舞いや支援制度がありますが、概算でいいのですが、どのくらいの支援金が出るのですか。教えてください。そして、これらの支援金で生活再建は可能と思われますか。見解をお聞かせください。","respondent":"平原防災課長","answer":"例えば学用品をなくした場合は学用品の現品支給、あるいはお亡くなりになった場合には最大５００万円までの弔慰金といったものもありますので、一概にそれで何かが足りるといったところについては言いづらいところですが。","voiceIndex":318,"id":"exchange-137"},{"speaker":"須貝委員","kind":"質問","question":"一番マックスで、やはり５００万円から、３００万円、１００万円、それぞれあります。でも、これらの額では、どうなのでしょう。そこに住まわれている方が本当に生活再建ができるのでしょうか。その辺についてご見解をもう一回お聞きします。２,０００万円も３,０００万円も出る話ではなくて、やはり私は金額的には、かなり絞られる、少ない金額かと思っているのですが、いかがでしょうか。","respondent":"平原防災課長","answer":"それ以外のところで、例えば仮設住宅でありますとか様々な支援策と取り合わせまして、震災後の生活再建を進めていくものと考えております。","voiceIndex":320,"id":"exchange-138"},{"speaker":"須貝委員","kind":"意見","question":"４８時間後に延焼して自分の自宅が燃えました。だけど、それだけでは、やはり品川区を見て仮に５０％としたら、木造家屋が多い、密集市街地が多い。そうしたら、非常に私は心配しているのですが、やはりもっと積極的に、住宅再建、それから家財道具の購入などを考えて、民間の地震保険に加入するように普及啓発をしっかり前向きにやるべきだと私は思うのですが、ご見解をお聞かせください。","respondent":"平原防災課長","answer":"そういったところもございまして、地震保険は公的な位置づけがあるということで、私どもも現在ではまだ、しながわ防災ハンドブックに紹介させていただいているというような形でやらせていただいておりますけれども、様々な場を捉えまして、今後。","voiceIndex":322,"id":"exchange-139"},{"speaker":"須貝委員","kind":"質問・要望","question":"地震でないと使えませんとは書いてありますけど、今言ったとおり、４８時間前にどこかが燃えて、自分のところは４８時間後に延焼した。全焼したのです。私はその辺を考えていただきたいと思います。年額５,０００円で、再検討の給付金は最大で６００万円です。そして、兵庫県の教訓と経験からつくり上げた、このような共済制度を、私はぜひ品川区でも創設するべきだと思いますが、ご見解をお聞かせください。","respondent":"平原防災課長","answer":"そういった中で、復旧の段階から復興に至るところ、いよいよ当面の生活再建から元に戻っていく段階としての生活再建、そういったところの渡し方、そういったときに必要な金額、どういったものがあるかというところも、先ほどの地震保険なども相まりまして。","voiceIndex":324,"id":"exchange-140"},{"speaker":"須貝委員","kind":"質問・要望","question":"ぜひ、これだけの木造密集地域もあります。一人でも多くの区民を助けるというのは、やはり自治体の使命だと私は思います。仮に品川区で共済制度をつくれなくても、やはり民間の、少なくとも地震保険に入って、皆さん、再建してくださいということを積極的に進めていただきたいと私は思います。区では、一人ひとりを助ける、再建させるということはできないですよね。ぜひ共済制度も含めてご検討ください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":326,"id":"exchange-141"},{"speaker":"大倉委員","kind":"質問・要望","question":"５２ページ、特別区民税、６４ページ、集会所使用料から荏原第一地域センター、時間があれば１３７ページの衆議院議員選挙執行費から選挙について伺えればと思います。その中で、こうした火曜延長窓口や日曜開庁を行うに至った経緯を改めて教えていただきたいのと、令和３年７月２６日からこちらが開かれて、今やられているところであります。","respondent":"提坂税務課長、川島地域活動課長","answer":"そういう方については、真摯に相談の窓口を開いて、状況をお聞きして、分割納付とか徴収猶予とかと、最終的に生活困窮ということであれば執行停止とか、そういうこともありますので。多分、庁舎のほうとも、接続というのですか、行き来の部分などというのも少しあるのかなというところもありましたので、荏原地区に、今までにないような新しいサービスが何かできないかということで、様々検討しまして、火曜延長窓口。","voiceIndex":328,"id":"exchange-142"},{"speaker":"大倉委員","kind":"質問・要望","question":"これについては、いろいろな課題があって、その課題解決をしてきているのだろうと思っておりまして、また今後、こういった新しいところにというところで今回入っているということも分かったのですが、今後こうしたさらなる区民の利便性の向上というところでは、ほかの地域センターでも考えられるようなことも、広さとか、今でいう人員とかというところも課題ではあるのかと思うのですが。","respondent":"川島地域活動課長、遠藤商業・ものづくり課長","answer":"その都度、どこの施設がどうなのかというのもなかなか予測がつきませんが、新しくするときには、どのようなものができるかというのは、しっかりサービス向上に資するものを検討していきたいと考えています。今までの、コロナの対策ということで大変だった部分が、現状ではやはり原材料高、それから価格低下がなかなかしづらいという部分と、あと以前の融資があった部分で、その支払いが始まっているというようなところに加えまして。","voiceIndex":331,"id":"exchange-143"},{"speaker":"大倉委員","kind":"質問・要望","question":"荏原第一地域センターは、ありがとうあります。不定期でということで、なるべく土曜日も区民の方が利用できるように工夫してやっていただいているのだと思いますので、引き続きよろしくお願いいたします。事業承継がかなりネガティブになっているところだと思いますので、今後、ウィズコロナを見据えた施策・対策というのを考えていただきたいのですが、ご検討をお願いします。","respondent":"遠藤商業・ものづくり課長","answer":"そういう部分で、借換融資とか新たな融資制度などを設けて、中小企業の支援に努めているところです。今後、国でも様々な支援策が出ているところですので、その辺を周知しまして、引き続き区としてどのような支援ができるか考えていきたいと考えています。","voiceIndex":334,"id":"exchange-144"},{"speaker":"中塚委員","kind":"質問・要望","question":"ここに関わって、区立伊藤幼稚園廃園について、存続を求めて質問したいと思います。これまでも依命通達について、マイナスシーリングという予算削減が、区民生活に必要な福祉や教育などの事業削減につながることはあってはならないと、繰り返し求めてきました。そこで、区立幼稚園のあり方について、企画部としてはどのような意見を述べてきたのか、そして出席した課長は誰か、ご説明いただきたいと思います。","respondent":"佐藤計画担当課長","answer":"会議の場での発言ということですけれども、ホームページ等にも出ておりますけれども、幼稚園、閉園になる対象のところの実現性ということで、今、通っていらっしゃるお子さんの受皿の部分ですとか、今後の区立幼稚園のあり方ですとか。","voiceIndex":337,"id":"exchange-145"},{"speaker":"中塚委員","kind":"質問・要望","question":"計画担当課長が閉園を求めたと、客観的な意見を述べたということでよいのか、改めて伺いたいと思います。企画部が教育委員会に直接意見を言うときは、決まって適正配置・適正規模という名の統廃合です。今回もまた企画部は、区立幼稚園の統廃合を、３者の会議の場で計画担当課長が主張してきたということでよいのか伺いたいと思います。","respondent":"佐藤計画担当課長","answer":"企画部の管理職ということで出席しておりましたので、今回のこの件に限らず、限られた財源に対して適正に事業を行うという視点からご意見を述べさせていただいたです。","voiceIndex":339,"id":"exchange-146"},{"speaker":"中塚委員","kind":"質問・要望","question":"限られた財源の中で適正にという視点から意見を述べたということは、閉園を求めたということでよいのですか。","respondent":"佐藤計画担当課長","answer":"区立幼稚園今後のあり方検討委員会という会議で示されました資料について、そういった点について今後どうしていくかという会議でございましたので、所管課だけでやるよりは、企画部も含めた言わば客観的な目を通してよりよい事業について考えていくという場でございましたので。","voiceIndex":341,"id":"exchange-147"},{"speaker":"中塚委員","kind":"質問・要望","question":"企画部として閉園を保育課や教育委員会に求めていないというのであれば、企画部は何を求めたのか伺いたいと思います。きちんと説明をいただきたいと思います。そして、この会議の場になぜ企画部が参加したのか、企画部の出席を求めた人は誰なのか、自分で参加したのか、それとも誰かに指示されて出席したのか、そこをご説明いただきたいと思います。","respondent":"佐藤計画担当課長、立木保育課長","answer":"答弁が繰り返しになってしまうかもしれませんけれども、私としては客観的な立場から、今後どうしていくかということに対して、企画部の管理職として意見を申し上げたところです。これは理由としましては、先ほど計画担当課長からお話がありましたとおり、区の全体の調整という形で企画部がありますので、そうしたところの意見をしっかり取り入れて検討していくためということで、参加していただいた次第です。","voiceIndex":343,"id":"exchange-148"},{"speaker":"中塚委員","kind":"質問・要望","question":"課長が言う、企画部としての客観的な立場として意見を述べていると言っている意味が、結局は、区の行政改革の路線で閉園を求めていくということにつながってくると私は思います。子どもの施設への投資は未来への投資です。社会が回っていきません。そして、子どもの施設にまで財政効率を求めるのはやめるべきだと、こうした行政改革路線は転換すべきだと思いますが、いかがでしょうか。","respondent":"立木保育課長","answer":"今回の伊藤幼稚園の件につきましては、閉園ということが１つ出ておりますが、それ以前に、区の今後の区立幼稚園のあり方ということで検討を進めてまいりました。これから、ゼロ歳から就学前までの一貫した保育教育ということで、幼保一体施設のほうを充実させていく。","voiceIndex":346,"id":"exchange-149"},{"speaker":"中塚委員","kind":"質問・要望","question":"今の答弁は、この間の経過を述べているだけなのです。私が伺っているのは、区民税や財調交付金も増えている。さらには新たに基金まで積み増すほどの余裕がある。これがこの決算で明らかになりました。この下で、なぜ子どもの施設にまで財政効率を求めるのかと伺いました。入るお金も増えている。なぜ子どもの施設にまで財政効率を求めるのか。この姿勢は改めるべきだと思いますけれども、いかがでしょうか。","respondent":"佐藤計画担当課長","answer":"冒頭申し上げたとおり、区のこの事業に限らずですけれども、限られた財源に対して効率的な事業を行うということで進めておりますので、本件会議に出席した際も、今通っているお子さんについての経費についてはお答えいただいておりますし。","voiceIndex":348,"id":"exchange-150"},{"speaker":"中塚委員","kind":"質問・要望","question":"限られた財源という言い方で、子どもにまで例外を認めない。こうした効率優先の運営は誤りだと思います。子どもへの投資は未来への投資です。目先の利益ばかりを追うのではなく、次の世代をつくっていく未来への投資なのです。効率化の名前で、伊藤幼稚園を含めて、子どもの施設にまで廃園を求めていく。抜本的な転換を強く求めて質問を終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":350,"id":"exchange-151"},{"speaker":"塚本委員","kind":"質問","question":"お聞きしたいのは、先ほどから出ている、１０％の区民の方、納税義務者が７００万円以上の年収をお持ちで、税額全体の４割を占めているという状況なわけですけれども、こういった納税者の分布というのですか、偏りというのか、こういった状況というのが、いわゆるコロナ禍を通じて貧富の格差みたいなものの拡大ということにつながっているようなことというのは。","respondent":"提坂税務課長","answer":"所得の分布の偏りというのですか、それについては、コロナ禍で始まったということではなくて、コロナ禍前からこの傾向は見えてきたのかなと考えます。","voiceIndex":352,"id":"exchange-152"},{"speaker":"塚本委員","kind":"質問・要望","question":"水とか教育とか雇用とか、こういったことを社会としてきっちり支えていくといった考え方から、それを発展させてベーシックサービスという考え方が今出てきているということなのですけれども、このベーシックサービスについての区の認識、また評価というのをお聞きしたいのですが、それとあわせてベーシックサービスというものが、いわゆる品川区の今やっている事業の中でふさわしいというのですか。","respondent":"佐藤企画調整課長","answer":"今後もそういった社会状況を見ながら、区として質素倹約で財政基盤はしっかりしておりますので、そういったものを使いながら進めていきたいと考えております。","voiceIndex":354,"id":"exchange-153"},{"speaker":"塚本委員","kind":"意見","question":"こういった点も含めて、今後の品川区の１つの社会保障、品川区ができる社会保障という部分での施策として、このベーシックサービスの考え方について、改めてご答弁をお願いしたいと思います。","respondent":"佐藤企画調整課長","answer":"委員から様々なご提案をいただきました。区では今現在、重層的支援体制整備というところで、福祉部が中心となりまして、相談体制の充実について検討しているところです。","voiceIndex":356,"id":"exchange-154"},{"speaker":"塚本委員","kind":"意見","question":"これは今後もいろいろと先の長い話であるかと思いますので、よろしくお願いしたいと思います。最後に、あまりお時間がないので１つだけ、使用料及び手数料で、今、キャッシュレス決済で使用しているアプリというのが幾つかあるかと思います。決済キャリアですね。今後どういう考え方で、こういった決済アプリを広げていくというふうに考えているのか、一言お願いいたします。","respondent":"宮澤情報推進課長","answer":"現在、窓口で手数料や使用料のキャッシュレス決済というのを行っております。キャッシュレスのブランドにつきましては、ＱＲコードであったりクレジットであったり電子マネーということで、様々なブランドを用意して区民の利便性を向上させているです。","voiceIndex":358,"id":"exchange-155"},{"speaker":"湯澤委員","kind":"質問・要望","question":"私からは、歳入全般についてご質問します。新型コロナウイルスが区内に蔓延してから間もなく３年がたとうとしています。品川区の見通しでは、令和２６年でしょうか、そこまでは人口が増え続けて、そこをピークに人口減少としていますけれども、午後の質疑の中でもありましたが、現在、コロナ禍で転出が増えているというご答弁もありました。区内企業の転入出についてもあわせてお知らせください。","respondent":"佐藤計画担当課長","answer":"夜間人口を１００とした割合でいきますと、１３７.８という数字になっております。","voiceIndex":361,"id":"exchange-156"},{"speaker":"湯澤委員","kind":"質問・要望","question":"区内全体についての人口をお知らせいただきたかったのですけれども、そちらはいかがでしょうか。いいです。分かりました。やはり、人口の減少や、事業所についても減少していくことは、区政運営について大きな影響を与えると考えています。現在、区が魅力発信として行っている取組と、取組に対して何か感触があればお知らせいただきたいと思います。","respondent":"篠田文化観光課長","answer":"今、国内外に対してですので、観光的な視点で申し上げますと、私どもも、インバウンドが落ち込んでいる中でも毎年、インターネット等を通じまして、基本的にはアジアを中心としてですけれども、様々な形で情報発信をして。","voiceIndex":363,"id":"exchange-157"},{"speaker":"湯澤委員","kind":"質問・要望","question":"それで、品川区に訪れたい、そして住みたいと思ってくれる人が増えればいいなと考えています。税外収入の確保として、クラウドファンディングやネーミングライツ等の活用について検討しているという区の方針が、毎年、依命通達でうたわれていると思うのですけれども、現在はどのような検討をされているのか、これまでの実績とともに教えていただければと思います。","respondent":"黒田財政課長","answer":"いわゆる税外収入の確保というところで、毎度、依命通達でも、税外収入の確保についてということは依命通達の中であるわけですが、クラウドファンティングにつきましては、子どもの食の支援というところでクラウドファンディングも行っておりますし、令和３年度につきましては。","voiceIndex":365,"id":"exchange-158"},{"speaker":"湯澤委員","kind":"提案","question":"ふるさと納税につきましては、先ほど芹澤委員から流出の軽減の提案をさせていただきましたし、またクラウドファンディング、ネーミングライツのさらなる活用を検討していただきたいと要望いたします。ネーミングライツに関しては、区のホームページなどでも募ってはいかがかと思いますが、いかがでしょうか。","respondent":"黒田財政課長","answer":"ネーミングライツは、様々活用している自治体があることは承知しておりますけれども、継続的に税外収入として確保できる安定的な税収となるという観点も１つでございまして、また一方で、小さなところでも、こつこつと申しましょうか、確保していくというところも重要ですので。","voiceIndex":367,"id":"exchange-159"},{"speaker":"湯澤委員","kind":"質問・要望","question":"こつこつというお話がありましたけれども、我が会派からも、これまでも要望させていただいておりましたが、ぜひ今だからこそ、こつこつと、そういったところも取り組んでいただきたいと考えています。特に区民プールなどはどうなのでしょうか。できればこれは上げてほしくないと思うのですけれども、区民使用料などは上げてほしくないと考えていますが、いかがでしょうか。","respondent":"黒田財政課長","answer":"いわゆる使用料につきましては、要はそれにかかる経費について一定程度ご負担いただくというところで算出していますが、今、一時的な物価高騰に対して、すぐに使用料を上げるというところで検討を進めているものではございません。","voiceIndex":369,"id":"exchange-160"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1516#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":118437,"voices":371}}]);
